package com.runealytics;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Tracks the depth (pending task count) of thread pool executor queues.
 *
 * <p>Monitors task submission rates and queue depth to detect executor
 * overload or thread starvation. High queue depth indicates tasks are
 * being submitted faster than they can execute.</p>
 *
 * <p>Only works with ThreadPoolExecutor (not ScheduledExecutorService directly),
 * so may not be available for all executor types.</p>
 */
@Slf4j
public class AsyncQueueDepthTracker
{
    private static final long QUEUE_DEPTH_CHECK_INTERVAL_MS = 30_000; // Check every 30 seconds
    private static final int QUEUE_DEPTH_WARNING_THRESHOLD = 50; // Warn if > 50 pending

    private final ThreadPoolExecutor executor;
    private final String executorName;
    private volatile long lastCheckMs = System.currentTimeMillis();
    private final AtomicLong peakQueueDepth = new AtomicLong(0);
    private final AtomicLong totalTasksSubmitted = new AtomicLong(0);
    private final AtomicLong totalTasksCompleted = new AtomicLong(0);

    public AsyncQueueDepthTracker(ThreadPoolExecutor executor, String executorName)
    {
        this.executor = executor;
        this.executorName = executorName;
    }

    /**
     * Records a task submission. Call this after submitting a task to the executor.
     */
    public void recordSubmission()
    {
        totalTasksSubmitted.incrementAndGet();
        checkQueueDepth();
    }

    /**
     * Records task completion. Call this in task finally blocks.
     */
    public void recordCompletion()
    {
        totalTasksCompleted.incrementAndGet();
    }

    /**
     * Checks current queue depth and logs warning if threshold exceeded.
     */
    private void checkQueueDepth()
    {
        if (executor == null || executor.isShutdown()) return;

        int queueSize = executor.getQueue().size();
        long now = System.currentTimeMillis();

        // Update peak
        long peak = peakQueueDepth.get();
        while (queueSize > peak && !peakQueueDepth.compareAndSet(peak, queueSize))
        {
            peak = peakQueueDepth.get();
        }

        // Check interval - only log periodically
        if (now - lastCheckMs > QUEUE_DEPTH_CHECK_INTERVAL_MS)
        {
            lastCheckMs = now;

            long submitted = totalTasksSubmitted.get();
            long completed = totalTasksCompleted.get();
            long pending = submitted - completed;

            log.debug("[queue] {} executor depth: queue={} active={} peak={} submitted={} completed={} pending={}",
                executorName, queueSize, executor.getActiveCount(), peakQueueDepth.get(),
                submitted, completed, pending);

            if (queueSize > QUEUE_DEPTH_WARNING_THRESHOLD)
            {
                log.debug("[queue] {} executor queue is building up: {} pending tasks " +
                    "(> {} threshold). Check for executor starvation or slow tasks.",
                    executorName, queueSize, QUEUE_DEPTH_WARNING_THRESHOLD);
            }
        }
    }

    /**
     * @return current queue depth (number of pending tasks)
     */
    public int getQueueDepth()
    {
        return executor != null ? executor.getQueue().size() : 0;
    }

    /**
     * @return current number of active (executing) threads
     */
    public int getActiveThreadCount()
    {
        return executor != null ? executor.getActiveCount() : 0;
    }

    /**
     * @return peak queue depth observed since tracking started
     */
    public long getPeakQueueDepth()
    {
        return peakQueueDepth.get();
    }

    /**
     * @return total tasks submitted to executor
     */
    public long getTotalSubmitted()
    {
        return totalTasksSubmitted.get();
    }

    /**
     * @return total tasks completed by executor
     */
    public long getTotalCompleted()
    {
        return totalTasksCompleted.get();
    }

    /**
     * @return pending tasks (submitted - completed)
     */
    public long getPendingTasks()
    {
        return totalTasksSubmitted.get() - totalTasksCompleted.get();
    }

    /**
     * Resets all statistics. Useful for testing or after diagnostic output.
     */
    public void reset()
    {
        peakQueueDepth.set(0);
        totalTasksSubmitted.set(0);
        totalTasksCompleted.set(0);
        lastCheckMs = System.currentTimeMillis();
        log.debug("[queue] {} executor tracking reset", executorName);
    }
}

package com.runealytics;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;

@Singleton
public class BankDataManager
{
    private static final Logger log = LoggerFactory.getLogger(BankDataManager.class);

    private final RunealyticsApiClient apiClient;
    private final ItemManager itemManager;

    @Inject
    public BankDataManager(RunealyticsApiClient apiClient, ItemManager itemManager)
    {
        this.apiClient   = apiClient;
        this.itemManager = itemManager;
    }

    /**
     * Builds the complete wealth snapshot JSON object on the <strong>client
     * thread</strong>.  This method calls {@link ItemManager#getItemComposition}
     * internally, which requires the client thread — it must NOT be called from
     * a background executor.
     *
     * <p>Call this synchronously, then hand the returned {@link JsonObject} to
     * {@link #syncBankData(String, String, JsonObject)} running on an executor
     * thread for the actual HTTP call.</p>
     *
     * @param username           verified RSN (added to the JSON payload)
     * @param world              the current world (captured on the client thread)
     * @param bankContainer      InventoryID.BANK container (required)
     * @param inventoryContainer InventoryID.INVENTORY container (may be null)
     * @param equipmentContainer InventoryID.EQUIPMENT container (may be null)
     * @return pre-serialised JSON ready to pass to the network call
     */
    public JsonObject buildBankSnapshot(
            String username,
            int world,
            ItemContainer bankContainer,
            ItemContainer inventoryContainer,
            ItemContainer equipmentContainer)
    {
        JsonObject data = new JsonObject();
        data.addProperty("username",  username);
        data.addProperty("timestamp", Instant.now().getEpochSecond());
        data.addProperty("world",     world);

        // fromContainerWithValues / containerTotalValue both call
        // ItemManager.getItemComposition which requires the client thread.
        JsonArray bankItems      = RuneAlyticsItemJson.fromContainerWithValues(bankContainer,      itemManager);
        JsonArray inventoryItems = RuneAlyticsItemJson.fromContainerWithValues(inventoryContainer, itemManager);
        JsonArray equipmentItems = RuneAlyticsItemJson.fromContainerWithValues(equipmentContainer, itemManager);

        data.add("items",     bankItems);
        data.add("inventory", inventoryItems);
        data.add("equipment", equipmentItems);

        long bankValue  = RuneAlyticsItemJson.containerTotalValue(bankContainer,      itemManager);
        long invValue   = RuneAlyticsItemJson.containerTotalValue(inventoryContainer, itemManager);
        long equipValue = RuneAlyticsItemJson.containerTotalValue(equipmentContainer, itemManager);
        long total      = bankValue + invValue + equipValue;

        data.addProperty("bank_value",      bankValue);
        data.addProperty("inventory_value", invValue);
        data.addProperty("equipment_value", equipValue);
        data.addProperty("total_wealth",    total);

        log.debug("Wealth snapshot built: bank={} ({}gp) inv={} ({}gp) equip={} ({}gp) total={}gp",
                bankItems.size(),      bankValue,
                inventoryItems.size(), invValue,
                equipmentItems.size(), equipValue,
                total);

        return data;
    }

    /**
     * Sends a pre-built wealth snapshot to the API.  Safe to call from a
     * background thread — all client API reads were already done by
     * {@link #buildBankSnapshot}.
     */
    public void syncBankData(String token, String username, JsonObject snapshot)
    {
        if (token == null || token.isEmpty())
        {
            log.debug("No auth token available, skipping bank sync");
            return;
        }

        if (username == null || username.isEmpty())
        {
            log.debug("Username is null/empty, skipping bank sync");
            return;
        }

        if (snapshot == null)
        {
            log.debug("Bank snapshot is null, skipping bank sync");
            return;
        }

        try
        {
            boolean success = apiClient.syncBankData(token, snapshot);
            if (success)
            {
                log.debug("Wealth snapshot synced successfully for {}", username);
            }
            else
            {
                log.debug("Failed to sync wealth snapshot for {}", username);
            }
        }
        catch (Exception e)
        {
            log.debug("Error syncing wealth snapshot for {}: {}", username, e.getMessage(), e);
        }
    }

}

package com.runealytics;

import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
@Getter
@Setter
public class BossKillStats
{
    private String npcName;
    private int    npcId;
    private int    killCount;
    private int    prestige;
    private long   totalLootValue;
    private long   highestDrop;
    private List<LootStorageData.KillRecord> killHistory;

    private List<AggregatedDrop> preloadedDrops = new ArrayList<>();
    private boolean manualSync = false;

    public BossKillStats(String npcName, int npcId)
    {
        this.npcName      = npcName;
        this.npcId        = npcId;
        this.killCount    = 0;
        this.prestige     = 0;
        this.totalLootValue = 0;
        this.highestDrop  = 0;
        this.killHistory  = new ArrayList<>();
    }

    public void prestige()
    {
        this.prestige++;
        this.killCount      = 0;
        this.totalLootValue = 0;
        this.highestDrop    = 0;
        this.killHistory.clear();
        this.preloadedDrops.clear();
        log.debug("Boss {} prestiged to level {}", npcName, prestige);
    }

    public long getLastKillTimestamp()
    {
        if (killHistory == null || killHistory.isEmpty()) return 0L;
        return killHistory.get(killHistory.size() - 1).getTimestamp();
    }

    public void addKill(LootStorageData.KillRecord kill)
    {
        if (kill == null) return;

        killHistory.add(kill);
        this.killCount++;

        long killValue = 0;
        for (LootStorageData.DropRecord drop : kill.getDrops())
        {
            killValue += drop.getTotalValue();
            if (drop.getTotalValue() > highestDrop)
                highestDrop = drop.getTotalValue();
        }
        this.totalLootValue += killValue;
    }

    public void setPreloadedDrops(List<AggregatedDrop> drops)
    {
        this.preloadedDrops = drops != null ? new ArrayList<>(drops) : new ArrayList<>();
    }

    public List<AggregatedDrop> getAggregatedDrops()
    {
        Map<Integer, AggregatedDrop> aggregatedMap = new HashMap<>();

        for (LootStorageData.KillRecord kill : killHistory)
        {
            for (LootStorageData.DropRecord drop : kill.getDrops())
            {
                AggregatedDrop agg = aggregatedMap.computeIfAbsent(
                        drop.getItemId(),
                        id -> new AggregatedDrop(
                                drop.getItemId(), drop.getItemName(),
                                0, 0, 0,
                                drop.getGePrice(), drop.getHighAlch()));

                agg.totalQuantity += drop.getQuantity();
                agg.totalValue    += drop.getTotalValue();
                agg.dropCount++;
                if (drop.isPet()) agg.setPet(true);
            }
        }

        List<AggregatedDrop> result = new ArrayList<>(aggregatedMap.values());

        if (result.isEmpty() && preloadedDrops != null && !preloadedDrops.isEmpty())
        {
            if (manualSync)
                log.debug("{}: using {} preloaded drops", npcName, preloadedDrops.size());
            return new ArrayList<>(preloadedDrops);
        }

        return result;
    }

    public List<AggregatedDrop> getAggregatedDropsSorted()
    {
        List<AggregatedDrop> drops = getAggregatedDrops();
        drops.sort((a, b) -> {
            // Pets always sort to slot #1 regardless of GE value
            if (a.isPet() != b.isPet()) return a.isPet() ? -1 : 1;
            return Long.compare(b.getTotalValue(), a.getTotalValue());
        });
        return drops;
    }

    @Getter
    @Setter
    public static class AggregatedDrop
    {
        private int     itemId;
        private String  itemName;
        private int     totalQuantity;
        private long    totalValue;
        private int     dropCount;
        private long    gePrice;
        private long    highAlchValue;
        private boolean pet;
        /**
         * True for non-tradeable items (quest rewards, untradeable cosmetics,
         * pets). Used by the panel sort to place untradeables first regardless
         * of their GE value, which is often 0.
         */
        private boolean untradeable;

        public AggregatedDrop(int itemId, String itemName,
                              int totalQuantity, long totalValue, int dropCount,
                              long gePrice, long highAlchValue)
        {
            this.itemId        = itemId;
            this.itemName      = itemName;
            this.totalQuantity = totalQuantity;
            this.totalValue    = totalValue;
            this.dropCount     = dropCount;
            this.gePrice       = gePrice;
            this.highAlchValue = highAlchValue;
            this.pet           = false;
            this.untradeable   = false;
        }
    }
}

package com.runealytics;

import java.util.regex.Pattern;

/**
 * Pure, dependency-free boss / loot-source name canonicalisation.
 *
 * <p>Extracted from {@code LootTrackerManager} so the mapping can be used by
 * components that must stay free of client dependencies (e.g.
 * {@link KillCountResolver}) and unit-tested in isolation. This is the seed of
 * the future data-driven {@code EncounterRegistry}: every variant NPC, chat,
 * or widget name funnels through here to one canonical storage key.</p>
 *
 * <p>{@code LootTrackerManager.normalizeBossName} delegates to
 * {@link #normalize(String)} — behaviour is identical for all existing
 * callers.</p>
 */
public final class BossNames
{
    private BossNames() {}

    /** Prefix marking thieving/pickpocket sources; must pass through unchanged. */
    static final String PICKPOCKET_PREFIX = "Pickpocket: ";

    private static final Pattern COLOR_TAG_PATTERN =
            Pattern.compile("</?col[^>]*>", Pattern.CASE_INSENSITIVE);

    /**
     * Strips RuneScape chat-message colour markup (e.g. {@code <col=00ffff>...</col>})
     * that occasionally leaks into an NPC's display name for certain reflected /
     * phase-variant monsters.
     */
    public static String stripColorTags(String raw)
    {
        return raw == null ? null : COLOR_TAG_PATTERN.matcher(raw).replaceAll("");
    }

    /**
     * Maps variant NPC / source names to a single canonical display name.
     *
     * <p>Pickpocket-prefixed names pass through unchanged so that stored
     * thieving entries survive across normalisation calls.</p>
     *
     * @param raw raw name from NPC, widget, or chat
     * @return canonical name, never null
     */
    public static String normalize(String raw)
    {
        if (raw == null || raw.isEmpty()) return "Unknown";

        raw = stripColorTags(raw).trim();
        if (raw.isEmpty()) return "Unknown";

        // Pass through already-prefixed pickpocket entries unchanged
        if (raw.startsWith(PICKPOCKET_PREFIX)) return raw;

        String l = raw.toLowerCase();

        // Most specific names first, then progressively broader matches
        if (l.contains("doom of mokhaiotl"))              return "Doom of Mokhaiotl";
        if (l.contains("corrupted gauntlet"))             return "Corrupted Gauntlet";
        if (l.contains("chambers") || l.contains("cox"))  return "Chambers of Xeric";
        if (l.contains("theatre") || l.contains("tob"))   return "Theatre of Blood";
        if (l.contains("tombs") || l.contains("toa"))     return "Tombs of Amascut";
        if (l.contains("gauntlet"))                       return "The Gauntlet";

        if (l.contains("zilyana"))                        return "Commander Zilyana";
        if (l.contains("graardor"))                       return "General Graardor";
        if (l.contains("kree"))                           return "Kree'arra";
        if (l.contains("kril"))                           return "K'ril Tsutsaroth";
        if (l.equals("nex"))                              return "Nex";

        if (l.contains("artio"))                          return "Artio";
        if (l.contains("callisto"))                       return "Callisto";
        if (l.contains("calvar"))                         return "Calvar'ion";
        if (l.contains("vet'ion") || l.contains("vetion")) return "Vet'ion";
        if (l.contains("spindel"))                        return "Spindel";
        if (l.contains("venenatis"))                      return "Venenatis";
        if (l.contains("corporeal"))                      return "Corporeal Beast";
        if (l.contains("chaos fanatic"))                  return "Chaos Fanatic";
        if (l.contains("scorpia"))                        return "Scorpia";
        if (l.contains("crazy archaeologist"))            return "Crazy Archaeologist";

        if (l.contains("duke") || l.contains("sucellus")) return "Duke Sucellus";
        if (l.contains("leviathan"))                      return "The Leviathan";
        if (l.contains("vardorvis"))                      return "Vardorvis";
        if (l.contains("whisperer"))                      return "The Whisperer";

        if (l.contains("royal titans") || l.contains("eldric") || l.contains("branda"))
            return "Royal Titans";
        if (l.contains("hueycoatl"))                      return "The Hueycoatl";
        // Check full phrase first before multi-part checks
        if (l.contains("moons of peril") || l.contains("blue moon")
                || l.contains("blood moon") || l.contains("eclipse moon")
                || l.contains("lunar chest") || l.equals("lunar"))
            return "Moons of Peril";
        if (l.contains("muspah"))                         return "Phantom Muspah";
        if (l.contains("yama"))                           return "Yama";
        if (l.contains("araxxor"))                        return "Araxxor";
        if (l.contains("scurrius"))                       return "Scurrius";
        if (l.contains("amoxliatl"))                      return "Amoxliatl";
        if (l.contains("tormented demon"))                return "Tormented Demon";
        if (l.contains("colosseum") || l.contains("fortis"))
            return "Fortis Colosseum";

        if (l.contains("zulrah"))                         return "Zulrah";
        if (l.contains("vorkath"))                        return "Vorkath";
        if (l.contains("hydra"))                          return "Alchemical Hydra";
        if (l.contains("cerberus"))                       return "Cerberus";
        if (l.contains("abyssal sire"))                   return "Abyssal Sire";
        if (l.contains("kraken"))                         return "Kraken";
        if (l.contains("smoke devil") || l.contains("thermonuclear")) return "Smoke Devil";
        if (l.contains("phosani"))                        return "Phosani's Nightmare";
        if (l.contains("nightmare"))                      return "The Nightmare";
        if (l.contains("grotesque"))                      return "Grotesque Guardians";
        if (l.contains("kalphite queen"))                 return "Kalphite Queen";
        if (l.contains("kbd") || l.contains("king black dragon")) return "King Black Dragon";
        if (l.contains("dagannoth prime"))                return "Dagannoth Prime";
        if (l.contains("dagannoth rex"))                  return "Dagannoth Rex";
        if (l.contains("dagannoth supreme"))              return "Dagannoth Supreme";
        if (l.contains("skotizo"))                        return "Skotizo";
        if (l.contains("hespori"))                        return "Hespori";

        if (l.contains("barrows"))                        return "Barrows";
        if (l.contains("tempoross"))                      return "Tempoross";
        if (l.contains("wintertodt"))                     return "Wintertodt";
        if (l.contains("zalcano"))                        return "Zalcano";

        // Exact phrase first, then split-word fallback for "Clue scroll (hard)"
        // style names where the tier and "clue" are not adjacent.
        if (l.contains("beginner clue") || (l.contains("beginner") && l.contains("clue")))
            return "Beginner Clue";
        if (l.contains("easy clue") || (l.contains("easy") && l.contains("clue")))
            return "Easy Clue";
        if (l.contains("medium clue") || (l.contains("medium") && l.contains("clue")))
            return "Medium Clue";
        if (l.contains("hard clue") || (l.contains("hard") && l.contains("clue")))
            return "Hard Clue";
        if (l.contains("elite clue") || (l.contains("elite") && l.contains("clue")))
            return "Elite Clue";
        if (l.contains("master clue") || (l.contains("master") && l.contains("clue")))
            return "Master Clue";

        return raw.trim();
    }
}

package com.runealytics;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.Getter;
import lombok.Setter;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Represents the current clan state for a player.
 * Thread-safe using ConcurrentHashMap for member list.
 * Lightweight snapshots to avoid data bloom.
 */
@Getter
@Setter
public class ClanInfo
{
    /** Clan name (e.g., "Legends") */
    private String clanName;

    /** Clan tag (e.g., "<tag>") if available */
    private String clanTag;

    /** Clan ID from RuneScape (if obtainable) */
    private Integer clanId;

    /** Player's rank in the clan */
    private String playerRank;

    /** Map of member username → ClanMember; concurrent-safe */
    private final Map<String, ClanMember> members = new ConcurrentHashMap<>();

    /** Unix timestamp when this clan was first joined */
    private long joinedAt;

    /** Unix timestamp of last update to this clan info */
    private long lastUpdateAt;

    /** Unix timestamp of last time members list was synced to server */
    private volatile long lastSyncAt;

    /**
     * Constructs a new clan snapshot.
     */
    public ClanInfo(String clanName)
    {
        this.clanName = clanName;
        this.joinedAt = System.currentTimeMillis() / 1000;
        this.lastUpdateAt = this.joinedAt;
        this.lastSyncAt = 0; // not yet synced
    }

    /**
     * Adds or updates a member in the clan.
     * If member exists, updates last-seen; if new, records join time.
     */
    public void upsertMember(String username, boolean isTracked)
    {
        members.computeIfAbsent(username, u ->
            new ClanMember(u, System.currentTimeMillis() / 1000, isTracked)
        ).updateLastSeen();
        this.lastUpdateAt = System.currentTimeMillis() / 1000;
    }

    /**
     * Remove a member from tracking (when they leave the clan).
     */
    public void removeMember(String username)
    {
        members.remove(username);
        this.lastUpdateAt = System.currentTimeMillis() / 1000;
    }

    /**
     * Gets a snapshot of members for serialization.
     * Creates a copy to avoid concurrent modification during iteration.
     */
    public List<ClanMember> getMemberSnapshot()
    {
        return new ArrayList<>(members.values());
    }

    /**
     * Gets member count. Safe for concurrent access.
     */
    public int getMemberCount()
    {
        return members.size();
    }

    /**
     * Checks if we know of a member.
     */
    public boolean hasMember(String username)
    {
        return members.containsKey(username);
    }

    /**
     * Converts to JSON for network transmission.
     * Includes only essential fields and member count (not full member list).
     * Full member list sent separately via syncClanMembers() to the /plugin/clan/members endpoint.
     */
    public JsonObject toJson()
    {
        JsonObject obj = new JsonObject();
        obj.addProperty("clan_name",     clanName != null ? clanName : "");
        obj.addProperty("clan_tag",      clanTag != null ? clanTag : "");
        obj.addProperty("player_rank",   playerRank != null ? playerRank : "member");
        obj.addProperty("member_count",  members.size());
        obj.addProperty("joined_at",     joinedAt);
        obj.addProperty("last_update",   lastUpdateAt);
        if (clanId != null)
        {
            obj.addProperty("clan_id", clanId);
        }
        return obj;
    }

    /**
     * Converts member list to JSON array for member sync endpoint.
     * Called separately to avoid oversized heartbeat payloads.
     */
    public JsonArray membersToJsonArray()
    {
        JsonArray arr = new JsonArray();
        for (ClanMember member : getMemberSnapshot())
        {
            arr.add(member.toJson());
        }
        return arr;
    }

    /**
     * Checks if the clan data has been modified since last sync.
     */
    public boolean isDirty()
    {
        return lastUpdateAt > lastSyncAt;
    }
}

package com.runealytics;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Manages clan membership and auto-detection.
 *
 * Tracks:
 * - Current clan membership
 * - Member list from clan chat
 * - Automatic detection when player joins/leaves clan
 *
 * Thread-safe: accepts updates from game thread, readable from any thread.
 */
@Slf4j
@Singleton
@Getter
public class ClanManager
{
    /** Current clan info (null when not in a clan) */
    private volatile ClanInfo currentClan;

    /** List of observers notified when clan state changes */
    private final List<ClanUpdateListener> listeners = new CopyOnWriteArrayList<>();

    public interface ClanUpdateListener
    {
        void onClanJoined(ClanInfo clan);
        void onClanLeft();
        void onMembersUpdated(ClanInfo clan);
    }

    /**
     * Register a listener for clan state changes.
     */
    public void addListener(ClanUpdateListener listener)
    {
        listeners.add(listener);
    }

    /**
     * Called when player joins a clan.
     * Initializes or updates the clan state.
     */
    public void onClanJoined(String clanName, String clanTag)
    {
        if (currentClan != null && currentClan.getClanName().equalsIgnoreCase(clanName))
        {
            log.debug("[Clan] Already in clan: {}", clanName);
            return;
        }

        ClanInfo newClan = new ClanInfo(clanName);
        if (clanTag != null && !clanTag.isEmpty())
        {
            newClan.setClanTag(clanTag);
        }
        currentClan = newClan;

        log.debug("[Clan] Joined clan: {} tag={}", clanName, clanTag != null ? clanTag : "none");
        listeners.forEach(l -> l.onClanJoined(newClan));
    }

    /**
     * Called when player leaves the clan (logout or manual leave).
     */
    public void onClanLeft()
    {
        if (currentClan == null)
        {
            return;
        }

        log.debug("[Clan] Left clan: {}", currentClan.getClanName());
        currentClan = null;
        listeners.forEach(ClanUpdateListener::onClanLeft);
    }

    /**
     * Adds or updates a member in the current clan.
     * Called when member appears in clan chat or member list.
     *
     * @param username player's RSN
     * @param isTracked whether this player uses RuneAlytics (plugin)
     */
    public void recordMember(String username, boolean isTracked)
    {
        if (currentClan == null)
        {
            return;
        }

        currentClan.upsertMember(username, isTracked);
        log.debug("[Clan] Member recorded: {} tracked={}", username, isTracked);
    }

    /**
     * Parses clan member list from clan chat widget.
     * This is called when the player opens the member list UI.
     *
     * @param members list of usernames in the clan
     */
    public void updateMemberList(List<String> members)
    {
        if (currentClan == null || members == null || members.isEmpty())
        {
            return;
        }

        // Add any new members
        for (String username : members)
        {
            currentClan.upsertMember(username, false); // can't determine if tracked from UI alone
        }

        log.debug("[Clan] Member list updated: {} members", members.size());
        listeners.forEach(l -> l.onMembersUpdated(currentClan));
    }

    /**
     * Marks the current clan as having been synced to the server.
     * Prevents unnecessary re-sends of unchanged data.
     */
    public void markSynced()
    {
        if (currentClan != null)
        {
            currentClan.setLastSyncAt(System.currentTimeMillis() / 1000);
            log.debug("[Clan] Marked synced: {}", currentClan.getClanName());
        }
    }

    /**
     * Checks if current clan data is dirty (needs sync to server).
     */
    public boolean hasDirtyData()
    {
        return currentClan != null && currentClan.isDirty();
    }

    /**
     * Reset clan state (called on logout).
     */
    public void reset()
    {
        currentClan = null;
    }

    /**
     * Gets a safe snapshot of clan members for serialization.
     */
    public List<ClanMember> getMemberSnapshot()
    {
        if (currentClan == null)
        {
            return Collections.emptyList();
        }
        return currentClan.getMemberSnapshot();
    }

    /**
     * Gets member count (or 0 if not in clan).
     */
    public int getMemberCount()
    {
        return currentClan != null ? currentClan.getMemberCount() : 0;
    }
}

package com.runealytics;

import com.google.gson.JsonObject;
import lombok.Getter;

/**
 * Represents a single clan member snapshot.
 * Lightweight to avoid overhead during large clan updates.
 */
@Getter
public class ClanMember
{
    /** Player's OSRS username */
    private final String username;

    /** Unix timestamp when this member was first observed in the clan */
    private final long joinedAt;

    /** Unix timestamp of last known activity in the clan */
    private long lastSeenAt;

    /** Whether the player is tracked by RuneAlytics (using the plugin) */
    private final boolean isTracked;

    /** Member's rank in the clan (if available from clan chat) */
    private String rank;

    public ClanMember(String username, long joinedAt, boolean isTracked)
    {
        this.username = username;
        this.joinedAt = joinedAt;
        this.lastSeenAt = System.currentTimeMillis() / 1000;
        this.isTracked = isTracked;
        this.rank = "member"; // default
    }

    public void updateLastSeen()
    {
        this.lastSeenAt = System.currentTimeMillis() / 1000;
    }

    public void setRank(String rank)
    {
        this.rank = rank;
    }

    /**
     * Converts to JSON for network transmission.
     * Only sends essential data to minimize payload size.
     */
    public JsonObject toJson()
    {
        JsonObject obj = new JsonObject();
        obj.addProperty("username",   username);
        obj.addProperty("rank",       rank);
        obj.addProperty("joined_at",  joinedAt);
        obj.addProperty("last_seen",  lastSeenAt);
        obj.addProperty("is_tracked", isTracked);
        return obj;
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Resolves and guards the current RuneScape account identity for all loot
 * sync operations.
 *
 * <h2>Responsibilities</h2>
 * <ol>
 *   <li>Determine the current RuneScape display name from the RuneLite client.</li>
 *   <li>Normalize the username consistently (trim, remove non-breaking spaces,
 *       lowercase, collapse internal whitespace).</li>
 *   <li>Compare the in-client name against the RuneAlytics verified/linked
 *       account so that a mismatch blocks sync before any data is written.</li>
 *   <li>Provide a stable {@link #getAccountKey()} used as the storage key for
 *       all local loot caches, API snapshot requests, and upload payloads.</li>
 *   <li>Reset when the client logs out or switches accounts.</li>
 * </ol>
 *
 * <h2>Account-mismatch guard</h2>
 * <p>If RuneAlytics is verified/linked to account "Chris123" but the RuneLite
 * client is currently logged into "IronMain", {@link #canSync()} returns
 * {@code false} and {@link #getMismatchMessage()} describes exactly which
 * accounts collide.  No loot is read, merged, or uploaded until the mismatch
 * is resolved.</p>
 *
 * <h2>Normalization rules (must match PHP side)</h2>
 * <ul>
 *   <li>Replace non-breaking spaces (U+00A0) with regular spaces.</li>
 *   <li>{@code trim()} leading/trailing whitespace.</li>
 *   <li>Lowercase the entire string.</li>
 *   <li>Collapse multiple consecutive spaces to a single space.</li>
 * </ul>
 */
@Slf4j
@Singleton
public class CurrentPlayerIdentityService
{
    private final Client           client;
    private final RuneAlyticsState state;

    /**
     * The last non-null normalized account name observed while logged in.
     * Captured on the client thread via {@link #rememberCurrentPlayer()} so it
     * survives the logout transition (when {@code getLocalPlayer()} is already
     * null) and can scope a logout-time flush sync.
     */
    private volatile String lastKnownAccountKey;

    @Inject
    public CurrentPlayerIdentityService(Client client, RuneAlyticsState state)
    {
        this.client = client;
        this.state  = state;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /**
     * Returns the normalized display name of the currently logged-in
     * RuneScape account, or {@code null} if no player is available.
     */
    public String getCurrentNormalizedUsername()
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) return null;

        String name = localPlayer.getName();
        if (name == null || name.isEmpty()) return null;

        return normalizeUsername(name);
    }

    /**
     * Caches the current player's normalized name as the last-known account.
     *
     * <p>MUST be called on the client thread (reads live client state). Safe to
     * call repeatedly — it is a no-op when no player is rendered.</p>
     */
    public void rememberCurrentPlayer()
    {
        String current = getCurrentNormalizedUsername();
        if (current != null) lastKnownAccountKey = current;
    }

    /**
     * Returns the last account that was seen logged in, or {@code null} if none
     * has been observed this session. Useful for a logout flush, when the live
     * player is already gone.
     */
    public String getLastKnownAccountKey()
    {
        return lastKnownAccountKey;
    }

    /**
     * Returns {@code true} when {@code accountKey} is the RuneAlytics-linked
     * account (or when no account is linked yet). Used to guard a logout flush
     * against pushing one account's data under another's link.
     */
    public boolean isLinkedAccount(String accountKey)
    {
        if (accountKey == null) return false;
        String linkedName = getLinkedNormalizedUsername();
        return linkedName == null || linkedName.isEmpty() || linkedName.equals(accountKey);
    }

    /**
     * Returns the account key to be used for all per-account loot storage,
     * snapshot requests, and sync payloads.
     *
     * <p>This is the normalized username of the currently logged-in player.
     * Returns {@code null} if the player is not available (not logged in).</p>
     */
    public String getAccountKey()
    {
        return getCurrentNormalizedUsername();
    }

    /**
     * Returns {@code true} when loot sync is safe to proceed.
     *
     * <p>Sync is blocked when:</p>
     * <ul>
     *   <li>No player is logged in ({@code localPlayer == null}).</li>
     *   <li>The in-client player name is unavailable or empty.</li>
     *   <li>RuneAlytics is linked to a different account than the one
     *       currently logged in.</li>
     * </ul>
     */
    public boolean canSync()
    {
        String currentName = getCurrentNormalizedUsername();
        if (currentName == null)
        {
            log.debug("[identity] canSync=false: no local player / not logged in");
            return false;
        }

        String linkedName = getLinkedNormalizedUsername();
        if (linkedName != null && !linkedName.isEmpty() && !linkedName.equals(currentName))
        {
            log.debug("[identity] canSync=false: account mismatch — linked='{}' current='{}'",
                    linkedName, currentName);
            return false;
        }

        return true;
    }

    /**
     * Returns a human-readable explanation of why sync is blocked, or
     * {@code null} if sync is allowed.
     */
    public String getMismatchMessage()
    {
        String currentName = getCurrentNormalizedUsername();
        if (currentName == null)
        {
            return "Log into a RuneScape account before syncing loot.";
        }

        String linkedName = getLinkedNormalizedUsername();
        if (linkedName != null && !linkedName.isEmpty() && !linkedName.equals(currentName))
        {
            return "RuneAlytics is linked to \u2018" + linkedName
                    + "\u2019, but RuneLite is logged in as \u2018" + currentName
                    + "\u2019. Switch accounts or re-verify the plugin to sync loot.";
        }

        return null;
    }

    // ── Static helper (also used by LootSyncMergeService) ────────────────────

    /**
     * Normalizes a RuneScape display name to a stable, comparable key.
     *
     * <p>Rules (must match the PHP server-side normalization):</p>
     * <ol>
     *   <li>Replace non-breaking spaces (U+00A0) with regular spaces.</li>
     *   <li>Trim leading/trailing whitespace.</li>
     *   <li>Lowercase the entire string.</li>
     *   <li>Collapse multiple consecutive spaces to a single space.</li>
     * </ol>
     *
     * @param  name  raw display name, may be {@code null}
     * @return normalized name, or {@code null} if the input is {@code null}/empty
     */
    public static String normalizeUsername(String name)
    {
        if (name == null) return null;

        // Replace non-breaking space (U+00A0) with regular space.
        name = name.replace('\u00A0', ' ');

        name = name.trim();

        if (name.isEmpty()) return null;

        name = name.toLowerCase();

        // Collapse multiple spaces to one (e.g. "Iron  Man" → "iron man").
        name = name.replaceAll("\\s+", " ");

        return name;
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    /**
     * Returns the normalized username of the RuneAlytics verified/linked
     * account, sourced from {@link RuneAlyticsState#getVerifiedUsername()}.
     * Returns {@code null} when no account is linked.
     */
    private String getLinkedNormalizedUsername()
    {
        return normalizeUsername(state.getVerifiedUsername());
    }
}

package com.runealytics;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.function.LongSupplier;

/**
 * Guards loot recording against false positives during death-recovery events.
 *
 * <h2>Problem</h2>
 * <p>When a player dies and recovers items from a Gravestone or Death's Office,
 * the RuneLite event bus fires {@link ItemContainerChanged} and {@link ItemSpawned}
 * events that look identical to normal loot drops.  Without this guard every
 * piece of recovered gear would be counted as new boss loot.</p>
 *
 * <h2>Suppression window</h2>
 * <ol>
 *   <li>A death is detected via one of:
 *       <ul>
 *         <li>{@link ActorDeath} where the dying actor is the local player.</li>
 *         <li>A recognised death chat message (e.g. "Oh dear, you are dead!").</li>
 *         <li>The player entering the Death's Office region (8543).</li>
 *       </ul>
 *   </li>
 *   <li>Suppression lasts a minimum of {@value #DEATH_SUPPRESSION_MS} ms
 *       ({@value #DEATH_SUPPRESSION_MINUTES} minutes) from the death time.</li>
 *   <li>Suppression is extended while the player is in the Death's Office
 *       region or while a gravestone widget is open.</li>
 *   <li>Suppression ends when {@link #endRecoveryMode()} is called explicitly
 *       (UI "End Recovery Mode" button) or when the window expires and the
 *       player is no longer in a recovery region.</li>
 * </ol>
 *
 * <h2>Valid loot attribution requirement</h2>
 * <p>Callers should use {@link #shouldSuppressLootEvent()} before recording any
 * item gain that is NOT confirmed by a {@code LootReceived} event (i.e. any
 * item gain read from an inventory diff, ground item, or container change).
 * {@code LootReceived} events from the RuneLite bus are never suppressed
 * because they require a server-confirmed kill attribution.</p>
 *
 * <h2>Thread safety</h2>
 * <p>All state mutations in this class originate on the RuneLite client thread.
 * {@link #shouldSuppressLootEvent()} may be called from background sync threads
 * and reads {@code volatile} fields to ensure visibility.</p>
 */
@Slf4j
@Singleton
public class DeathRecoveryGuard
{
    // ── Region IDs for death-related areas ───────────────────────────────────

    /** Region ID of Death's Office / Death's Domain (OSRS). */
    private static final int REGION_DEATHS_OFFICE = 8543;

    /** A few neighbouring region IDs that may appear during the death cinematic. */
    private static final int REGION_DEATHS_OFFICE_ALT1 = 8799;
    private static final int REGION_DEATHS_OFFICE_ALT2 = 8544;

    // ── Widget IDs associated with gravestone / death storage ─────────────────

    /** Gravestone info/manage widget group. */
    private static final int WIDGET_GRAVESTONE   = 659;
    /** Death's coffer / office fee widget group. */
    private static final int WIDGET_DEATHS_COFFER = 4;

    // ── Timing ────────────────────────────────────────────────────────────────

    /** Minimum suppression duration after death, in milliseconds (5 minutes). */
    private static final long DEATH_SUPPRESSION_MS      = 5 * 60 * 1_000L;
    private static final int  DEATH_SUPPRESSION_MINUTES = 5;

    /**
     * Additional idle extension: if no recovery interaction occurs within this
     * window after the base suppression expires, recovery mode ends automatically.
     */
    private static final long IDLE_EXTENSION_MS = 60_000L;

    // ── Death/recovery chat messages to detect ────────────────────────────────

    private static final String DEATH_MESSAGE_OVERHEAD = "oh dear, you are dead!";
    private static final String DEATH_MESSAGE_IRONMAN  = "you have died.";
    private static final String GRAVESTONE_RECLAIM     = "your gravestone has been reclaimed";
    private static final String GRAVESTONE_COLLAPSED   = "your gravestone has collapsed";

    // ── Injected deps ─────────────────────────────────────────────────────────

    private final Client client;

    /**
     * Time source for all suppression-window arithmetic. Defaults to the system
     * clock in production; tests inject a controllable one for deterministic
     * boundary checks.
     */
    private final LongSupplier clock;

    // ── Mutable state (all written on client thread) ──────────────────────────

    /** Time at which the most recent death was detected (epoch ms), or 0. */
    private volatile long deathDetectedAt = 0L;

    /** True while the player is in a gravestone/death office recovery area. */
    private volatile boolean inRecoveryRegion = false;

    /** True while a gravestone/death UI widget is open. */
    private volatile boolean recoveryWidgetOpen = false;

    /** Time of the last recovery interaction, used for idle-extension logic. */
    private volatile long lastRecoveryInteractionAt = 0L;

    /** Running count of item-gain events suppressed this session. */
    @Getter
    private volatile int suppressedEventCount = 0;

    /** Locally recorded ignored items (for UI display). */
    private final List<IgnoredRecoveryItem> ignoredItems = new ArrayList<>();

    @Inject
    public DeathRecoveryGuard(Client client)
    {
        this(client, System::currentTimeMillis);
    }

    /**
     * Test seam: lets a unit test supply a deterministic time source. Production
     * always goes through the {@code @Inject} constructor above, which uses
     * {@link System#currentTimeMillis()}.
     */
    DeathRecoveryGuard(Client client, LongSupplier clock)
    {
        this.client = client;
        this.clock  = clock;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /**
     * Returns {@code true} when item-gain events should be ignored because the
     * player is likely recovering items from a gravestone or Death's Office.
     *
     * <p>Callers that already have a confirmed {@code LootReceived} RuneLite
     * event (with a valid source/NPC attribution) do NOT need to consult this
     * guard — those paths are always reliable.</p>
     */
    public boolean shouldSuppressLootEvent()
    {
        if (deathDetectedAt == 0L) return false;

        long now        = clock.getAsLong();
        long elapsed    = now - deathDetectedAt;
        boolean inWindow = elapsed < DEATH_SUPPRESSION_MS;
        boolean extended = inRecoveryRegion || recoveryWidgetOpen;

        // Allow idle-extension past the base window while actively recovering.
        if (!inWindow && extended)
        {
            // If the last recovery interaction was within the idle-extension
            // window, keep suppression active.
            inWindow = (now - lastRecoveryInteractionAt) < IDLE_EXTENSION_MS;
        }

        return inWindow;
    }

    /**
     * Returns {@code true} if recovery mode is currently active (death was
     * detected and the suppression window has not yet expired).
     */
    public boolean isRecovering()
    {
        return shouldSuppressLootEvent();
    }

    /**
     * Record an item pickup that was suppressed during recovery mode.
     * Used for UI display and optional audit upload.
     */
    public synchronized void recordIgnoredItem(int itemId, String itemName, int quantity, String reason)
    {
        suppressedEventCount++;
        ignoredItems.add(new IgnoredRecoveryItem(itemId, itemName, quantity, reason,
                Instant.now(), getCurrentRegionId()));

        log.debug("[death-guard] Ignored item during recovery: {} x{} — {}",
                itemName, quantity, reason);
    }

    /**
     * Explicitly ends recovery mode (called from UI "End Recovery Mode" button
     * or from {@link RuneAlyticsPlugin} when the player returns to a safe area).
     */
    public void endRecoveryMode()
    {
        log.debug("[death-guard] Recovery mode ended manually");
        deathDetectedAt = 0L;
        inRecoveryRegion = false;
        recoveryWidgetOpen = false;
    }

    /**
     * Resets the guard completely — called on plugin startup and account switch.
     */
    public synchronized void reset()
    {
        deathDetectedAt           = 0L;
        inRecoveryRegion          = false;
        recoveryWidgetOpen        = false;
        lastRecoveryInteractionAt = 0L;
        suppressedEventCount      = 0;
        ignoredItems.clear();
        log.debug("[death-guard] Guard reset");
    }

    /**
     * Returns an unmodifiable snapshot of all ignored recovery items this session.
     */
    public synchronized List<IgnoredRecoveryItem> getIgnoredItems()
    {
        return java.util.Collections.unmodifiableList(new ArrayList<>(ignoredItems));
    }

    // ── Event handlers (called by RuneAlyticsPlugin) ──────────────────────────

    /**
     * Called when an actor dies.  Triggers the suppression window if the dying
     * actor is the local player.
     */
    public void onActorDeath(ActorDeath event)
    {
        if (event.getActor() instanceof Player)
        {
            Player dying = (Player) event.getActor();
            Player local = client.getLocalPlayer();
            if (local != null && dying == local)
            {
                triggerDeath("ActorDeath event");
            }
        }
    }

    /**
     * Called for each chat message.  Detects death confirmation messages and
     * gravestone recovery notifications.
     */
    public void onChatMessage(ChatMessage event)
    {
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM) return;

        String msg = event.getMessage().toLowerCase()
                .replaceAll("<[^>]+>", "").trim();

        if (msg.contains(DEATH_MESSAGE_OVERHEAD) || msg.contains(DEATH_MESSAGE_IRONMAN))
        {
            triggerDeath("chat message: " + msg);
            return;
        }

        if (msg.contains(GRAVESTONE_RECLAIM) || msg.contains(GRAVESTONE_COLLAPSED))
        {
            markRecoveryInteraction("gravestone chat: " + msg);
        }
    }

    /**
     * Called when a widget loads.  Detects the gravestone management UI and
     * Death's Coffer widget.
     */
    public void onWidgetLoaded(WidgetLoaded event)
    {
        int group = event.getGroupId();
        if (group == WIDGET_GRAVESTONE || group == WIDGET_DEATHS_COFFER)
        {
            log.debug("[death-guard] Recovery widget loaded: group={}", group);
            recoveryWidgetOpen = true;
            markRecoveryInteraction("widget loaded: " + group);
        }
    }

    /**
     * Called every game tick.  Checks whether the player is currently in the
     * Death's Office region and extends suppression accordingly.
     */
    public void onGameTick()
    {
        int regionId = getCurrentRegionId();
        boolean wasInRegion = inRecoveryRegion;

        inRecoveryRegion = isDeathOfficeRegion(regionId);

        if (inRecoveryRegion && !wasInRegion)
        {
            log.debug("[death-guard] Entered Death's Office region ({})", regionId);
            if (deathDetectedAt == 0L)
            {
                // Player entered Death's Office without a detected death event.
                // Treat this as an implicit death trigger.
                triggerDeath("entered Death's Office region");
            }
            markRecoveryInteraction("Death's Office region entry");
        }
        else if (!inRecoveryRegion && wasInRegion)
        {
            log.debug("[death-guard] Left Death's Office region");
        }

        // Clear the widget-open flag after a tick if the widget is no longer
        // actually displayed (RuneLite does not fire a WidgetClosed event).
        if (recoveryWidgetOpen)
        {
            net.runelite.api.widgets.Widget w = client.getWidget(WIDGET_GRAVESTONE, 0);
            if (w == null || w.isHidden())
            {
                recoveryWidgetOpen = false;
            }
        }
    }

    /**
     * Called when the game state changes.  Clears the guard on logout so we
     * do not carry stale state into the next session.
     */
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOGIN_SCREEN:
            case HOPPING:
            case CONNECTION_LOST:
                reset();
                break;
            default:
                break;
        }
    }

    // ── Internal helpers ──────────────────────────────────────────────────────

    private void triggerDeath(String reason)
    {
        deathDetectedAt = clock.getAsLong();
        lastRecoveryInteractionAt = deathDetectedAt;
        log.debug("[death-guard] Death detected ({}). Suppression active for {} minutes.",
                reason, DEATH_SUPPRESSION_MINUTES);
    }

    private void markRecoveryInteraction(String context)
    {
        lastRecoveryInteractionAt = clock.getAsLong();
        log.debug("[death-guard] Recovery interaction: {}", context);
    }

    private int getCurrentRegionId()
    {
        Player local = client.getLocalPlayer();
        if (local == null) return -1;
        WorldPoint pos = local.getWorldLocation();
        return pos != null ? pos.getRegionID() : -1;
    }

    private static boolean isDeathOfficeRegion(int regionId)
    {
        return regionId == REGION_DEATHS_OFFICE
                || regionId == REGION_DEATHS_OFFICE_ALT1
                || regionId == REGION_DEATHS_OFFICE_ALT2;
    }

    // ── Nested data class ─────────────────────────────────────────────────────

    /** An item that was suppressed (not counted as loot) during recovery mode. */
    public static class IgnoredRecoveryItem
    {
        public final int     itemId;
        public final String  itemName;
        public final int     quantity;
        public final String  reason;
        public final Instant timestamp;
        public final int     regionId;

        IgnoredRecoveryItem(int itemId, String itemName, int quantity,
                String reason, Instant timestamp, int regionId)
        {
            this.itemId    = itemId;
            this.itemName  = itemName;
            this.quantity  = quantity;
            this.reason    = reason;
            this.timestamp = timestamp;
            this.regionId  = regionId;
        }
    }
}

package com.runealytics;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Reads RuneLite's default Loot Tracker data and returns per-source,
 * per-item absolute quantity totals for the currently logged-in account.
 *
 * <h2>How RuneLite stores loot (and why account scoping matters)</h2>
 * <p>RuneLite keeps all per-account ("RS profile") data inside the shared
 * {@code profiles2/*.properties} files using keys of the form:</p>
 * <pre>
 *   loottracker.rsprofile.&lt;RSPROFILE_KEY&gt;.drops_&lt;TYPE&gt;_&lt;NAME&gt; = { ...json... }
 * </pre>
 * <p>where {@code <RSPROFILE_KEY>} (e.g. {@code "Ro2U8NV6"}) identifies one RS
 * account. A single file therefore contains the loot of <em>every</em> account
 * that has ever logged in on this installation. The mapping from an
 * {@code <RSPROFILE_KEY>} to its RuneScape display name is stored alongside as:</p>
 * <pre>
 *   rsprofile.rsprofile.&lt;RSPROFILE_KEY&gt;.displayName = Zezima
 * </pre>
 *
 * <p>To avoid importing other accounts' loot, this reader:</p>
 * <ol>
 *   <li>Builds a {@code <RSPROFILE_KEY> → normalizedDisplayName} map from every
 *       {@code rsprofile.rsprofile.*.displayName} property it can find.</li>
 *   <li>Resolves the {@code <RSPROFILE_KEY>}(s) whose display name matches the
 *       currently logged-in account.</li>
 *   <li>Reads <b>only</b> the {@code loottracker.rsprofile.<that key>.drops_*}
 *       entries — every other account's loot is ignored.</li>
 * </ol>
 *
 * <p>When the current account has no identifiable RS-profile key (e.g. RuneLite
 * never recorded a display name for it), nothing is imported and the caller
 * should show the "history could not be matched" warning. Forward-sync via live
 * {@code LootReceived} events is always safe and unaffected by this limitation.</p>
 *
 * <h2>Data format</h2>
 * <p>Returns a {@code Map<sourceName, Map<itemId, totalQuantity>>} where
 * {@code totalQuantity} is the <em>absolute</em> total RuneLite has recorded.
 * These values must be treated as absolute totals, never as incremental drops.</p>
 */
@Slf4j
@Singleton
public class DefaultRuneLiteLootTrackerReader
{
    /** Loot entries: {@code loottracker.rsprofile.<KEY>.drops_<TYPE>_<NAME>}. */
    private static final String LOOT_KEY_PREFIX = "loottracker.rsprofile.";
    private static final String DROPS_INFIX     = ".drops_";

    /** Account-name mapping: {@code rsprofile.rsprofile.<KEY>.displayName}. */
    private static final String RSPROFILE_KEY_PREFIX = "rsprofile.rsprofile.";
    private static final String DISPLAY_NAME_SUFFIX  = ".displayName";

    private final RuneLiteTrackerFileCache fileCache = new RuneLiteTrackerFileCache();

    @Inject
    public DefaultRuneLiteLootTrackerReader() {}

    // ── Public API ────────────────────────────────────────────────────────────

    /**
     * Returns {@code true} when at least one RS-profile display name can be read
     * from the {@code profiles2} files — i.e. RuneLite has tagged accounts and
     * we are able to scope loot per account. When {@code false}, callers must
     * NOT import historical RuneLite loot and should rely on live events.
     */
    public boolean canImportHistorical()
    {
        return canImportHistorical(listProfileFiles());
    }

    /** Testable core of {@link #canImportHistorical()} over an explicit file list. */
    boolean canImportHistorical(List<File> files)
    {
        for (File f : files)
        {
            if (!readProfileKeyToAccount(loadProperties(f)).isEmpty()) return true;
        }
        return false;
    }

    /**
     * Per-source totals read from RuneLite's own Loot Tracker file: the
     * cumulative kill count RuneLite has recorded for that source, alongside
     * the absolute per-item quantities.
     */
    public static class SourceTotals
    {
        public int killCount;
        public final Map<Integer, Long> items = new HashMap<>();
    }

    /**
     * Reads RuneLite Loot Tracker absolute totals for {@code accountKey}.
     *
     * <p>Only loot stored under the RS-profile key(s) whose display name matches
     * {@code accountKey} is returned. All other accounts' loot is ignored.</p>
     *
     * @param  accountKey  normalized RuneScape username, e.g. {@code "zezima"}
     * @return map of {sourceName → totals}; empty (never null) when no matching data exists
     */
    public Map<String, SourceTotals> readForAccount(String accountKey)
    {
        return readForAccount(accountKey, listProfileFiles());
    }

    /**
     * Testable core of {@link #readForAccount(String)} over an explicit file
     * list, so the per-account scoping can be unit-tested without depending on
     * {@code RuneLite.RUNELITE_DIR}.
     */
    Map<String, SourceTotals> readForAccount(String accountKey, List<File> files)
    {
        if (accountKey == null || accountKey.isEmpty())
        {
            return Collections.emptyMap();
        }

        if (files == null || files.isEmpty())
        {
            return Collections.emptyMap();
        }

        Map<String, SourceTotals> result = new HashMap<>();
        Set<String> allSeenDisplayNames = new HashSet<>();

        for (File propFile : files)
        {
            Properties props = loadProperties(propFile);
            if (props == null) continue;

            // 1. Which RS-profile keys in this file belong to the current account?
            Map<String, String> keyToAccount = readProfileKeyToAccount(props);
            allSeenDisplayNames.addAll(keyToAccount.values());

            Set<String> matchingKeys = new HashSet<>();
            for (Map.Entry<String, String> e : keyToAccount.entrySet())
            {
                if (accountKey.equals(e.getValue())) matchingKeys.add(e.getKey());
            }

            if (matchingKeys.isEmpty())
            {
                continue;
            }

            // 2. Read only loot stored under those keys.
            readLootForKeys(propFile.getName(), props, matchingKeys, result);
        }

        // Drop sources that ended up with neither a kill count nor any item —
        // e.g. an entry whose "drops" array was empty or whose only pairs were
        // filtered out (itemId<=0/qty<=0). These carry no real information and
        // must never reach the merge step as a phantom 0-KC/0-loot source.
        result.values().removeIf(t -> t.killCount <= 0 && t.items.isEmpty());

        return result;
    }

    // ── Internal helpers ──────────────────────────────────────────────────────

    /** Lists every {@code profiles2/*.properties} file, or empty when absent. */
    private List<File> listProfileFiles()
    {
        File profiles2 = new File(RuneLite.RUNELITE_DIR, "profiles2");
        if (!profiles2.isDirectory()) return Collections.emptyList();

        File[] files = profiles2.listFiles(f -> f.isFile() && f.getName().endsWith(".properties"));
        if (files == null || files.length == 0) return Collections.emptyList();

        // Most-recently-modified first, so a tie on display name prefers the
        // freshest profile data.
        Arrays.sort(files, (a, b) -> Long.compare(b.lastModified(), a.lastModified()));
        return Arrays.asList(files);
    }

    /**
     * Builds {@code <RSPROFILE_KEY> → normalizedDisplayName} from all
     * {@code rsprofile.rsprofile.<KEY>.displayName} properties in this file.
     */
    private Map<String, String> readProfileKeyToAccount(Properties props)
    {
        if (props == null) return Collections.emptyMap();

        Map<String, String> map = new HashMap<>();
        for (String key : props.stringPropertyNames())
        {
            if (!key.startsWith(RSPROFILE_KEY_PREFIX) || !key.endsWith(DISPLAY_NAME_SUFFIX)) continue;

            String rsKey = key.substring(
                    RSPROFILE_KEY_PREFIX.length(),
                    key.length() - DISPLAY_NAME_SUFFIX.length());
            if (rsKey.isEmpty() || rsKey.contains(".")) continue; // guard nested keys

            String name = props.getProperty(key);
            String normalized = CurrentPlayerIdentityService.normalizeUsername(name);
            if (normalized != null) map.put(rsKey, normalized);
        }
        return map;
    }

    /**
     * Parses {@code loottracker.rsprofile.<KEY>.drops_*} entries whose
     * {@code <KEY>} is in {@code allowedKeys} and merges absolute totals into
     * {@code dest}. The loot value JSON looks like:
     * <pre>{"type":"NPC","name":"Goblin guard","kills":1,"drops":[526,1,995,5]}</pre>
     *
     * @return {@code true} if at least one entry was parsed
     */
    private boolean readLootForKeys(String fileName, Properties props, Set<String> allowedKeys,
            Map<String, SourceTotals> dest)
    {
        int entriesParsed = 0;

        for (String key : props.stringPropertyNames())
        {
            if (!key.startsWith(LOOT_KEY_PREFIX)) continue;

            int dropsIdx = key.indexOf(DROPS_INFIX, LOOT_KEY_PREFIX.length());
            if (dropsIdx < 0) continue;

            String rsKey = key.substring(LOOT_KEY_PREFIX.length(), dropsIdx);
            if (!allowedKeys.contains(rsKey)) continue; // belongs to another account

            String val = props.getProperty(key);
            if (val == null || val.isBlank()) continue;

            try
            {
                JsonObject obj = new JsonParser().parse(val).getAsJsonObject();

                String name  = obj.has("name")  ? obj.get("name").getAsString()  : "Unknown";
                int    kills = obj.has("kills") ? obj.get("kills").getAsInt()    : 0;
                if (!obj.has("drops") || !obj.get("drops").isJsonArray()) continue;

                JsonArray flatDrops = obj.getAsJsonArray("drops");
                SourceTotals totals = dest.computeIfAbsent(name, k -> new SourceTotals());

                // RuneLite stores ABSOLUTE kill counts/quantities. max() guards
                // against the same account's data being split across files or
                // across multiple drops_<TYPE>_<name> entries for one source.
                totals.killCount = Math.max(totals.killCount, kills);

                for (int i = 0; i + 1 < flatDrops.size(); i += 2)
                {
                    int  itemId = flatDrops.get(i).getAsInt();
                    long qty    = flatDrops.get(i + 1).getAsLong();
                    if (itemId <= 0 || qty <= 0) continue;

                    totals.items.merge(itemId, qty, Math::max);
                }

                entriesParsed++;
            }
            catch (Exception ignore)
            {
                log.debug("Error parsing RuneLite loot entry");
            }
        }

        return entriesParsed > 0;
    }

    private Properties loadProperties(File propFile)
    {
        // Check cache first: if the file hasn't changed (same lastModified + size),
        // return the cached Properties object without re-reading from disk.
        Properties cached = fileCache.getCachedIfUnchanged(propFile);
        if (cached != null)
        {
            return cached;
        }

        Properties props = new Properties();
        try (InputStreamReader isr = new InputStreamReader(
                new FileInputStream(propFile), StandardCharsets.UTF_8))
        {
            props.load(isr);
            fileCache.put(propFile, props);
            return props;
        }
        catch (Exception e)
        {
            return null;
        }
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Tracks Doom of Mokhaiotl delve runs with full lifecycle management.
 *
 * <p>This component manages the state of potentially multiple concurrent Doom runs
 * (one per account/world combination) and provides hooks for:</p>
 * <ul>
 *   <li>Detecting Doom region entry</li>
 *   <li>Tracking NPC kills in Doom</li>
 *   <li>Detecting floor progression</li>
 *   <li>Capturing reward claims</li>
 *   <li>Invalidating runs on logout/world-hop</li>
 *   <li>Distinguishing progression from claimed rewards</li>
 * </ul>
 *
 * <h2>Doom Region Detection</h2>
 * <p>Doom of Mokhaiotl is located in the Kharidian Desert. The delve regions are
 * roughly area 14226 and nearby regions. We detect Doom by checking if the player
 * is in a high-level desert region and has killed a Mokhaiotl-family NPC.</p>
 *
 * <h2>Floor Detection</h2>
 * <p>Floor progression is detected through:</p>
 * <ul>
 *   <li>Chat messages mentioning floor completion</li>
 *   <li>Widget loading events (reward widgets fire as floor completes)</li>
 *   <li>NPC kills in Doom region (indicates progression)</li>
 * </ul>
 */
@Slf4j
@Singleton
public class DoomEncounterTracker
{
    private static final int MOKHAIOTL_DELVE_NPC_ID_START = 12681;
    private static final int MOKHAIOTL_DELVE_NPC_ID_END = 12690;

    /**
     * Timeout for abandoning a stale run (no activity for 2 minutes).
     */
    private static final long RUN_STALE_MS = 2 * 60 * 1_000L;

    /**
     * Per-account current run. Maps account name → DoomRunState.
     * Null when no active run.
     */
    private final Map<String, DoomRunState> currentRun = new ConcurrentHashMap<>();

    /**
     * Completed runs archived for analytics.
     * Kept for up to 1 hour after completion.
     */
    private final Map<String, DoomRunState> completedRuns = new LinkedHashMap<String, DoomRunState>()
    {
        protected boolean removeEldestEntry(Map.Entry eldest)
        {
            return size() > 100; // Keep last 100 completed runs
        }
    };

    private final Client client;

    /** Cumulative value of all Doom loot lost from this session. */
    private long totalLostLootValue = 0;

    @Inject
    public DoomEncounterTracker(Client client)
    {
        this.client = client;
    }

    /**
     * Called when an NPC is killed. If it's in a Doom region, activates or updates
     * the current run.
     */
    public void onNpcKilled(NPC npc, String account, int world)
    {
        if (!isDoomNpc(npc))
            return;

        WorldPoint loc = npc.getWorldLocation();
        if (loc == null || !isDoomRegion(loc))
            return;

        log.debug("Doom NPC killed: {} at {}", npc.getName(), loc);

        // Get or create run for this account
        DoomRunState run = currentRun.computeIfAbsent(account, k -> new DoomRunState(account, world));

        // If run is stale or on wrong world, replace it
        if (run.isStale() || run.getStartWorld() != world)
        {
            log.debug("Doom run {} is stale or on wrong world, creating new run", run.getRunId());
            run = new DoomRunState(account, world);
            currentRun.put(account, run);
        }

        // Activate progression if not already active
        if (run.getState() == DoomRunState.State.IDLE)
        {
            run.startProgression();
        }
    }

    /**
     * Called when a floor completion is detected (via chat or widget).
     */
    public void onFloorCompleted(String account, int floorNumber)
    {
        DoomRunState run = currentRun.get(account);
        if (run == null)
        {
            log.debug("No active Doom run for {}, ignoring floor {} completion", account, floorNumber);
            return;
        }

        run.completeFloor(floorNumber);
    }

    /**
     * Called when the reward is claimed (widget opened showing items).
     */
    public void onRewardClaimed(String account, List<ItemStack> items)
    {
        DoomRunState run = currentRun.get(account);
        if (run == null)
        {
            log.debug("No active Doom run for {}, ignoring reward claim", account);
            return;
        }

        run.claimReward(items);
        log.debug("Doom reward claimed: {} items, highest floor={}", items.size(), run.getHighestFloorCompleted());
    }

    /**
     * Records pending loot shown in the reward dialog (items earned this floor).
     */
    public void onPendingLootShown(String account, List<ItemStack> items, long value)
    {
        DoomRunState run = currentRun.get(account);
        if (run == null)
        {
            log.debug("No active Doom run for {}, ignoring pending loot", account);
            return;
        }

        run.setPendingLoot(items, value);
        log.debug("Doom pending loot recorded: {} items, {} gp", items.size(), value);
    }

    /**
     * Marks the run as completed after loot has been recorded to the database.
     */
    public void markComplete(String account)
    {
        DoomRunState run = currentRun.remove(account);
        if (run != null)
        {
            run.complete();
            completedRuns.put(run.getRunId(), run);
            log.debug("Doom run marked complete: {}", run);
        }
    }

    /**
     * Abandons the current run (logout, world hop, death, etc.).
     * Accumulates lost loot value to session total.
     */
    public void abandonRun(String account, String reason)
    {
        DoomRunState run = currentRun.get(account);
        if (run != null)
        {
            run.abandon(reason);
            if (run.getState() == DoomRunState.State.ABANDONED)
            {
                // Accumulate lost loot to session total
                totalLostLootValue += run.getLostLootValue();
                currentRun.remove(account);
                log.debug("Doom run abandoned: {} (lost {} gp, session total: {} gp)",
                        reason, run.getLostLootValue(), totalLostLootValue);
            }
        }
    }

    /**
     * Returns the current active Doom run for an account, or null if none.
     */
    public DoomRunState getCurrentRun(String account)
    {
        DoomRunState run = currentRun.get(account);
        if (run != null && run.isStale())
        {
            run.abandon("inactivity timeout");
            currentRun.remove(account);
            return null;
        }
        return run;
    }

    /**
     * Returns the cumulative value of all Doom loot lost in this session.
     */
    public long getTotalLostLootValue()
    {
        return totalLostLootValue;
    }

    /**
     * Returns the pending loot value from the current active run, or 0 if none.
     */
    public long getCurrentRunPendingLootValue(String account)
    {
        DoomRunState run = getCurrentRun(account);
        return run != null ? run.getPendingLootValue() : 0;
    }

    /**
     * Clears all state (logout/plugin shutdown).
     */
    public void reset()
    {
        for (DoomRunState run : currentRun.values())
            run.abandon("session reset");
        currentRun.clear();
        totalLostLootValue = 0;
    }

    // ─────────────────────────────────────────────────────────────────────────

    private boolean isDoomNpc(NPC npc)
    {
        if (npc == null) return false;
        int id = npc.getId();
        return id >= MOKHAIOTL_DELVE_NPC_ID_START && id <= MOKHAIOTL_DELVE_NPC_ID_END;
    }

    /**
     * Returns true if the given world point is in the Doom of Mokhaiotl delve region.
     * Doom is primarily in region 14226 with surrounding delve regions.
     */
    private boolean isDoomRegion(WorldPoint p)
    {
        if (p == null) return false;

        // Doom delves are in the Kharidian Desert around 3300-3400x / 2800-2900y
        // More specifically, the delve region block is around 14226
        // We can detect by: specific coordinates or region verification
        // For now, use coordinate ranges
        int x = p.getX();
        int y = p.getY();
        int region = p.getRegionID();

        // Primary Doom delve region
        if (region == 14226) return true;

        // Nearby delve region IDs  (rough estimate based on world coordinates)
        // Doom regions: 14226 is the main one
        // Surrounding: 14225, 14227, 14482, 14483, etc. (need verification)

        // Coordinate-based detection: Kharidian desert around Artefacts area
        return (x >= 3200 && x <= 3400 && y >= 2700 && y <= 2900);
    }
}

package com.runealytics;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.util.*;

/**
 * Tracks the state of a Doom of Mokhaiotl delve run.
 *
 * <p>Doom is a progressive encounter where the player can choose to continue
 * deeper into the delve for better rewards or claim their current reward. This
 * state machine ensures:</p>
 * <ul>
 *   <li>Each floor progression is tracked (floor 1, 2, 3, etc.)</li>
 *   <li>Final claimed reward is recorded only once</li>
 *   <li>Floor progression is not counted as independent boss kills</li>
 *   <li>Highest floor completed is tracked separately from loot</li>
 *   <li>Failures/deaths invalidate the run</li>
 *   <li>Logout invalidates pending progress</li>
 * </ul>
 *
 * <h2>State Flow</h2>
 * <pre>
 *   IDLE
 *     ↓ (NPC killed in Doom region)
 *   PROGRESSION_ACTIVE
 *     ↓ (floor N completed)
 *   FLOOR_N_COMPLETED
 *     ↓ (player claims reward)
 *   REWARD_CLAIMED
 *     ↓ (loot recorded)
 *   COMPLETED
 *
 *   OR:
 *     ↓ (player dies or logs out before claiming)
 *   ABANDONED
 * </pre>
 */
@Slf4j
@Getter
public class DoomRunState
{
    public enum State
    {
        IDLE,
        PROGRESSION_ACTIVE,
        REWARD_CLAIMED,
        COMPLETED,
        ABANDONED
    }

    /** Unique identifier for this run (UUID). */
    private final String runId;

    /** RuneScape account this run belongs to (for isolation). */
    private final String account;

    /** State of this run. */
    private State state = State.IDLE;

    /** Highest floor completed in this run (0 = not started, 1-5+ = floor number). */
    private int highestFloorCompleted = 0;

    /** Current in-progress floor (during PROGRESSION_ACTIVE). */
    private int currentFloor = 0;

    /** World the run started on. */
    private int startWorld = 0;

    /** Time run started (epoch ms). */
    private long startedAt = 0;

    /** Time the run was last updated (epoch ms). */
    private long lastActivityAt = 0;

    /** Time reward was claimed (epoch ms). */
    private long claimedAt = 0;

    /** Items obtained from the final reward. */
    private List<ItemStack> claimedItems = Collections.emptyList();

    /** Pending loot accumulated but not yet claimed (shown in reward dialog). */
    private List<ItemStack> pendingLoot = Collections.emptyList();

    /** Total value of pending loot in GP. */
    private long pendingLootValue = 0;

    /** Total value of loot lost from this run (if abandoned before claiming). */
    private long lostLootValue = 0;

    /** Floor progression history (useful for analytics). */
    private final List<FloorProgression> progressionHistory = new ArrayList<>();

    /** Reason run was abandoned (if applicable). */
    private String abandonReason = null;

    /**
     * Timeout after which an active run is automatically considered abandoned
     * if no activity occurs (2 minutes, matching typical Doom completion time).
     */
    private static final long INACTIVITY_TIMEOUT_MS = 2 * 60 * 1_000L;

    // ─────────────────────────────────────────────────────────────────────────

    public DoomRunState(String account, int world)
    {
        this.runId = UUID.randomUUID().toString();
        this.account = account;
        this.startWorld = world;
        this.startedAt = System.currentTimeMillis();
        this.lastActivityAt = startedAt;
    }

    /**
     * Mark the start of active progression (first NPC killed in Doom).
     */
    public void startProgression()
    {
        if (state != State.IDLE)
        {
            log.debug("DoomRun {}: Cannot start progression from state {}", runId, state);
            return;
        }
        state = State.PROGRESSION_ACTIVE;
        currentFloor = 1;
        lastActivityAt = System.currentTimeMillis();
        log.debug("DoomRun {}: Progression started, account={}", runId, account);
    }

    /**
     * Record completion of a floor with potential reward widget visibility.
     */
    public void completeFloor(int floorNumber)
    {
        if (state != State.PROGRESSION_ACTIVE)
        {
            log.debug("DoomRun {}: Cannot complete floor {} from state {}", runId, floorNumber, state);
            return;
        }

        this.currentFloor = floorNumber;
        this.highestFloorCompleted = Math.max(highestFloorCompleted, floorNumber);
        this.lastActivityAt = System.currentTimeMillis();

        progressionHistory.add(new FloorProgression(floorNumber, lastActivityAt));
        log.debug("DoomRun {}: Floor {} completed (highest={})", runId, floorNumber, highestFloorCompleted);
    }

    /**
     * Record the pending loot shown in the floor-completion reward dialog.
     * This loot is earned but not yet claimed (player can descend or claim).
     */
    public void setPendingLoot(List<ItemStack> items, long value)
    {
        if (state != State.PROGRESSION_ACTIVE)
        {
            log.debug("DoomRun {}: Cannot set pending loot from state {}", runId, state);
            return;
        }

        this.pendingLoot = new ArrayList<>(items);
        this.pendingLootValue = value;
        this.lastActivityAt = System.currentTimeMillis();
        log.debug("DoomRun {}: Pending loot set for floor {}: {} items, {} gp",
                runId, highestFloorCompleted, items.size(), value);
    }

    /**
     * Mark that the player has claimed their reward.
     */
    public void claimReward(List<ItemStack> items)
    {
        if (state != State.PROGRESSION_ACTIVE)
        {
            log.debug("DoomRun {}: Cannot claim reward from state {}", runId, state);
            return;
        }

        state = State.REWARD_CLAIMED;
        claimedAt = System.currentTimeMillis();
        claimedItems = new ArrayList<>(items);
        lastActivityAt = claimedAt;

        log.debug("DoomRun {}: Reward claimed with {} items, highest floor={}", runId, items.size(), highestFloorCompleted);
    }

    /**
     * Mark the run as successfully completed after loot has been recorded.
     */
    public void complete()
    {
        if (state != State.REWARD_CLAIMED)
        {
            log.debug("DoomRun {}: Cannot complete from state {}", runId, state);
            return;
        }

        state = State.COMPLETED;
        log.debug("DoomRun {}: Run completed, final floor={}, items={}", runId, highestFloorCompleted, claimedItems.size());
    }

    /**
     * Abandon the run due to death, logout, world hop, etc.
     * Captures any pending loot that was lost.
     */
    public void abandon(String reason)
    {
        if (state == State.COMPLETED || state == State.ABANDONED)
        {
            return;
        }

        // Record loot value that was lost if run is abandoned during progression
        if (state == State.PROGRESSION_ACTIVE && pendingLootValue > 0)
        {
            lostLootValue = pendingLootValue;
            log.debug("DoomRun {}: Abandoned with {} gp pending loot lost", runId, lostLootValue);
        }

        state = State.ABANDONED;
        abandonReason = reason;
        lastActivityAt = System.currentTimeMillis();
        log.debug("DoomRun {}: Abandoned - {}", runId, reason);
    }

    /**
     * Returns true if this run has been inactive for too long.
     * Inactive runs are automatically abandoned when checked.
     */
    public boolean isStale()
    {
        if (state == State.COMPLETED || state == State.ABANDONED)
            return true;

        return System.currentTimeMillis() - lastActivityAt > INACTIVITY_TIMEOUT_MS;
    }

    /**
     * Returns true if the claimed reward is waiting to be recorded.
     * False after {@link #complete()} because that runs once loot is saved.
     */
    public boolean isReadyToRecord()
    {
        return state == State.REWARD_CLAIMED && !claimedItems.isEmpty();
    }

    /**
     * Record of a single floor progression.
     */
    @Getter
    public static class FloorProgression
    {
        private final int floor;
        private final long completedAt;

        public FloorProgression(int floor, long completedAt)
        {
            this.floor = floor;
            this.completedAt = completedAt;
        }
    }

    @Override
    public String toString()
    {
        return String.format("DoomRun{id=%s, account=%s, state=%s, floor=%d, highestFloor=%d}",
                runId, account, state, currentFloor, highestFloorCompleted);
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Monitors executor health to detect starvation (tasks not executing in timely fashion).
 *
 * <p>Periodically submits a probe task to the executor and measures how long it takes
 * to execute. If probe execution is significantly delayed, logs a warning indicating
 * the executor may be starved or overloaded.</p>
 *
 * <p>Separate monitoring instances are used for loot-sync executor and other executors
 * to identify which executor is experiencing problems.</p>
 */
@Slf4j
public class ExecutorHealthMonitor
{
    private static final long PROBE_INTERVAL_MS = 60_000; // Check every 60 seconds
    private static final long PROBE_TIMEOUT_MS = 5_000;   // Task should run within 5 seconds
    private static final long STARVATION_THRESHOLD_MS = 10_000; // Warn if > 10 seconds delay

    private final ScheduledExecutorService executor;
    private final String executorName;
    private volatile ScheduledFuture<?> healthCheckTask;
    private final AtomicLong lastProbeExecutionTimeMs = new AtomicLong(System.currentTimeMillis());

    public ExecutorHealthMonitor(ScheduledExecutorService executor, String executorName)
    {
        this.executor = executor;
        this.executorName = executorName;
    }

    /**
     * Starts periodic health checks. Should be called at plugin startup.
     */
    public void start()
    {
        if (executor == null || executor.isShutdown()) return;

        healthCheckTask = executor.scheduleAtFixedRate(
            this::runHealthProbe,
            PROBE_INTERVAL_MS,
            PROBE_INTERVAL_MS,
            TimeUnit.MILLISECONDS
        );
        log.debug("[health] Started health monitoring for executor: {}", executorName);
    }

    /**
     * Stops health checks. Should be called at plugin shutdown.
     */
    public void stop()
    {
        if (healthCheckTask != null)
        {
            healthCheckTask.cancel(false);
            healthCheckTask = null;
            log.debug("[health] Stopped health monitoring for executor: {}", executorName);
        }
    }

    /**
     * Runs a lightweight probe task and measures execution delay.
     */
    private void runHealthProbe()
    {
        long probeSubmitTimeMs = System.currentTimeMillis();

        try
        {
            executor.execute(() ->
            {
                long probeExecuteTimeMs = System.currentTimeMillis();
                long delayMs = probeExecuteTimeMs - probeSubmitTimeMs;

                if (delayMs > STARVATION_THRESHOLD_MS)
                {
                    log.debug("[health] {} executor is starved: probe delayed {}ms (> {}ms threshold)",
                        executorName, delayMs, STARVATION_THRESHOLD_MS);
                }
                else if (delayMs > PROBE_TIMEOUT_MS / 2)
                {
                    log.debug("[health] {} executor is slow: probe delayed {}ms",
                        executorName, delayMs);
                }

                lastProbeExecutionTimeMs.set(probeExecuteTimeMs);
            });
        }
        catch (Exception e)
        {
            log.debug("[health] Failed to submit health probe to {}: {}",
                executorName, e.getMessage());
        }
    }

    /**
     * @return the timestamp of the last successful probe execution
     */
    public long getLastProbeExecutionTimeMs()
    {
        return lastProbeExecutionTimeMs.get();
    }

    /**
     * @return true if no probe has executed for > 30 seconds (executor likely dead)
     */
    public boolean isLikelyDead()
    {
        long lastProbeMs = getLastProbeExecutionTimeMs();
        long timeSinceLastProbeMs = System.currentTimeMillis() - lastProbeMs;
        return timeSinceLastProbeMs > 30_000;
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.ConcurrentHashMap;

/**
 * Caches Grand Exchange prices with time-to-live (TTL) expiration.
 *
 * <p>GE prices change frequently (every few seconds), so cached prices are
 * invalidated after a configurable TTL. This reduces API calls to the GE
 * service while remaining reasonably fresh.</p>
 *
 * <p>Thread-safe via ConcurrentHashMap. Expired entries are lazily purged
 * on access, not by a background thread.</p>
 */
@Slf4j
public class GePriceCache
{
    /** Default TTL: 5 minutes for GE prices */
    private static final long DEFAULT_TTL_MS = 5 * 60 * 1000;

    private static class CacheEntry
    {
        final int price;
        final long expiresAtMs;

        CacheEntry(int price, long expiresAtMs)
        {
            this.price = price;
            this.expiresAtMs = expiresAtMs;
        }

        boolean isExpired()
        {
            return System.currentTimeMillis() > expiresAtMs;
        }
    }

    private final ConcurrentHashMap<Integer, CacheEntry> cache = new ConcurrentHashMap<>();
    private final long ttlMs;
    private volatile long cacheHits = 0;
    private volatile long cacheMisses = 0;

    public GePriceCache()
    {
        this(DEFAULT_TTL_MS);
    }

    public GePriceCache(long ttlMs)
    {
        this.ttlMs = ttlMs;
    }

    /**
     * Attempts to retrieve a cached GE price for the given item ID.
     *
     * @param itemId the item ID to look up
     * @return cached price if available and not expired, or -1 if cache miss
     */
    public int getPrice(int itemId)
    {
        CacheEntry entry = cache.get(itemId);
        if (entry != null && !entry.isExpired())
        {
            cacheHits++;
            log.debug("[cache] GE price cache HIT: id={} price={}", itemId, entry.price);
            return entry.price;
        }

        // Remove expired entry
        if (entry != null)
        {
            cache.remove(itemId);
        }

        cacheMisses++;
        return -1;
    }

    /**
     * Stores a GE price in the cache for the given item ID.
     *
     * @param itemId the item ID
     * @param price the Grand Exchange price
     */
    public void putPrice(int itemId, int price)
    {
        if (price < 0) return;

        long expiresAtMs = System.currentTimeMillis() + ttlMs;
        cache.put(itemId, new CacheEntry(price, expiresAtMs));
        log.debug("[cache] GE price cached: id={} price={} ttl={}ms", itemId, price, ttlMs);
    }

    /**
     * Clears the entire cache.
     */
    public void clear()
    {
        int sizeBefore = cache.size();
        cache.clear();
        cacheHits = 0;
        cacheMisses = 0;
        log.debug("[cache] GE price cache cleared ({} entries)", sizeBefore);
    }

    /**
     * Purges all expired entries. Useful for periodic cleanup if cache
     * is not accessed frequently.
     *
     * @return number of entries purged
     */
    public int purgeExpired()
    {
        int purged = 0;
        for (Integer itemId : cache.keySet())
        {
            CacheEntry entry = cache.get(itemId);
            if (entry != null && entry.isExpired())
            {
                if (cache.remove(itemId) != null)
                {
                    purged++;
                }
            }
        }
        if (purged > 0)
        {
            log.debug("[cache] GE price cache purged {} expired entries", purged);
        }
        return purged;
    }

    /**
     * @return cache hit rate as percentage (0-100), or 0 if no queries yet
     */
    public double getHitRate()
    {
        long total = cacheHits + cacheMisses;
        return total > 0 ? (100.0 * cacheHits / total) : 0.0;
    }

    /**
     * @return total number of cache hits
     */
    public long getHits()
    {
        return cacheHits;
    }

    /**
     * @return total number of cache misses
     */
    public long getMisses()
    {
        return cacheMisses;
    }

    /**
     * @return current cache size (number of cached entries, including expired ones)
     */
    public int size()
    {
        return cache.size();
    }

    /**
     * @return TTL in milliseconds
     */
    public long getTtlMs()
    {
        return ttlMs;
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

/**
 * Validates and scopes ground-item attribution to prevent false positives.
 *
 * <p>Ground-item detection is the least reliable loot-tracking method because
 * multiple items spawning simultaneously in a multi-player area can be attributed
 * to the wrong NPC. This validator ensures ground items are only counted as loot
 * when they clearly belong to a specific kill.</p>
 *
 * <h2>Scope Validation</h2>
 * <p>Ground items are only attributed to a kill when ALL of:</p>
 * <ul>
 *   <li>Item spawned within {@value #GROUND_ITEM_PROXIMITY_TILES} tiles of the kill</li>
 *   <li>Item spawned within {@value #GROUND_ITEM_WINDOW_MS} ms of the kill</li>
 *   <li>Item is not a shared loot chest/interface (runs, raids, etc.)</li>
 *   <li>Player is not in a shared multi-combat area (Wilderness, Dungeon, Raid)</li>
 *   <li>Item does not match known non-loot IDs (cosmetics, etc.)</li>
 * </ul>
 *
 * <h2>High-Risk Scenarios (Bypassed)</h2>
 * <ul>
 *   <li>Wilderness (where loot can be seen by other players) — use server loot only</li>
 *   <li>Raid areas (CoX, ToB, ToA) — use container reads, not ground items</li>
 *   <li>Multi-combat zones with multiple players — attribution uncertain</li>
 *   <li>GWD / other group dungeons — use widget/container reads instead</li>
 * </ul>
 */
@Slf4j
@Singleton
public class GroundItemAttributor
{
    /**
     * Maximum distance (in tiles) an item can spawn from the kill location
     * to be attributed to that kill.
     */
    private static final int GROUND_ITEM_PROXIMITY_TILES = 8;

    /**
     * Maximum time (ms) after a kill during which ground items are attributed to it.
     */
    private static final long GROUND_ITEM_WINDOW_MS = 5_000L;

    /**
     * World types where ground-item attribution is disabled entirely
     * (loot is visible to other players, unsafe).
     */
    private static final Set<Integer> UNSAFE_WORLD_TYPES = Set.of(
            4,   // PvP
            64,  // Dead man
            128, // Survival
            256  // Leagues
    );

    /**
     * Region IDs that are multi-player or raid areas where item attribution
     * is ambiguous. Uses container reads or widget reads instead.
     */
    private static final Set<Integer> NO_GROUND_ITEM_REGIONS = Set.of(
            12889, 12890, 12891, 13105, 13106, 13107, // CoX
            12611, 12612, 12867, 12868,                // ToB
            14386, 14387, 14643, 14644, 14645,         // ToA
            12444,                                      // Barrows
            7513, 7769,                                 // GWD
            15131                                       // Inferno (for now)
    );

    /**
     * Items that should never be considered loot even if they spawn near a kill.
     * (Cosmetics, boss mechanics, non-drop items, etc.)
     */
    private static final Set<Integer> NON_LOOT_ITEM_IDS = Set.of(
            ItemID.CLUE_SCROLL  // Handled separately via menu + widget
    );

    private final Client client;

    @Inject
    public GroundItemAttributor(Client client)
    {
        this.client = client;
    }

    /**
     * Validates whether a ground item should be attributed to a specific kill.
     *
     * @param itemId item ID that spawned
     * @param itemQuantity quantity that spawned
     * @param killLocation world point where the kill occurred
     * @param killTime epoch ms when the kill occurred (approximate)
     * @return true if the item should be counted as loot from this kill
     */
    public boolean shouldAttributeToKill(int itemId, int itemQuantity,
                                         WorldPoint killLocation, long killTime)
    {
        // --- Sanity checks ---
        if (itemId <= 0 || itemQuantity <= 0 || killLocation == null)
            return false;

        // --- Filter non-loot items ---
        if (NON_LOOT_ITEM_IDS.contains(itemId))
        {
            log.debug("Ground item {} is in non-loot filter", itemId);
            return false;
        }

        // --- World type validation ---
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
            return false;

        WorldPoint playerLoc = localPlayer.getWorldLocation();
        if (playerLoc == null)
            return false;

        // Check if world is unsafe (PvP, DMM, Survival, Leagues)
        int world = client.getWorld();
        if (isUnsafeWorld(world))
        {
            log.debug("Ground item {} in unsafe world type {}, attribution blocked", itemId, world);
            return false;
        }

        // --- Region validation ---
        if (isInNoGroundItemRegion(killLocation))
        {
            log.debug("Ground item {} in raid/multi-combat region, attribution blocked", itemId);
            return false;
        }

        // --- Proximity validation ---
        int distanceSquared = playerLoc.distanceTo(killLocation);
        if (distanceSquared > GROUND_ITEM_PROXIMITY_TILES)
        {
            log.debug("Ground item {} spawned {} tiles away (max={}), not attributed",
                    itemId, distanceSquared, GROUND_ITEM_PROXIMITY_TILES);
            return false;
        }

        // --- Time window validation ---
        long elapsed = System.currentTimeMillis() - killTime;
        if (elapsed > GROUND_ITEM_WINDOW_MS)
        {
            log.debug("Ground item {} spawned {}ms after kill (max={}ms), not attributed",
                    itemId, elapsed, GROUND_ITEM_WINDOW_MS);
            return false;
        }

        log.debug("Ground item {} attributed to kill at {} ({}ms, {}tiles away)",
                itemId, killLocation, elapsed, distanceSquared);
        return true;
    }

    /**
     * Returns true if the given world type is unsafe for ground-item attribution.
     * (PvP worlds where items are visible to other players, DMM, etc.)
     */
    private boolean isUnsafeWorld(int worldNumber)
    {
        // World type is encoded in the world number
        // Lower bits indicate world type flags
        for (int unsafe : UNSAFE_WORLD_TYPES)
        {
            if ((worldNumber & unsafe) != 0)
                return true;
        }
        return false;
    }

    /**
     * Returns true if the given region is a raid, dungeon, or multi-combat area
     * where ground-item attribution is ambiguous.
     */
    private boolean isInNoGroundItemRegion(WorldPoint p)
    {
        if (p == null) return false;
        int region = p.getRegionID();
        return NO_GROUND_ITEM_REGIONS.contains(region);
    }
}

package com.runealytics;

import java.util.HashSet;
import java.util.Set;
import java.util.function.LongSupplier;

/**
 * Suppresses inventory-diff loot attribution while the player is moving items
 * through a non-loot interface: bank, deposit box, Grand Exchange, shop,
 * trade, seed vault or group storage.
 *
 * <h2>Problem</h2>
 * <p>The skilling, pickpocket, impling-jar and crate-reward paths all work by
 * diffing inventory snapshots. A bank withdrawal (or trade/shop/GE collect)
 * that lands inside one of those attribution windows is indistinguishable
 * from loot at the container level — e.g. withdrawing feathers within 1.5 s of
 * a Fishing XP drop recorded the feathers as Fishing loot. Equipment moves
 * were already excluded ({@code excludeEquipmentMovement}); bank/trade/shop
 * moves were not.</p>
 *
 * <h2>Model</h2>
 * <p>Mirrors {@link DeathRecoveryGuard}: the plugin feeds widget open/close
 * events in, and every inventory-diff site asks
 * {@link #shouldSuppressInventoryDiff()} before attributing gains. Suppression
 * lasts while any tracked interface is open plus a short
 * {@value #CLOSE_COOLDOWN_MS} ms cooldown after the last one closes, covering
 * trailing {@code ItemContainerChanged} events that arrive a tick or two
 * later.</p>
 *
 * <p>Confirmed-attribution paths ({@code NpcLootReceived},
 * {@code PlayerLootReceived}, reward-container/widget reads) are NOT gated by
 * this guard — RuneLite has already tied those items to a kill or chest, and
 * loot must never be lost because a bank happened to be open.</p>
 *
 * <p>Pure Java (widget group ids are plain ints supplied by the plugin), so
 * the logic is fully unit-testable without a client.</p>
 */
public class InventoryDiffGuard
{
    // ── Tracked widget group IDs (stable OSRS interface ids) ────────────────
    static final int GROUP_BANK           = 12;
    static final int GROUP_BANK_PIN       = 213;
    static final int GROUP_DEPOSIT_BOX    = 192;
    static final int GROUP_GRAND_EXCHANGE = 465;
    static final int GROUP_GE_COLLECTION  = 402;
    static final int GROUP_SHOP           = 300;
    static final int GROUP_TRADE          = 335;
    static final int GROUP_TRADE_CONFIRM  = 334;
    static final int GROUP_SEED_VAULT     = 631;
    static final int GROUP_GROUP_STORAGE  = 724;

    private static final Set<Integer> TRACKED_GROUPS = buildTrackedGroups();

    private static Set<Integer> buildTrackedGroups()
    {
        Set<Integer> s = new HashSet<>();
        s.add(GROUP_BANK);
        s.add(GROUP_BANK_PIN);
        s.add(GROUP_DEPOSIT_BOX);
        s.add(GROUP_GRAND_EXCHANGE);
        s.add(GROUP_GE_COLLECTION);
        s.add(GROUP_SHOP);
        s.add(GROUP_TRADE);
        s.add(GROUP_TRADE_CONFIRM);
        s.add(GROUP_SEED_VAULT);
        s.add(GROUP_GROUP_STORAGE);
        return s;
    }

    /**
     * How long after the last tracked interface closes that inventory diffs
     * remain suppressed (~3 game ticks), absorbing trailing container events.
     */
    static final long CLOSE_COOLDOWN_MS = 1_800L;

    private final LongSupplier clock;

    /** Tracked interfaces currently open (client thread only). */
    private final Set<Integer> openGroups = new HashSet<>();

    /** When the last tracked interface closed (epoch ms), or 0. */
    private volatile long lastCloseAt = 0L;

    /** True while any tracked interface is open — volatile mirror of openGroups. */
    private volatile boolean anyOpen = false;

    public InventoryDiffGuard()
    {
        this(System::currentTimeMillis);
    }

    /** Test seam: deterministic clock. */
    InventoryDiffGuard(LongSupplier clock)
    {
        this.clock = clock;
    }

    /** Feed from {@code WidgetLoaded}: marks a tracked interface as open. */
    public synchronized void onWidgetLoaded(int groupId)
    {
        if (TRACKED_GROUPS.contains(groupId))
        {
            openGroups.add(groupId);
            anyOpen = true;
        }
    }

    /** Feed from {@code WidgetClosed}: starts the close cooldown. */
    public synchronized void onWidgetClosed(int groupId)
    {
        if (openGroups.remove(groupId))
        {
            lastCloseAt = clock.getAsLong();
            anyOpen = !openGroups.isEmpty();
        }
    }

    /**
     * @return {@code true} while a bank/GE/shop/trade/vault interface is open,
     *         or within {@value #CLOSE_COOLDOWN_MS} ms of the last one closing
     *         — inventory-diff loot attribution must be skipped.
     */
    public boolean shouldSuppressInventoryDiff()
    {
        if (anyOpen) return true;
        long closedAt = lastCloseAt;
        return closedAt != 0L && clock.getAsLong() - closedAt < CLOSE_COOLDOWN_MS;
    }

    /** Clears all state (logout / account switch / plugin restart). */
    public synchronized void reset()
    {
        openGroups.clear();
        anyOpen = false;
        lastCloseAt = 0L;
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.ConcurrentHashMap;

/**
 * Caches static item metadata (name, ID, alch value, etc.) that rarely changes.
 *
 * <p>Item composition data from ItemManager is fetched on the client thread and
 * cached here to avoid repeated client-thread calls for the same item ID.
 * This is particularly useful during merge operations where many items may be
 * processed but few are unique.</p>
 *
 * <p>Cache is never invalidated during a session since item metadata is static
 * and doesn't change at runtime. If RuneLite patches items, a plugin reload
 * clears all caches automatically.</p>
 */
@Slf4j
public class ItemMetadataCache
{
    public static class ItemMetadata
    {
        public final int itemId;
        public final String name;
        public final int highAlch;
        public final long gecPrice;

        public ItemMetadata(int itemId, String name, int highAlch, long gecPrice)
        {
            this.itemId = itemId;
            this.name = name;
            this.highAlch = highAlch;
            this.gecPrice = gecPrice;
        }
    }

    private final ConcurrentHashMap<Integer, ItemMetadata> cache = new ConcurrentHashMap<>();
    private volatile long cacheHits = 0;
    private volatile long cacheMisses = 0;

    /**
     * Attempts to retrieve cached metadata for the given item ID.
     *
     * @param itemId the item ID to look up
     * @return cached metadata if available, or null if cache miss
     */
    public ItemMetadata get(int itemId)
    {
        ItemMetadata metadata = cache.get(itemId);
        if (metadata != null)
        {
            cacheHits++;
            log.debug("[cache] Item metadata cache HIT: id={} name={}", itemId, metadata.name);
        }
        else
        {
            cacheMisses++;
        }
        return metadata;
    }

    /**
     * Stores metadata in the cache for the given item ID.
     *
     * @param metadata the item metadata to cache
     */
    public void put(ItemMetadata metadata)
    {
        if (metadata == null) return;
        cache.put(metadata.itemId, metadata);
        log.debug("[cache] Item metadata cached: id={} name={}", metadata.itemId, metadata.name);
    }

    /**
     * Clears the entire cache. Called on plugin reload.
     */
    public void clear()
    {
        int sizeBefore = cache.size();
        cache.clear();
        cacheHits = 0;
        cacheMisses = 0;
        log.debug("[cache] Item metadata cache cleared ({} entries)", sizeBefore);
    }

    /**
     * @return cache hit rate as percentage (0-100), or 0 if no queries yet
     */
    public double getHitRate()
    {
        long total = cacheHits + cacheMisses;
        return total > 0 ? (100.0 * cacheHits / total) : 0.0;
    }

    /**
     * @return total number of cache hits
     */
    public long getHits()
    {
        return cacheHits;
    }

    /**
     * @return total number of cache misses
     */
    public long getMisses()
    {
        return cacheMisses;
    }

    /**
     * @return current cache size (number of cached items)
     */
    public int size()
    {
        return cache.size();
    }
}

