package com.runealytics;

import com.google.common.collect.ImmutableMap;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemID;
import net.runelite.client.game.ItemManager;

import java.util.Map;

/**
 * Resolves the GE value of any item — including untradeable / charged variants
 * — by canonicalising and (where necessary) decomposing into the tradeable
 * components a player would have to spend to re-create it.
 *
 * <p>Items like Scythe of Vitur, Tumeken's Shadow, Sanguinesti staff, and gear
 * like Ferocious Gloves are <em>untradeable in their charged / final form</em>,
 * so {@link ItemManager#getItemPrice} returns 0 for them. This resolver looks
 * each one up in a hand-curated decomposition table and falls back to the
 * canonical (uncharged / unnoted) form.</p>
 *
 * <p>Adding new items: append to {@link #DECOMPOSITION}. The "value" is a
 * {@code Map<itemId, quantity>} naming the tradeable components that compose
 * the untradeable item. Charges are not modelled — the reported value is that
 * of an <em>empty</em> charged item.</p>
 */
public final class ItemValueResolver
{
    private ItemValueResolver() {}

    /**
     * Maps an untradeable / charged item ID → its tradeable components.
     *
     * <p>Each entry says "to make this item the player burned the listed
     * tradeable ingredients". Values are summed at runtime against live GE
     * prices, so the totals stay accurate even as prices drift.</p>
     */
    private static final Map<Integer, Map<Integer, Integer>> DECOMPOSITION =
            ImmutableMap.<Integer, Map<Integer, Integer>>builder()
                    // ── ToB megas (charged variants are untradeable; report base) ──
                    .put(ItemID.SCYTHE_OF_VITUR,            componentMap(ItemID.SCYTHE_OF_VITUR_UNCHARGED, 1))
                    .put(ItemID.SANGUINESTI_STAFF,          componentMap(ItemID.SANGUINESTI_STAFF_UNCHARGED, 1))
                    .put(ItemID.GHRAZI_RAPIER,              componentMap(ItemID.GHRAZI_RAPIER, 1))
                    .put(ItemID.JUSTICIAR_FACEGUARD,        componentMap(ItemID.JUSTICIAR_FACEGUARD, 1))
                    .put(ItemID.JUSTICIAR_CHESTGUARD,       componentMap(ItemID.JUSTICIAR_CHESTGUARD, 1))
                    .put(ItemID.JUSTICIAR_LEGGUARDS,        componentMap(ItemID.JUSTICIAR_LEGGUARDS, 1))

                    // ── ToA megas ──────────────────────────────────────────────
                    .put(ItemID.TUMEKENS_SHADOW,            componentMap(ItemID.TUMEKENS_SHADOW_UNCHARGED, 1))

                    // ── CoX (already tradeable but kept for completeness) ──────
                    // (Twisted bow / Kodai / etc. trade as-is — no decomposition needed.)

                    // ── Hydra / Slayer untradeables ────────────────────────────
                    .put(ItemID.FEROCIOUS_GLOVES,           componentMap(ItemID.HYDRA_LEATHER, 1))

                    // ── Crystal armour / weapons (charged; report blueprint cost) ──
                    .put(ItemID.BOW_OF_FAERDHINEN,          componentMap(ItemID.BOW_OF_FAERDHINEN_INACTIVE, 1))
                    .put(ItemID.BLADE_OF_SAELDOR,           componentMap(ItemID.BLADE_OF_SAELDOR_INACTIVE, 1))

                    // ── Misc charged / inactive forms ──────────────────────────
                    .put(ItemID.RING_OF_SUFFERING_R,        componentMap(ItemID.RING_OF_SUFFERING, 1))
                    .put(ItemID.AMULET_OF_BLOOD_FURY,       componentMap(ItemID.AMULET_OF_FURY, 1, ItemID.BLOOD_SHARD, 1))
                    .put(ItemID.AMULET_OF_THE_DAMNED_FULL,  componentMap(ItemID.AMULET_OF_THE_DAMNED, 1))
                    .build();

    private static Map<Integer, Integer> componentMap(int... idQtyPairs)
    {
        if (idQtyPairs.length % 2 != 0)
            throw new IllegalArgumentException("componentMap requires id,qty pairs");
        ImmutableMap.Builder<Integer, Integer> b = ImmutableMap.builder();
        for (int i = 0; i < idQtyPairs.length; i += 2)
            b.put(idQtyPairs[i], idQtyPairs[i + 1]);
        return b.build();
    }

    /**
     * Returns the live GE value of a single item, resolving untradeable /
     * charged / noted forms transparently.
     *
     * <ol>
     *   <li>If the item has an explicit decomposition entry, sum component
     *       GE values.</li>
     *   <li>Otherwise fall back to {@link ItemManager#canonicalize} and look
     *       up the canonical form's price — this handles noted items, broken
     *       weapons, and any item whose linked-tradeable RuneLite knows
     *       about.</li>
     *   <li>If both lookups return 0 (truly untradeable, e.g. quest items),
     *       returns 0.</li>
     * </ol>
     */
    /**
     * Narrows a RuneLite price ({@code long} since client 1.13.0) to the
     * {@code int} used by the plugin's storage and API payloads, clamping
     * instead of overflowing.
     */
    public static int clampPrice(long price)
    {
        return (int) Math.max(Integer.MIN_VALUE, Math.min(price, Integer.MAX_VALUE));
    }

    public static int perItemGeValue(ItemManager itemManager, int itemId)
    {
        if (itemManager == null || itemId <= 0) return 0;

        Map<Integer, Integer> components = DECOMPOSITION.get(itemId);
        if (components != null)
        {
            long total = 0;
            for (Map.Entry<Integer, Integer> e : components.entrySet())
                total += itemManager.getItemPrice(e.getKey()) * e.getValue();
            if (total > 0) return (int) Math.min(total, Integer.MAX_VALUE);
        }

        int canonical = itemManager.canonicalize(itemId);
        int price = clampPrice(itemManager.getItemPrice(canonical));
        if (price > 0) return price;

        // Last-ditch fallback: high-alch value (so the bank total includes at
        // least *something* for purely untradeable items).
        ItemComposition comp = itemManager.getItemComposition(itemId);
        if (comp != null) return Math.max(0, comp.getHaPrice());
        return 0;
    }
}

package com.runealytics;

import java.util.HashMap;
import java.util.Map;
import java.util.function.UnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Single source of truth for <b>authoritative game kill counts</b> parsed from
 * chat, replacing the ad-hoc (Whisperer-only) KC handling.
 *
 * <h2>Why</h2>
 * <p>The game announces the real KC in chat for nearly every boss, raid,
 * Barrows, the Gauntlet, Wintertodt and Tempoross, in several distinct
 * grammatical forms. Historically the plugin parsed only
 * {@code "Your X kill count is: N"} — and then discarded the value for every
 * boss except the Whisperer, so almost all kills were numbered by the local
 * counter even when the game had just told us the true KC.</p>
 *
 * <h2>Message forms recognised</h2>
 * <ul>
 *   <li>{@code Your Vorkath kill count is: 100.}</li>
 *   <li>{@code Your Barrows chest count is: 279.}</li>
 *   <li>{@code Your Gauntlet completion count is: 12.}</li>
 *   <li>{@code Your herbiboar harvest count is: 50.}</li>
 *   <li>{@code Your completed Chambers of Xeric count is: 57.}</li>
 *   <li>{@code Your subdued Wintertodt count is: 245.}</li>
 *   <li>Fallback: {@code Your <anything> count is: N.} (e.g. Lunar Chest)</li>
 * </ul>
 *
 * <h2>Correlation model</h2>
 * <p>Each parsed message becomes a per-boss <em>pending observation</em>.
 * The kill write path ({@code LootTrackerManager.recordKill}) consumes the
 * observation when it records a kill for the same normalised boss within
 * {@value #CONSUME_WINDOW_MS} ms — regardless of whether the chat message or
 * the loot event arrived first. An observation is consumed <b>exactly once</b>
 * so multiple KC signals can never increment a kill twice.</p>
 *
 * <h2>Safety rules</h2>
 * <ul>
 *   <li>Monotonic per boss: an observation lower than the highest KC already
 *       seen this session is rejected (stale / out-of-order message).</li>
 *   <li>State is session-scoped: {@link #clear()} must be called on logout or
 *       account switch so one account's KC can never bleed into another.</li>
 *   <li>Pure Java, no client dependencies — trivially unit-testable and
 *       incapable of crashing an event handler.</li>
 * </ul>
 */
public class KillCountResolver
{
    /**
     * How long a parsed KC stays claimable by a kill record for the same boss.
     *
     * <p>Ground-drop bosses record within ticks of the message, but chest and
     * raid sources announce the KC on completion while the reward is only
     * read when the player opens the chest — potentially a minute or more
     * later. Two minutes comfortably covers that walk while staying far below
     * the fastest possible repeat of any chest/raid source, so an unconsumed
     * observation can never be mistaken for the <em>next</em> completion's KC
     * (and even then, the raise-only guards make a stale value harmless).</p>
     */
    static final long CONSUME_WINDOW_MS = 120_000L;

    /** Strips RuneScape chat markup ({@code <col=...>}, {@code <br>}, ...). */
    private static final Pattern TAG_PATTERN = Pattern.compile("<[^>]*>");

    /**
     * Ordered patterns; the first match wins. Group 1 = boss name,
     * group 2 = count (may contain thousands separators).
     */
    private static final Pattern[] KC_PATTERNS = {
            // "Your completed Chambers of Xeric count is: 57"
            Pattern.compile("your completed (.+?) count is:?\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE),
            // "Your subdued Wintertodt count is: 245"
            Pattern.compile("your subdued (.+?) count is:?\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE),
            // "Your Vorkath kill count is: 100" / "Your Barrows chest count is: 279"
            // / "Your Gauntlet completion count is: 12" / harvest & success variants
            Pattern.compile(
                    "your (.+?) (?:kill count|chest count|completion count|success count|harvest count) is:?\\s*([\\d,]+)",
                    Pattern.CASE_INSENSITIVE),
            // Fallback for counts with no recognised suffix, e.g.
            // "Your Lunar Chest count is: 11"
            Pattern.compile("your (.+?) count is:?\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE),
    };

    /** One authoritative-KC sighting parsed from chat. */
    public static final class KcObservation
    {
        private final String bossName;
        private final int    killCount;
        private final long   timestampMs;

        KcObservation(String bossName, int killCount, long timestampMs)
        {
            this.bossName    = bossName;
            this.killCount   = killCount;
            this.timestampMs = timestampMs;
        }

        /** Normalised boss / source name (already passed through the name normaliser). */
        public String getBossName()    { return bossName; }
        /** The authoritative in-game kill count from the message. */
        public int    getKillCount()   { return killCount; }
        /** Wall-clock time the message was observed. */
        public long   getTimestampMs() { return timestampMs; }
    }

    /** Canonicalises raw chat boss names to the plugin's storage keys. */
    private final UnaryOperator<String> nameNormalizer;

    /** Pending, not-yet-consumed observations keyed by normalised boss name. */
    private final Map<String, KcObservation> pending = new HashMap<>();

    /**
     * Highest KC seen per boss this session — used to reject stale or
     * out-of-order KC messages. Cleared with {@link #clear()}.
     */
    private final Map<String, Integer> highestSeen = new HashMap<>();

    /**
     * @param nameNormalizer maps a raw boss name from chat to the canonical
     *                       storage key (production passes
     *                       {@code BossNames::normalize})
     */
    public KillCountResolver(UnaryOperator<String> nameNormalizer)
    {
        this.nameNormalizer = nameNormalizer;
    }

    /**
     * Parses a chat message and, when it carries a KC, records it as the
     * pending observation for that boss.
     *
     * @param rawMessage chat message, may contain colour tags
     * @param nowMs      current wall-clock time
     * @return the recorded observation, or {@code null} when the message
     *         carries no KC or the KC regressed below the highest seen value
     */
    public synchronized KcObservation observe(String rawMessage, long nowMs)
    {
        if (rawMessage == null || rawMessage.isEmpty()) return null;

        String stripped = TAG_PATTERN.matcher(rawMessage).replaceAll("").trim();

        for (Pattern p : KC_PATTERNS)
        {
            Matcher m = p.matcher(stripped);
            if (!m.find()) continue;

            String rawName = m.group(1).trim();
            int kc;
            try
            {
                kc = Integer.parseInt(m.group(2).replace(",", ""));
            }
            catch (NumberFormatException nfe)
            {
                return null; // count too large / malformed — ignore safely
            }
            if (kc <= 0) return null;

            String key = normalize(rawName);
            if (key == null || key.isEmpty()) return null;

            Integer highest = highestSeen.get(key);
            if (highest != null && kc < highest)
            {
                // Regression: stale message replay or cross-variant noise.
                return null;
            }

            KcObservation obs = new KcObservation(key, kc, nowMs);
            pending.put(key, obs);
            highestSeen.put(key, kc);
            return obs;
        }
        return null;
    }

    /**
     * Claims (and removes) the pending KC for {@code bossName} when one was
     * observed within {@link #CONSUME_WINDOW_MS}. Expired observations are
     * dropped. Consuming is exactly-once: a second call returns {@code null},
     * which is what guarantees KC can never be applied to two kills.
     *
     * @return the authoritative game KC, or {@code null} when none is pending
     */
    public synchronized Integer consume(String bossName, long nowMs)
    {
        String key = normalize(bossName);
        if (key == null) return null;

        KcObservation obs = pending.remove(key);
        if (obs == null) return null;

        if (nowMs - obs.getTimestampMs() > CONSUME_WINDOW_MS)
        {
            return null; // too old to be this kill's KC — discarded
        }
        return obs.getKillCount();
    }

    /** @return the highest KC seen for {@code bossName} this session, or {@code null}. */
    public synchronized Integer getHighestSeen(String bossName)
    {
        String key = normalize(bossName);
        return key == null ? null : highestSeen.get(key);
    }

    /**
     * Drops all session state. MUST be called on logout / account switch so
     * observations and monotonic floors never leak across accounts.
     */
    public synchronized void clear()
    {
        pending.clear();
        highestSeen.clear();
    }

    private String normalize(String raw)
    {
        if (raw == null) return null;
        String normalized = nameNormalizer.apply(raw);
        return normalized == null ? null : normalized;
    }
}

package com.runealytics;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.List;

/**
 * Draws the players the website says we are allowed to see (delivered in each
 * {@code /plugin/heartbeat} response and cached in {@link RuneAlyticsState}) on
 * both the in-game minimap and the game scene.
 *
 * <p>Only players on the local player's current world and plane that fall inside
 * the loaded scene are drawn — anything outside that range simply isn't rendered,
 * exactly like RuneLite's own minimap dots. All rendering happens on the client
 * thread, so reading client state here is safe. Rendering is gated behind the
 * {@code showMapPlayers} config toggle.</p>
 */
@Singleton
public class LiveMapMinimapOverlay extends Overlay
{
    private static final int   DOT_SIZE    = 5;
    private static final int   SCENE_TEXT_Z = 60;
    private static final Color DOT_COLOR   = new Color(0, 200, 255);   // cyan
    private static final Color DOT_BORDER  = new Color(0, 80, 110);
    private static final Color TILE_COLOR  = new Color(0, 200, 255, 120);
    private static final Color TILE_FILL   = new Color(0, 200, 255, 40);
    private static final Color NAME_COLOR  = Color.WHITE;

    private final Client client;
    private final RuneAlyticsState state;
    private final RunealyticsConfig config;

    @Inject
    public LiveMapMinimapOverlay(Client client, RuneAlyticsState state, RunealyticsConfig config)
    {
        this.client = client;
        this.state  = state;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.MED);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showMapPlayers())
        {
            return null;
        }

        List<MapPlayer> players = state.getVisibleMapPlayers();
        if (players == null || players.isEmpty())
        {
            return null;
        }

        Player local = client.getLocalPlayer();
        if (local == null)
        {
            return null;
        }

        final int localWorld = client.getWorld();
        final int localPlane = client.getPlane();
        final String localName = normalizeRsn(local.getName());

        for (MapPlayer p : players)
        {
            if (p == null) continue;

            // Don't draw on ourselves, and only show same-world/plane peers.
            // Names are normalized because RuneLite uses NBSP (U+00A0) while the
            // server uses regular spaces/underscores. World must match exactly:
            // a player on another world rendered at our scene coords is a ghost.
            if (localName != null && localName.equalsIgnoreCase(normalizeRsn(p.getUsername()))) continue;
            if (p.getWorld() != localWorld) continue;
            if (p.getPlane() != localPlane) continue;

            WorldPoint wp = p.toWorldPoint();
            LocalPoint lp = LocalPoint.fromWorld(client, wp);
            if (lp == null) continue; // outside the loaded scene

            drawSceneMarker(graphics, lp, p.getUsername());
            drawMinimapDot(graphics, lp);
        }

        return null;
    }

    private static String normalizeRsn(String name)
    {
        if (name == null) return null;
        return name.replace('\u00A0', ' ').replace('_', ' ').trim();
    }

    private void drawMinimapDot(Graphics2D graphics, LocalPoint lp)
    {
        net.runelite.api.Point mm = Perspective.localToMinimap(client, lp);
        if (mm == null) return;

        int half = DOT_SIZE / 2;
        graphics.setColor(DOT_COLOR);
        graphics.fillOval(mm.getX() - half, mm.getY() - half, DOT_SIZE, DOT_SIZE);
        graphics.setColor(DOT_BORDER);
        graphics.drawOval(mm.getX() - half, mm.getY() - half, DOT_SIZE, DOT_SIZE);
    }

    private void drawSceneMarker(Graphics2D graphics, LocalPoint lp, String name)
    {
        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly != null)
        {
            graphics.setColor(TILE_COLOR);
            graphics.draw(poly);
            graphics.setColor(TILE_FILL);
            graphics.fill(poly);
        }

        if (name != null && !name.isEmpty())
        {
            net.runelite.api.Point textLoc =
                    Perspective.getCanvasTextLocation(client, graphics, lp, name, SCENE_TEXT_Z);
            if (textLoc != null)
            {
                graphics.setColor(NAME_COLOR);
                graphics.drawString(name, textLoc.getX(), textLoc.getY());
            }
        }
    }
}

package com.runealytics;

/**
 * Enumeration of log categories for categorized debug logging.
 *
 * <p>Allows filtering logs by component and concern (sync, cache, executor, etc.)
 * for easier debugging and performance analysis. Each log message includes its
 * category in the debug output, e.g., {@code [sync:merge] Merging 5 sources}</p>
 */
public enum LogCategory
{
    /** Loot sync pipeline operations */
    SYNC("sync"),
    /** Sync merge operations (three-source merge) */
    SYNC_MERGE("sync:merge"),
    /** Sync coordination and coalescing */
    SYNC_COORD("sync:coord"),
    /** Executor health and starvation */
    EXECUTOR("executor"),
    /** Cache hits, misses, and operations */
    CACHE("cache"),
    /** File I/O operations */
    FILE_IO("file-io"),
    /** Network I/O and API calls */
    NETWORK("network"),
    /** ItemManager queries and client thread operations */
    ITEM_MANAGER("item-mgr"),
    /** Memory pressure and GC events */
    MEMORY("memory"),
    /** Performance metrics and timing */
    PERF("perf"),
    /** Bank sync operations */
    BANK_SYNC("bank-sync"),
    /** Generic plugin events */
    PLUGIN("plugin"),
    /** Loot tracker UI updates and performance */
    UI_UPDATE("ui-update");

    public final String label;

    LogCategory(String label)
    {
        this.label = label;
    }

    /**
     * Formats a log message with this category prefix.
     * Supports standard String.format() style formatting with %s, %d, %f, etc.
     * Example: format("Memory: %d%% (%s)", 85, "HIGH")
     * becomes "[perf] Memory: 85% (HIGH)"
     *
     * @param format the format string (supports %s, %d, %f, etc.)
     * @param args variable arguments to substitute into format string
     * @return formatted message with category prefix
     */
    public String format(String format, Object... args)
    {
        String formattedMessage = String.format(format, args);
        return String.format("[%s] %s", label, formattedMessage);
    }
}

package com.runealytics;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import java.util.List;

/**
 * Builds the {@code drop} / {@code kill} JSON objects POSTed to the RuneAlytics
 * server. Central schema shared by all loot upload paths.
 */
public final class LootKillJsonBuilder
{
    private LootKillJsonBuilder() {}

    /**
     * Builds a single {@code DropRecord} JSON object matching the
     * {@code /loot/*} API schema. Items with no resolvable name are included
     * with a synthetic {@code "Item #<id>"} label.
     */
    public static JsonObject buildDrop(LootStorageData.DropRecord drop)
    {
        JsonObject d = new JsonObject();
        d.addProperty("item_id",     drop.getItemId());
        d.addProperty("item_name",   safeName(drop));
        d.addProperty("quantity",    Math.max(1, drop.getQuantity()));
        d.addProperty("ge_price",    drop.getGePrice());
        d.addProperty("high_alch",   drop.getHighAlch());
        d.addProperty("total_value", drop.getTotalValue());
        d.addProperty("hidden",      drop.isHidden());
        d.addProperty("is_pet",      drop.isPet());
        return d;
    }

    private static String safeName(LootStorageData.DropRecord drop)
    {
        String name = drop.getItemName();
        if (name != null && !name.isEmpty()) return name;
        return "Item #" + drop.getItemId();
    }

    /**
     * Builds a complete kill payload (NPC metadata + drops + aggregates).
     *
     * <p>NPC info is passed in because {@link LootStorageData.KillRecord} does
     * not store it — kills are nested under their NPC inside
     * {@link LootStorageData.BossKillData}.</p>
     */
    public static JsonObject buildKill(
            LootStorageData.KillRecord kill,
            String npcName,
            int npcId,
            int prestige)
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("npc_name",     npcName);
        payload.addProperty("npc_id",       npcId);
        payload.addProperty("combat_level", kill.getCombatLevel());
        payload.addProperty("kill_count",   kill.getKillNumber());
        payload.addProperty("world",        kill.getWorld());
        payload.addProperty("timestamp",    kill.getTimestamp());
        payload.addProperty("prestige",     prestige);
        payload.addProperty("game_mode",    kill.getGameMode()    != null ? kill.getGameMode()    : "regular");
        payload.addProperty("account_type", kill.getAccountType() != null ? kill.getAccountType() : "normal");

        JsonArray dropsArr = new JsonArray();
        long totalValue = 0;
        int  dropCount  = 0;

        List<LootStorageData.DropRecord> drops = kill.getDrops();
        if (drops != null)
        {
            for (LootStorageData.DropRecord d : drops)
            {
                dropsArr.add(buildDrop(d));
                totalValue += d.getTotalValue();
                dropCount++;
            }
        }

        payload.add("drops", dropsArr);
        payload.addProperty("total_loot_value", totalValue);
        payload.addProperty("drop_count",       dropCount);

        // Optional per-kill location object. Omitted when the kill has no
        // captured location.
        PlayerLocationSnapshot location = kill.getLocation();
        if (location != null)
        {
            payload.add("location", location.toJson());
        }

        return payload;
    }

    /**
     * Wraps a batch of kill payloads inside the envelope the bulk endpoints expect.
     *
     * <p>Schema: {@code { "username": ..., "game_mode": ..., "account_type": ..., "kills": [...] }}.
     * {@code game_mode} and {@code account_type} at the top level represent the session-level
     * default; individual kill objects may carry their own values if the mode changed
     * mid-session (e.g. world-hop from regular to a Leagues world).</p>
     *
     * @param username       verified RSN
     * @param gameMode       session-level game mode (e.g. "regular", "leagues")
     * @param accountSubtype session-level account subtype (e.g. "normal", "ironman")
     * @param kills          list of per-kill payloads built by {@link #buildKill}
     */
    public static JsonObject buildBulkEnvelope(
            String username,
            String gameMode,
            String accountSubtype,
            List<JsonObject> kills)
    {
        JsonObject envelope = new JsonObject();
        envelope.addProperty("username",     username);
        envelope.addProperty("game_mode",    gameMode      != null ? gameMode      : "regular");
        envelope.addProperty("account_type", accountSubtype != null ? accountSubtype : "normal");

        JsonArray arr = new JsonArray();
        for (JsonObject k : kills) arr.add(k);
        envelope.add("kills", arr);
        return envelope;
    }
}

package com.runealytics;

import com.google.gson.annotations.SerializedName;
import lombok.Data;

import java.util.*;

@Data
public class LootStorageData
{
    @SerializedName("username")
    private String username;

    /**
     * Monotonically increasing revision number.
     * Incremented every time new loot is added to local storage.
     * Used to detect when newer loot has arrived during a synchronization,
     * preventing the sync result from overwriting unsynchronized local drops.
     */
    @SerializedName("revision")
    private long revision = 0;

    @SerializedName("last_sync")
    private long lastSyncTimestamp;

    @SerializedName("boss_kills")
    private Map<String, BossKillData> bossKills = new HashMap<>();

    /**
     * Per-boss set of item IDs the user has hidden in RuneAlytics, keyed by
     * normalised boss name. Separate from RuneLite's own ignore list.
     */
    @SerializedName("hidden_drops_by_boss")
    private Map<String, Set<Integer>> hiddenDropsByBoss = new HashMap<>();

    /**
     * Per-boss set of item IDs the user has permanently deleted from RuneAlytics,
     * keyed by normalised boss name. These are stripped from incoming server data
     * during sync so deleted items don't reappear.
     */
    @SerializedName("deleted_drops_by_boss")
    private Map<String, Set<Integer>> deletedDropsByBoss = new HashMap<>();

    /**
     * Normalised names of bosses the user has hidden from the panel entirely.
     * Display-only; does not affect what gets synced to the server.
     */
    @SerializedName("hidden_bosses")
    private Set<String> hiddenBosses = new HashSet<>();

    /**
     * Last authoritative in-game kill count observed per boss (from KC chat
     * messages), keyed by normalised boss name. Raise-only. Survives restarts
     * so the real game KC can be audited against the local counter; absent in
     * files written by older plugin versions (Gson leaves the default).
     */
    @SerializedName("last_game_kc_by_boss")
    private Map<String, Integer> lastGameKcByBoss = new HashMap<>();

    @Data
    public static class BossKillData
    {
        @SerializedName("npc_name")
        private String npcName;

        @SerializedName("npc_id")
        private int npcId;

        @SerializedName("kill_count")
        private int killCount;

        @SerializedName("prestige")
        private int prestige;

        @SerializedName("total_loot_value")
        private long totalLootValue;

        @SerializedName("kills")
        private List<KillRecord> kills = new ArrayList<>();

        @SerializedName("aggregated_drops")
        private Map<Integer, AggregatedDrop> aggregatedDrops = new HashMap<>();
    }

    @Data
    public static class KillRecord
    {
        @SerializedName("timestamp")
        private long timestamp;

        @SerializedName("kill_number")
        private int killNumber;

        @SerializedName("world")
        private int world;

        @SerializedName("combat_level")
        private int combatLevel;

        @SerializedName("drops")
        private List<DropRecord> drops = new ArrayList<>();

        @SerializedName("synced_to_server")
        private boolean syncedToServer;

        /**
         * Game mode at the time this kill was recorded.
         * Values: "regular", "ironman", "leagues", "deadman", "fresh_start", "grid_master".
         * Defaults to "regular" for records loaded from older storage files.
         */
        @SerializedName("game_mode")
        private String gameMode = "regular";

        /**
         * OSRS account subtype at the time this kill was recorded.
         * Values: "normal", "ironman", "hardcore_ironman", "ultimate_ironman",
         * "group_ironman", "hardcore_group_ironman", "unranked_group_ironman".
         */
        @SerializedName("account_type")
        private String accountType = "normal";

        /**
         * Player location when this kill happened, captured on the client thread
         * and uploaded per-kill in the {@code /loot/bulk-sync} payload.
         * {@code null} when no location was captured, in which case the field is
         * omitted from the request.
         */
        @SerializedName("location")
        private PlayerLocationSnapshot location;
    }

    @Data
    public static class DropRecord
    {
        @SerializedName("item_id")
        private int itemId;

        @SerializedName("item_name")
        private String itemName;

        @SerializedName("quantity")
        private int quantity;

        @SerializedName("ge_price")
        private int gePrice;

        @SerializedName("high_alch")
        private int highAlch;

        // long: a per-drop value can exceed Integer.MAX_VALUE for large stacks
        // of high-value items.
        @SerializedName("total_value")
        private long totalValue;

        @SerializedName("hidden")
        private boolean hidden;

        @SerializedName("is_pet")
        private boolean pet;
    }

    @Data
    public static class AggregatedDrop
    {
        @SerializedName("item_id")
        private int itemId;

        @SerializedName("item_name")
        private String itemName;

        @SerializedName("total_quantity")
        private int totalQuantity;

        @SerializedName("drop_count")
        private int dropCount;

        @SerializedName("total_value")
        private long totalValue;

        @SerializedName("ge_price")
        private int gePrice;

        @SerializedName("high_alch")
        private int highAlch;

        @SerializedName("is_pet")
        private boolean pet;
    }
}

package com.runealytics;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.*;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.*;

@Slf4j
@Singleton
public class LootStorageManager
{
    private static final String STORAGE_FILE_PREFIX = "loot-";
    private static final String STORAGE_FILE_SUFFIX = ".json";
    /** Prefix used by releases that wrote loot files straight into {@code ~/.runelite}. */
    static final String LEGACY_FILE_PREFIX = "runealytics-loot-";
    private final Gson gson;
    private final RuneAlyticsState state;
    private LootStorageData currentData;

    /**
     * Plugin data directory ({@code ~/.runelite/plugin-data/runealytics}),
     * supplied by the plugin on startup. While null, loads return empty data
     * and saves are skipped.
     */
    private volatile Filepath dataDirectory;

    /**
     * Directory older releases wrote {@code runealytics-loot-*.json} into.
     * Set only by {@link #migrateLegacyLootFiles}. While a legacy file for the
     * current account is still here, saves refuse to create a new file, so a
     * failed move cannot be sealed by an empty overwrite.
     */
    private volatile File legacyDirectory;

    /** True when {@link #currentData} was read from the legacy file, not the plugin directory. */
    private volatile boolean loadedFromLegacy;

    private java.util.concurrent.ScheduledExecutorService saveExecutor = newSaveExecutor();
    private java.util.concurrent.ScheduledFuture<?> pendingSave = null;

    private static java.util.concurrent.ScheduledExecutorService newSaveExecutor()
    {
        return java.util.concurrent.Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "RuneAlytics-Save");
            t.setDaemon(true);
            return t;
        });
    }

    @Inject
    public LootStorageManager(RuneAlyticsState state, Gson gson)
    {
        this.state = state;
        this.gson = gson.newBuilder()
                .setPrettyPrinting()
                .create();
    }

    /**
     * Sets the plugin data directory used for all loot files. Does not scan
     * {@code ~/.runelite}; call {@link #migrateLegacyLootFiles} for that.
     */
    public void setDataDirectory(Filepath directory)
    {
        this.dataDirectory = directory;
    }

    /**
     * Moves loot files left in {@code legacyDir} by older releases into the
     * plugin data directory. {@code legacyDir} is remembered so a later save
     * can retry the move instead of creating a second file beside it.
     */
    public void migrateLegacyLootFiles(File legacyDir)
    {
        this.legacyDirectory = legacyDir;
        Filepath directory = this.dataDirectory;
        if (directory != null && legacyDir != null)
        {
            migrateLegacyFiles(legacyDir, directory);
        }
    }

    /**
     * Moves {@code runealytics-loot-*.json} files from the legacy location
     * (the root of {@code .runelite}) into the plugin data directory. A file is
     * only migrated when the destination does not already exist, so it never
     * overwrites newer data. Leftover {@code .tmp} files from interrupted
     * legacy saves are removed.
     */
    static void migrateLegacyFiles(File legacyDir, Filepath directory)
    {
        File[] legacy = legacyDir == null ? null : legacyDir.listFiles(f ->
                f.isFile() && f.getName().startsWith(LEGACY_FILE_PREFIX)
                        && (f.getName().endsWith(STORAGE_FILE_SUFFIX)
                            || f.getName().endsWith(STORAGE_FILE_SUFFIX + ".tmp")));
        if (legacy == null || legacy.length == 0) return;

        for (File old : legacy)
        {
            try
            {
                String name = old.getName();
                if (name.endsWith(".tmp"))
                {
                    Files.deleteIfExists(old.toPath());
                    continue;
                }

                String sanitized = name.substring(LEGACY_FILE_PREFIX.length(),
                        name.length() - STORAGE_FILE_SUFFIX.length());
                Filepath target = directory.joinSegment(
                        STORAGE_FILE_PREFIX + sanitized + STORAGE_FILE_SUFFIX);
                if (target.exists())
                {
                    log.debug("Skipping legacy loot file {}: {} already exists", name, target.getFileName());
                    continue;
                }

                // Copy via a temp file so a crash mid-migration can't leave a
                // truncated target that would block a retry on next start.
                directory.createDirectories();
                Filepath tmp = directory.joinSegment(target.getFileName() + ".tmp");
                tmp.write(Files.readAllBytes(old.toPath()));
                try
                {
                    tmp.moveTo(target,
                            StandardCopyOption.ATOMIC_MOVE,
                            StandardCopyOption.REPLACE_EXISTING);
                }
                catch (AtomicMoveNotSupportedException atomicEx)
                {
                    tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
                }
                Files.delete(old.toPath());
                log.debug("Migrated legacy loot file {} to plugin data directory", name);
            }
            catch (Exception e)
            {
                log.debug("Failed to migrate legacy loot file {}", old.getName(), e);
            }
        }
    }

    /**
     * Load loot data for current username
     */
    public synchronized LootStorageData loadData()
    {
        String username = state.getVerifiedUsername();
        if (username == null || username.isEmpty())
        {
            log.debug("No verified username, cannot load loot data");
            currentData = new LootStorageData();
            return currentData;
        }

        Filepath file = getStorageFile(username);
        if (file != null && file.exists())
        {
            loadedFromLegacy = false;
            try (Reader reader = file.openBufferedReader())
            {
                return readLoaded(reader, username);
            }
            catch (Exception e)
            {
                log.debug("Failed to load loot data for {}", username, e);
            }
        }
        else
        {
            // Filepath cannot see the old ~/.runelite root, so a failed move
            // still has to be read from the legacy file directly.
            File legacy = legacyFileFor(username);
            if (legacy != null && legacy.isFile())
            {
                try (Reader reader = Files.newBufferedReader(legacy.toPath()))
                {
                    log.debug("Loaded legacy loot file {}", legacy.getName());
                    loadedFromLegacy = true;
                    return readLoaded(reader, username);
                }
                catch (Exception e)
                {
                    log.debug("Failed to load legacy loot data for {}", username, e);
                }
            }
            else
            {
                log.debug("No existing loot data file for {}", username);
            }
        }

        currentData = new LootStorageData();
        currentData.setUsername(username);
        loadedFromLegacy = false;
        return currentData;
    }

    private LootStorageData readLoaded(Reader reader, String username)
    {
        currentData = gson.fromJson(reader, LootStorageData.class);
        if (currentData == null)
        {
            currentData = new LootStorageData();
            currentData.setUsername(username);
            loadedFromLegacy = false;
        }
        int bossCount = 0;
        int killCount = 0;
        if (currentData.getBossKills() != null)
        {
            bossCount = currentData.getBossKills().size();
            killCount = currentData.getBossKills().values().stream()
                    .mapToInt(LootStorageData.BossKillData::getKillCount)
                    .sum();
        }
        log.debug("Loaded loot data for {} - {} bosses, {} total kills",
                username, bossCount, killCount);
        return currentData;
    }


    /**
     * Saves current loot data to disk.
     *
     * <p>Only the in-memory JSON serialisation happens under the lock — that's
     * CPU-only and stays fast even for a large history. The disk write (temp
     * file + atomic rename) runs afterwards with no lock held, so a kill event
     * on the client thread ({@link #addKill}) is never blocked waiting on disk
     * I/O from a background save. Holding a monitor across a blocking file
     * write is exactly what caused the client to stall during AOE kill bursts
     * (several {@link #addKill} calls landing back-to-back on the client
     * thread while a save was mid-write). The write is still atomic (temp
     * file + rename) so a crash mid-write leaves the previous file intact.</p>
     */
    public void saveData()
    {
        String username;
        String json;
        int bossCount;
        boolean fromLegacy;

        synchronized (this)
        {
            if (currentData == null)
            {
                log.debug("No data to save");
                return;
            }

            username = state.getVerifiedUsername();
            if (username == null || username.isEmpty())
            {
                log.debug("No verified username, cannot save loot data");
                return;
            }

            json      = gson.toJson(currentData);
            bossCount = currentData.getBossKills() == null ? 0 : currentData.getBossKills().size();
            fromLegacy = loadedFromLegacy;
        }

        Filepath file = getStorageFile(username);
        if (file == null)
        {
            log.debug("No plugin data directory, cannot save loot data");
            return;
        }

        // A new file must not appear while the legacy file is still in place.
        // Otherwise the next startup skips migration ("destination exists")
        // and the old history is orphaned.
        if (!file.exists() && !legacyClearedForWrite(username, fromLegacy))
        {
            log.debug("Legacy loot file for {} is still outside the plugin directory; not creating a new file", username);
            return;
        }

        try
        {
            file.getParent().createDirectories();

            // Write to a temp file, then atomically swap it into place so a
            // crash mid-write leaves the previous good file intact.
            Filepath tmp = file.getParent().joinSegment(file.getFileName() + ".tmp");
            try (Writer writer = tmp.openBufferedWriter())
            {
                writer.write(json);
            }

            try
            {
                tmp.moveTo(file,
                        StandardCopyOption.ATOMIC_MOVE,
                        StandardCopyOption.REPLACE_EXISTING);
            }
            catch (AtomicMoveNotSupportedException atomicEx)
            {
                // Some filesystems don't support atomic moves — fall back to a
                // plain replace.
                tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
            }

            log.debug("Saved loot data for {} - {} bosses", username, bossCount);
        }
        catch (Exception e)
        {
            log.debug("Failed to save loot data for {}", username, e);
        }
    }

    /**
     * Debounced save: coalesces rapid mutations into a single disk write 500ms
     * later, off the calling thread.
     */
    public synchronized void scheduleSave()
    {
        // Recreate the executor if it was shut down, since this @Singleton is
        // reused across a disable→enable cycle.
        if (saveExecutor.isShutdown())
            saveExecutor = newSaveExecutor();

        if (pendingSave != null && !pendingSave.isDone())
            pendingSave.cancel(false);
        pendingSave = saveExecutor.schedule(this::saveData, 500, java.util.concurrent.TimeUnit.MILLISECONDS);
    }

    /**
     * Add a kill to storage (no location — kept for callers that don't capture one).
     */
    public void addKill(String npcName, int npcId, int combatLevel, int killNumber, int world,
                        int prestige, List<LootStorageData.DropRecord> drops)
    {
        addKill(npcName, npcId, combatLevel, killNumber, world, prestige, drops, null);
    }

    /**
     * Add a kill to storage, recording the player's location at kill time so it
     * can be uploaded per-kill in the bulk-sync payload. {@code location} may be
     * {@code null}, in which case the kill simply carries no location.
     */
    public void addKill(String npcName, int npcId, int combatLevel, int killNumber, int world,
                        int prestige, List<LootStorageData.DropRecord> drops,
                        PlayerLocationSnapshot location)
    {
        // Snapshot first so a caller mutating the list cannot desync the
        // pre-computed totals from the stored kill, or throw CME mid-add.
        List<LootStorageData.DropRecord> snapshot =
                drops == null ? new ArrayList<>() : new ArrayList<>(drops);

        // Pre-compute aggregated stats outside lock to reduce contention
        long killValue = 0;
        Map<Integer, LootStorageData.AggregatedDrop> precomputedAggs = new HashMap<>();

        for (LootStorageData.DropRecord drop : snapshot)
        {
            killValue += drop.getTotalValue();

            precomputedAggs.computeIfAbsent(drop.getItemId(), k -> {
                LootStorageData.AggregatedDrop newAgg = new LootStorageData.AggregatedDrop();
                newAgg.setItemId(drop.getItemId());
                newAgg.setItemName(drop.getItemName());
                newAgg.setTotalQuantity(0);
                newAgg.setDropCount(0);
                newAgg.setTotalValue(0);
                newAgg.setGePrice(drop.getGePrice());
                newAgg.setHighAlch(drop.getHighAlch());
                return newAgg;
            });
        }

        synchronized (this)
        {
            if (currentData == null)
            {
                currentData = loadData();
            }

            // Get or create boss data
            LootStorageData.BossKillData bossData = currentData.getBossKills()
                    .computeIfAbsent(npcName, k -> {
                        LootStorageData.BossKillData newBoss = new LootStorageData.BossKillData();
                        newBoss.setNpcName(npcName);
                        newBoss.setNpcId(npcId);
                        newBoss.setKillCount(0);
                        newBoss.setPrestige(prestige);
                        newBoss.setTotalLootValue(0);
                        return newBoss;
                    });

            // Create kill record with the snapshot (caller can't mutate stored kills)
            LootStorageData.KillRecord killRecord = new LootStorageData.KillRecord();
            killRecord.setTimestamp(System.currentTimeMillis());
            killRecord.setKillNumber(killNumber);
            killRecord.setWorld(world);
            killRecord.setCombatLevel(combatLevel);
            killRecord.setDrops(snapshot);
            killRecord.setSyncedToServer(false);
            killRecord.setLocation(location);

            // Add kill to list
            bossData.getKills().add(killRecord);

            // Update aggregated stats with pre-computed values
            bossData.setKillCount(killNumber);
            bossData.setPrestige(prestige);

            for (LootStorageData.DropRecord drop : snapshot)
            {
                LootStorageData.AggregatedDrop aggDrop = bossData.getAggregatedDrops()
                        .computeIfAbsent(drop.getItemId(), k -> precomputedAggs.get(drop.getItemId()));

                aggDrop.setTotalQuantity(aggDrop.getTotalQuantity() + drop.getQuantity());
                aggDrop.setDropCount(aggDrop.getDropCount() + 1);
                aggDrop.setTotalValue(aggDrop.getTotalValue() + drop.getTotalValue());

                if (aggDrop.getGePrice() <= 0 && drop.getGePrice() > 0)  aggDrop.setGePrice(drop.getGePrice());
                if (aggDrop.getHighAlch() <= 0 && drop.getHighAlch() > 0) aggDrop.setHighAlch(drop.getHighAlch());
                if (drop.isPet()) aggDrop.setPet(true);
            }

            bossData.setTotalLootValue(bossData.getTotalLootValue() + killValue);

            currentData.setRevision(currentData.getRevision() + 1);

            scheduleSave();
        }

        log.debug("Added kill #{} for {} - {} drops, {} gp",
                killNumber, npcName, snapshot.size(), killValue);
    }

    /**
     * Appends extra drops to the most recent kill record for {@code npcName}.
     *
     * <p>Used for Ring of Wealth auto-collected coins that bypass
     * {@code ItemSpawned}.</p>
     *
     * @param npcName normalised boss name matching the existing storage key
     * @param drops   additional drops to merge into the last kill
     */
    public synchronized void appendDropsToLastKill(String npcName, List<LootStorageData.DropRecord> drops)
    {
        if (currentData == null || drops == null || drops.isEmpty()) return;

        LootStorageData.BossKillData bossData = currentData.getBossKills().get(npcName);
        if (bossData == null || bossData.getKills().isEmpty()) return;

        LootStorageData.KillRecord lastKill =
                bossData.getKills().get(bossData.getKills().size() - 1);

        lastKill.getDrops().addAll(drops);
        lastKill.setSyncedToServer(false);

        // Update aggregated stats for the new drops
        for (LootStorageData.DropRecord drop : drops)
        {
            LootStorageData.AggregatedDrop agg = bossData.getAggregatedDrops()
                    .computeIfAbsent(drop.getItemId(), k -> {
                        LootStorageData.AggregatedDrop a = new LootStorageData.AggregatedDrop();
                        a.setItemId(drop.getItemId());
                        a.setItemName(drop.getItemName());
                        a.setTotalQuantity(0);
                        a.setDropCount(0);
                        a.setTotalValue(0);
                        a.setGePrice(drop.getGePrice());
                        a.setHighAlch(drop.getHighAlch());
                        return a;
                    });

            agg.setTotalQuantity(agg.getTotalQuantity() + drop.getQuantity());
            agg.setDropCount(agg.getDropCount() + 1);
            agg.setTotalValue(agg.getTotalValue() + drop.getTotalValue());
            bossData.setTotalLootValue(bossData.getTotalLootValue() + drop.getTotalValue());

            if (agg.getGePrice() <= 0 && drop.getGePrice() > 0)   agg.setGePrice(drop.getGePrice());
            if (agg.getHighAlch() <= 0 && drop.getHighAlch() > 0) agg.setHighAlch(drop.getHighAlch());
            if (drop.isPet()) agg.setPet(true);
        }

        scheduleSave();
        log.debug("Appended {} drop(s) to last '{}' kill", drops.size(), npcName);
    }

    /**
     * Records the last authoritative in-game kill count for a boss.
     * Raise-only: a lower value never overwrites a higher one (stale or
     * out-of-order KC messages must not regress the stored floor).
     */
    public synchronized void recordLastGameKc(String npcName, int gameKC)
    {
        if (npcName == null || gameKC <= 0) return;
        if (currentData == null) currentData = loadData();
        if (currentData == null) return;

        if (currentData.getLastGameKcByBoss() == null)
        {
            // Files written by pre-2.0.6 versions deserialize without the map.
            currentData.setLastGameKcByBoss(new HashMap<>());
        }

        Integer existing = currentData.getLastGameKcByBoss().get(npcName);
        if (existing != null && existing >= gameKC) return;

        currentData.getLastGameKcByBoss().put(npcName, gameKC);
        scheduleSave();
    }

    /**
     * Relabels the most recent kill record for {@code npcName} with the
     * authoritative game kill count that arrived in chat just after the kill
     * was recorded. Rename-only — never adds or removes a kill.
     *
     * @return {@code true} if the record was relabeled; {@code false} when
     *         there is no eligible record (none exists, the last kill already
     *         carries an equal/higher number, or it already synced to the
     *         server — relabeling a synced kill would re-upload it as a
     *         duplicate)
     */
    public synchronized boolean relabelLastKill(String npcName, int killNumber)
    {
        if (currentData == null || npcName == null || killNumber <= 0) return false;

        LootStorageData.BossKillData bossData = currentData.getBossKills().get(npcName);
        if (bossData == null || bossData.getKills().isEmpty()) return false;

        LootStorageData.KillRecord lastKill =
                bossData.getKills().get(bossData.getKills().size() - 1);

        if (lastKill.getKillNumber() >= killNumber) return false;
        if (lastKill.isSyncedToServer()) return false;

        lastKill.setKillNumber(killNumber);
        if (killNumber > bossData.getKillCount())
        {
            bossData.setKillCount(killNumber);
        }

        if (currentData.getLastGameKcByBoss() == null)
        {
            currentData.setLastGameKcByBoss(new HashMap<>());
        }
        Integer existing = currentData.getLastGameKcByBoss().get(npcName);
        if (existing == null || existing < killNumber)
        {
            currentData.getLastGameKcByBoss().put(npcName, killNumber);
        }

        scheduleSave();
        log.debug("Relabeled last '{}' kill to game KC {}", npcName, killNumber);
        return true;
    }

    /**
     * Mark kills as synced to server
     */
    public synchronized void markKillsSynced(String npcName, long fromTimestamp, long toTimestamp)
    {
        if (currentData == null) return;

        LootStorageData.BossKillData bossData = currentData.getBossKills().get(npcName);
        if (bossData == null) return;

        int syncedCount = 0;
        for (LootStorageData.KillRecord kill : bossData.getKills())
        {
            if (kill.getTimestamp() >= fromTimestamp && kill.getTimestamp() <= toTimestamp)
            {
                kill.setSyncedToServer(true);
                syncedCount++;
            }
        }

        if (syncedCount > 0)
        {
            saveData();
            log.debug("Marked {} kills as synced for {}", syncedCount, npcName);
        }
    }

    /**
     * Get unsynced kills for upload
     */
    public synchronized List<LootStorageData.KillRecord> getUnsyncedKills(String npcName)
    {
        if (currentData == null) return Collections.emptyList();

        LootStorageData.BossKillData bossData = currentData.getBossKills().get(npcName);
        if (bossData == null) return Collections.emptyList();

        List<LootStorageData.KillRecord> unsynced = new ArrayList<>();
        for (LootStorageData.KillRecord kill : bossData.getKills())
        {
            if (!kill.isSyncedToServer())
            {
                unsynced.add(kill);
            }
        }

        return unsynced;
    }

    /**
     * Get all unsynced kills across all bosses
     */
    public synchronized Map<String, List<LootStorageData.KillRecord>> getAllUnsyncedKills()
    {
        if (currentData == null) return Collections.emptyMap();

        Map<String, List<LootStorageData.KillRecord>> result = new HashMap<>();

        for (Map.Entry<String, LootStorageData.BossKillData> entry : currentData.getBossKills().entrySet())
        {
            List<LootStorageData.KillRecord> unsynced = getUnsyncedKills(entry.getKey());
            if (!unsynced.isEmpty())
            {
                result.put(entry.getKey(), unsynced);
            }
        }

        return result;
    }

    /**
     * Merges server data into the in-memory copy. Server kills for a boss are
     * only added when the server has more kills than the client. Call only
     * during manual sync operations.
     */
    public synchronized void mergeServerData(Map<String, LootStorageData.BossKillData> serverData)
    {
        mergeServerData(serverData, true);
    }

    /**
     * Merges server data into the in-memory copy. Server kills for a boss are
     * only added when the server has more kills than the client.
     *
     * @param manualSync when {@code true}, verbose merge details are logged;
     *                   when {@code false}, only essential debug info is logged
     */
    public synchronized void mergeServerData(Map<String, LootStorageData.BossKillData> serverData, boolean manualSync)
    {
        if (manualSync)
            log.debug("mergeServerData() called during manual sync");

        // Merge into the in-memory copy; load from disk only if nothing is
        // loaded yet this session.
        if (currentData == null)
        {
            currentData = loadData();
        }

        if (currentData == null)
        {
            if (manualSync)
                log.debug("Failed to load client data - aborting merge");
            return;
        }

        int killsAdded = 0;
        int dropsAdded = 0;
        int bossesSkipped = 0;
        boolean killCountOnlyUpdated = false;

        for (Map.Entry<String, LootStorageData.BossKillData> entry : serverData.entrySet())
        {
            String npcName = entry.getKey();
            LootStorageData.BossKillData serverBoss = entry.getValue();

            // Check if boss exists in client data
            LootStorageData.BossKillData localBoss = currentData.getBossKills().get(npcName);

            // If boss exists locally
            if (localBoss != null)
            {
                // Client has equal or more kills; keep client data.
                if (localBoss.getKillCount() >= serverBoss.getKillCount())
                {
                    if (manualSync)
                        log.debug("❌ SKIPPING SERVER DATA: {} - Client KC {} >= Server KC {}",
                                npcName, localBoss.getKillCount(), serverBoss.getKillCount());
                    bossesSkipped++;
                    continue; // Skip this boss entirely - client has fresher data
                }

                // Server has MORE kills - merge the new ones
                if (manualSync)
                    log.debug("✅ MERGING: {} - Server KC {} > Client KC {}",
                            npcName, serverBoss.getKillCount(), localBoss.getKillCount());
            }
            else
            {
                // Boss doesn't exist locally yet. Only worth creating a row at
                // all if the server actually reports kills/loot for it — don't
                // create a 0-KC, no-drop placeholder that would just show as an
                // empty container on the panel.
                boolean serverHasRealData = serverBoss.getKillCount() > 0
                        || (serverBoss.getKills() != null && !serverBoss.getKills().isEmpty())
                        || (serverBoss.getAggregatedDrops() != null
                                && serverBoss.getAggregatedDrops().values().stream()
                                        .anyMatch(d -> d.getTotalQuantity() > 0));
                if (!serverHasRealData)
                {
                    if (manualSync)
                        log.debug("❌ SKIPPING SERVER DATA: {} - no kills/loot reported, not creating placeholder",
                                npcName);
                    bossesSkipped++;
                    continue;
                }

                if (manualSync)
                    log.debug("➕ NEW BOSS from server: {} with {} kills", npcName, serverBoss.getKillCount());
                localBoss = new LootStorageData.BossKillData();
                localBoss.setNpcName(npcName);
                localBoss.setNpcId(serverBoss.getNpcId());
                localBoss.setKillCount(0);
                localBoss.setPrestige(0);
                localBoss.setTotalLootValue(0);
                currentData.getBossKills().put(npcName, localBoss);
            }

            // Per-boss counter, separate from the running cross-boss killsAdded total.
            int bossKillsAdded = 0;

            // Build set of existing kill timestamps and kill numbers (client data)
            Set<Long> existingTimestamps = new HashSet<>();
            Set<Integer> existingKillNumbers = new HashSet<>();

            for (LootStorageData.KillRecord kill : localBoss.getKills())
            {
                existingTimestamps.add(kill.getTimestamp());
                existingKillNumbers.add(kill.getKillNumber());
            }

            // Add only server kills not already present. Dedup is by kill
            // timestamp (±1s), the key the server uses. The kill number is only
            // used as a dedup key when it is a real positive value, since
            // history kills arrive with killNumber 0.
            for (LootStorageData.KillRecord serverKill : serverBoss.getKills())
            {
                boolean existsByTimestamp = false;
                for (long existingTs : existingTimestamps)
                {
                    if (Math.abs(existingTs - serverKill.getTimestamp()) <= 1000)
                    {
                        existsByTimestamp = true;
                        break;
                    }
                }

                boolean existsByKillNumber = serverKill.getKillNumber() > 0
                        && existingKillNumbers.contains(serverKill.getKillNumber());

                // Skip if exists by either method
                if (existsByTimestamp || existsByKillNumber)
                {
                    continue;
                }

                // This is a NEW kill - add it
                serverKill.setSyncedToServer(true);

                // Filter out deleted drops before adding the kill. This prevents
                // deleted items from reappearing when server data is merged back.
                Set<Integer> deletedForBoss = currentData.getDeletedDropsByBoss().get(npcName);
                if (deletedForBoss != null && !deletedForBoss.isEmpty())
                {
                    serverKill.getDrops().removeIf(drop -> deletedForBoss.contains(drop.getItemId()));
                }

                localBoss.getKills().add(serverKill);
                killsAdded++;
                bossKillsAdded++;

                if (manualSync)
                    log.debug("Added missing kill #{} from server: {} at timestamp {}",
                            serverKill.getKillNumber(), npcName, serverKill.getTimestamp());

                // Update aggregated drops
                for (LootStorageData.DropRecord drop : serverKill.getDrops())
                {
                    LootStorageData.AggregatedDrop aggDrop = localBoss.getAggregatedDrops()
                            .computeIfAbsent(drop.getItemId(), k -> {
                                LootStorageData.AggregatedDrop newAgg = new LootStorageData.AggregatedDrop();
                                newAgg.setItemId(drop.getItemId());
                                newAgg.setItemName(drop.getItemName());
                                newAgg.setTotalQuantity(0);
                                newAgg.setDropCount(0);
                                newAgg.setTotalValue(0);
                                newAgg.setGePrice(drop.getGePrice());
                                newAgg.setHighAlch(drop.getHighAlch());
                                return newAgg;
                            });

                    aggDrop.setTotalQuantity(aggDrop.getTotalQuantity() + drop.getQuantity());
                    aggDrop.setDropCount(aggDrop.getDropCount() + 1);
                    aggDrop.setTotalValue(aggDrop.getTotalValue() + drop.getTotalValue());

                    if (aggDrop.getGePrice() <= 0 && drop.getGePrice() > 0)   aggDrop.setGePrice(drop.getGePrice());
                    if (aggDrop.getHighAlch() <= 0 && drop.getHighAlch() > 0) aggDrop.setHighAlch(drop.getHighAlch());
                    if (drop.isPet()) aggDrop.setPet(true);
                    dropsAdded++;
                }
            }

            // Update kill count and prestige from server when kills were merged
            // for this boss, OR when the server simply reports a higher
            // aggregate kill count than we have locally (max-wins, same rule
            // applied to item quantities elsewhere).
            if (bossKillsAdded > 0 || serverBoss.getKillCount() > localBoss.getKillCount())
            {
                if (bossKillsAdded == 0) killCountOnlyUpdated = true;
                int originalKillCount = localBoss.getKillCount();
                int originalPrestige = localBoss.getPrestige();
                long originalValue = localBoss.getTotalLootValue();

                localBoss.setKillCount(serverBoss.getKillCount()); // Server has more, use that
                localBoss.setPrestige(Math.max(localBoss.getPrestige(), serverBoss.getPrestige()));

                // Recalculate total value from ALL kills in memory
                long recalculatedValue = 0;
                for (LootStorageData.KillRecord kill : localBoss.getKills())
                {
                    for (LootStorageData.DropRecord drop : kill.getDrops())
                    {
                        recalculatedValue += drop.getTotalValue();
                    }
                }
                localBoss.setTotalLootValue(recalculatedValue);

                if (manualSync)
                    log.debug("Updated {} stats - KC: {} -> {}, Prestige: {} -> {}, Value: {} -> {}",
                            npcName,
                            originalKillCount, localBoss.getKillCount(),
                            originalPrestige, localBoss.getPrestige(),
                            originalValue, localBoss.getTotalLootValue());
            }
        }

        if (killsAdded > 0 || dropsAdded > 0 || killCountOnlyUpdated)
        {
            currentData.setLastSyncTimestamp(System.currentTimeMillis());
            saveData();
            if (manualSync)
                log.debug("Merge complete: Added {} kills, {} drops from server ({} bosses skipped - client data equal/newer)",
                        killsAdded, dropsAdded, bossesSkipped);
        }
        else
        {
            if (manualSync)
                log.debug("Merge complete: No new data from server ({} bosses skipped - client data equal/newer)",
                        bossesSkipped);
        }
    }

    /**
     * Get current data
     */
    public synchronized LootStorageData getCurrentData()
    {
        if (currentData == null)
        {
            return loadData();
        }
        return currentData;
    }

    /**
     * Persists the current account's data to disk immediately (cancelling any
     * pending debounced save). Call on logout, while
     * {@link RuneAlyticsState#getVerifiedUsername()} still refers to the account
     * whose data is in memory, so nothing is lost before {@link #dropCache()}.
     */
    public synchronized void flushNow()
    {
        if (pendingSave != null && !pendingSave.isDone())
        {
            pendingSave.cancel(false);
            pendingSave = null;
        }
        saveData();
    }

    /**
     * Drops the in-memory copy so the next {@link #getCurrentData()} reloads the
     * file for whichever account is logged in now. Prevents one account's loot
     * from being read/written under another account after a profile switch.
     *
     * <p>Does NOT write to disk — callers must {@link #flushNow()} first if the
     * cached data still needs persisting.</p>
     */
    public synchronized void dropCache()
    {
        currentData = null;
        loadedFromLegacy = false;
    }

    /**
     * Flushes any pending save and stops the background save executor.
     */
    public synchronized void shutdown()
    {
        if (pendingSave != null && !pendingSave.isDone())
        {
            pendingSave.cancel(false);
            pendingSave = null;
        }
        saveData();
        saveExecutor.shutdown();
    }

    /**
     * Clear all data for current user
     */
    public synchronized void clearData()
    {
        String username = state.getVerifiedUsername();
        if (username == null || username.isEmpty()) return;

        currentData = new LootStorageData();
        currentData.setUsername(username);
        saveData();

        log.debug("Cleared all loot data for {}", username);
    }

    /**
     * Get storage file for username, or null if no data directory is set
     */
    Filepath getStorageFile(String username)
    {
        Filepath directory = dataDirectory;
        if (directory == null) return null;

        return directory.joinSegment(STORAGE_FILE_PREFIX + sanitizeUsername(username) + STORAGE_FILE_SUFFIX);
    }

    private static String sanitizeUsername(String username)
    {
        return username.toLowerCase().replaceAll("[^a-z0-9_-]", "_");
    }

    /** Legacy {@code ~/.runelite/runealytics-loot-<user>.json}, or null when unset. */
    private File legacyFileFor(String username)
    {
        File legacyDir = legacyDirectory;
        if (legacyDir == null || username == null || username.isEmpty()) return null;
        return new File(legacyDir, LEGACY_FILE_PREFIX + sanitizeUsername(username) + STORAGE_FILE_SUFFIX);
    }

    /**
     * @return {@code true} when creating the plugin-directory file will not
     *         orphan a legacy file. A move is retried only when memory was
     *         loaded from that legacy file, so a failed read cannot be saved
     *         back over the original.
     */
    private boolean legacyClearedForWrite(String username, boolean fromLegacy)
    {
        File legacy = legacyFileFor(username);
        if (legacy == null || !legacy.isFile()) return true;

        if (fromLegacy)
        {
            Filepath directory = dataDirectory;
            if (directory != null)
            {
                migrateLegacyFiles(legacy.getParentFile(), directory);
            }

            Filepath file = getStorageFile(username);
            if (file != null && file.exists()) return true;
        }

        return false;
    }
}

package com.runealytics;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

/**
 * Reads RuneLite's own default Loot Tracker totals and submits them to the
 * RuneAlytics website via the sync-absolute endpoint.
 *
 * <h2>Merge algorithm (max-absolute)</h2>
 * <p>For each player account, source (boss/NPC), and item:</p>
 * <ol>
 *   <li>Read RuneLite's own default Loot Tracker totals straight from its
 *       {@code profiles2/*.properties} save file via
 *       {@link DefaultRuneLiteLootTrackerReader#readForAccount(String)},
 *       scoped to the currently logged-in OSRS username. This is read fresh
 *       on every sync — RuneLite's file is the source of truth, never a
 *       plugin-side cache or temp file.</li>
 *   <li>Update the plugin local cache (display only) to the merged totals,
 *       raising existing per-item/KC values but never lowering them.</li>
 *   <li>{@code POST} merged totals to {@code /runelite/loot/sync-absolute}.</li>
 * </ol>
 *
 * <h2>Website snapshot leg</h2>
 * <p>The website's {@code /runelite/loot/snapshot} endpoint is also merged
 * in (fetched first, below) — for each (source, item) tuple, the final
 * quantity is {@code max(website, runelite_default)}. Any source whose name
 * or key still contains raw chat-message markup (e.g. {@code <col=...>}
 * tags) is rejected defensively, since that indicates malformed upstream
 * data rather than a real NPC/source name.</p>
 *
 * <h2>Important: RuneLite default tracker data is absolute</h2>
 * <p>RuneLite's Loot Tracker stores cumulative totals, not incremental new
 * drops.  They must never be treated as new kills to add on top of existing
 * data — only as the value applied via max-absolute.</p>
 *
 * <h2>Account guard</h2>
 * <p>Before doing anything, {@link CurrentPlayerIdentityService#canSync()} is
 * checked.  If the in-client account does not match the RuneAlytics linked
 * account, the merge is aborted and a descriptive error is returned.</p>
 */
@Slf4j
@Singleton
public class LootSyncMergeService
{
    /** Max time to wait for the client thread to resolve RuneLite item names. */
    private static final long NAME_RESOLVE_TIMEOUT_MS = 5_000;

    private final CurrentPlayerIdentityService  identity;
    private final LootStorageManager            storageManager;
    private final LootTrackerApiClient          apiClient;
    private final DefaultRuneLiteLootTrackerReader rlReader;
    private final ItemManager                   itemManager;
    private final ClientThread                  clientThread;

    @Inject
    public LootSyncMergeService(
            CurrentPlayerIdentityService identity,
            LootStorageManager storageManager,
            LootTrackerApiClient apiClient,
            DefaultRuneLiteLootTrackerReader rlReader,
            ItemManager itemManager,
            ClientThread clientThread)
    {
        this.identity       = identity;
        this.storageManager = storageManager;
        this.apiClient      = apiClient;
        this.rlReader       = rlReader;
        this.itemManager    = itemManager;
        this.clientThread   = clientThread;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /**
     * Performs the full website + RuneLite-tracker merge for the currently
     * logged-in account.
     *
     * <p>Must be called from a background executor thread, never from the
     * RuneLite client thread (network I/O is involved).</p>
     *
     * @return a {@link MergeResult} describing what happened; check
     *         {@link MergeResult#success} before reading other fields
     */
    public MergeResult performMerge()
    {
        return performMerge(true);
    }

    /**
     * Performs the full website + RuneLite-tracker merge for the currently
     * logged-in account.
     *
     * <p>Must be called from a background executor thread, never from the
     * RuneLite client thread (network I/O is involved).</p>
     *
     * @param manualSync when {@code true}, verbose merge details are logged;
     *                   when {@code false}, only essential debug info is logged
     * @return a {@link MergeResult} describing what happened; check
     *         {@link MergeResult#success} before reading other fields
     */
    public MergeResult performMerge(boolean manualSync)
    {
        // ── 1. Account guard ─────────────────────────────────────────────────
        if (!identity.canSync())
        {
            String msg = identity.getMismatchMessage();
            log.debug("[merge] Sync blocked: {}", msg);
            return MergeResult.blocked(msg);
        }

        String accountKey = identity.getAccountKey();
        if (accountKey == null)
        {
            return MergeResult.blocked("No RuneScape account detected. Log in before syncing.");
        }

        return performMergeForAccount(accountKey, manualSync);
    }

    /**
     * Performs the three-source merge for an explicitly supplied
     * {@code accountKey}.
     *
     * <p>Unlike {@link #performMerge()}, this does not re-read the live client
     * identity, so it is safe to call during a logout flush (when the local
     * player is already gone). Callers are responsible for having validated
     * that {@code accountKey} is the account that should be synced (e.g. via
     * {@link CurrentPlayerIdentityService#isLinkedAccount(String)}).</p>
     *
     * @param accountKey normalized RuneScape account name; must be non-null
     */
    public MergeResult performMergeForAccount(String accountKey)
    {
        return performMergeForAccount(accountKey, true);
    }

    /**
     * Performs the three-source merge for an explicitly supplied
     * {@code accountKey}.
     *
     * <p>Unlike {@link #performMerge()}, this does not re-read the live client
     * identity, so it is safe to call during a logout flush (when the local
     * player is already gone). Callers are responsible for having validated
     * that {@code accountKey} is the account that should be synced (e.g. via
     * {@link CurrentPlayerIdentityService#isLinkedAccount(String)}).</p>
     *
     * @param accountKey normalized RuneScape account name; must be non-null
     * @param manualSync when {@code true}, verbose merge details are logged;
     *                   when {@code false}, only essential debug info is logged
     */
    public MergeResult performMergeForAccount(String accountKey, boolean manualSync)
    {
        if (accountKey == null || accountKey.isEmpty())
        {
            return MergeResult.blocked("No RuneScape account detected. Log in before syncing.");
        }

        if (manualSync)
            log.debug("[merge] Starting merge for account '{}'", accountKey);

        // ── 2. Read RuneLite default tracker first (best-effort, account-filtered) ──
        // Read directly from RuneLite's own profiles2/*.properties save file
        // on every sync — never from a plugin-side cache or temp file. This is
        // the canonical source of truth for what RuneLite has tracked, and is
        // checked before the website so that anything RuneLite has tracked
        // locally but the website hasn't seen yet still gets uploaded below.
        boolean rlAvailable = rlReader.canImportHistorical();
        Map<String, DefaultRuneLiteLootTrackerReader.SourceTotals> rlTotals = Collections.emptyMap();
        boolean rlSkippedDueToAccount = false;

        if (rlAvailable)
        {
            rlTotals = rlReader.readForAccount(accountKey);
            rlSkippedDueToAccount = rlTotals.isEmpty();
            if (manualSync)
                log.debug("[merge] RuneLite tracker: {} sources (account-filtered)", rlTotals.size());
        }
        else
        {
            if (manualSync)
                log.debug("[merge] RuneLite Loot Tracker historical data cannot be safely matched to "
                        + "this account. Using website data only.");
        }

        // ── 3. Fetch website snapshot ──────────────────────────────────────────
        // Fetched after RuneLite so the merge below can fill/raise anything
        // the website is missing relative to what RuneLite has tracked.
        LootTrackerApiClient.LootSnapshot websiteSnapshot = null;
        try
        {
            websiteSnapshot = apiClient.fetchLootSnapshot(accountKey);
            if (manualSync)
                log.debug("[merge] Website snapshot: {} sources",
                        websiteSnapshot != null ? websiteSnapshot.sources.size() : "null (fetch failed)");
        }
        catch (IOException e)
        {
            if (manualSync)
                log.debug("[merge] Failed to fetch website snapshot: {}", e.getMessage());
            // Non-fatal: continue with RuneLite data only.
        }

        // Local cache — used as a merge input so local plugin tracking is
        // included in the max-wins merge alongside RuneLite and website.
        LootStorageData localData = storageManager.getCurrentData();

        // ── 5. Item + kill-count merge ────────────────────────────────────────
        MergeContext ctx = new MergeContext(accountKey);

        // RuneLite default tracker leg — merged first.
        // RuneLite stores only item IDs, so names are resolved via ItemManager —
        // which MUST run on the client thread. Resolve every needed name up front
        // in a single client-thread hop rather than per-item inside this loop.
        Set<Integer> rlItemIds = new HashSet<>();
        for (DefaultRuneLiteLootTrackerReader.SourceTotals t : rlTotals.values()) rlItemIds.addAll(t.items.keySet());
        Map<Integer, String> rlItemNames = resolveItemNames(rlItemIds);

        for (Map.Entry<String, DefaultRuneLiteLootTrackerReader.SourceTotals> srcEntry : rlTotals.entrySet())
        {
            String sourceName = srcEntry.getKey();
            String sourceKey  = normalizeBossKey(sourceName);
            DefaultRuneLiteLootTrackerReader.SourceTotals totals = srcEntry.getValue();

            ctx.mergeKillCount(sourceKey, sourceName, totals.killCount, "runelite_default_loot_tracker");

            for (Map.Entry<Integer, Long> itemEntry : totals.items.entrySet())
            {
                int  itemId = itemEntry.getKey();
                long qty    = itemEntry.getValue();
                String itemName = rlItemNames.getOrDefault(itemId, "Item " + itemId);
                ctx.mergeItem(sourceKey, sourceName, null,
                        itemId, itemName, qty, "runelite_default_loot_tracker");
            }
        }

        // Website leg — merged second, so it only raises values RuneLite's
        // tracker didn't already have at least as high; anything RuneLite
        // had that the website was missing is still in `ctx` and will be
        // uploaded back to the website in step 7 below, keeping both sides
        // in sync regardless of which one was behind.
        if (websiteSnapshot != null)
        {
            for (LootTrackerApiClient.LootSnapshot.SourceData srcData : websiteSnapshot.sources.values())
            {
                if (hasMarkup(srcData.sourceKey) || hasMarkup(srcData.sourceName))
                {
                    if (manualSync)
                        log.debug("[merge] Rejected website source with malformed name/key: key='{}' name='{}'",
                                srcData.sourceKey, srcData.sourceName);
                    continue;
                }

                for (Map.Entry<String, Long> e : srcData.itemTotals.entrySet())
                {
                    String itemKey = e.getKey();
                    long   qty     = e.getValue();
                    if (qty <= 0) continue; // never surface a zero-quantity drop
                    int    itemId  = websiteSnapshot.itemIdsByKey.getOrDefault(itemKey, 0);
                    String name    = websiteSnapshot.itemNamesByKey.getOrDefault(itemKey, itemKey);
                    if (hasMarkup(name)) continue;
                    ctx.mergeItem(srcData.sourceKey, srcData.sourceName, null,
                            itemId, name, qty, "website");
                }
            }
        }

        // NOTE: the website snapshot has no per-source kill_count field (only
        // items), so there is no real "website KC" to merge here. The
        // account's already-recorded kill count is preserved as a floor
        // directly in applyMergedToLocalStorage (it only ever raises KC, never
        // lowers it), so nothing is lost by not looping it back through here.

        // Local plugin data leg — merged third, so it can raise any values that
        // both RuneLite and website are missing or underestimating. This ensures
        // local plugin tracking (player's actual loot) participates in max-wins merge.
        if (localData != null && !localData.getBossKills().isEmpty())
        {
            for (Map.Entry<String, LootStorageData.BossKillData> bossEntry : localData.getBossKills().entrySet())
            {
                String bossName = bossEntry.getKey();
                String bossKey = normalizeBossKey(bossName);
                LootStorageData.BossKillData bossData = bossEntry.getValue();

                if (bossData.getKillCount() > 0)
                {
                    ctx.mergeKillCount(bossKey, bossName, bossData.getKillCount(), "local_plugin_tracking");
                }

                if (!bossData.getAggregatedDrops().isEmpty())
                {
                    for (Map.Entry<Integer, LootStorageData.AggregatedDrop> dropEntry : bossData.getAggregatedDrops().entrySet())
                    {
                        LootStorageData.AggregatedDrop drop = dropEntry.getValue();
                        if (drop.getTotalQuantity() > 0)
                        {
                            ctx.mergeItem(bossKey, bossName, null,
                                    drop.getItemId(), drop.getItemName(), drop.getTotalQuantity(), "local_plugin_tracking");
                        }
                    }
                }
            }
            if (manualSync)
                log.debug("[merge] Local plugin data: {} sources merged", localData.getBossKills().size());
        }

        List<MergedSource> merged = ctx.build();
        if (manualSync)
            log.debug("[merge] Merge complete: {} sources, {} items total",
                    merged.size(),
                    merged.stream().mapToInt(s -> s.items.size()).sum());

        // ── 6. Apply merged totals to plugin local storage ────────────────────
        applyMergedToLocalStorage(merged, localData, manualSync);

        // ── 7. Submit merged totals to website ────────────────────────────────
        boolean uploaded = false;
        String uploadError = null;
        try
        {
            uploaded = apiClient.syncAbsolute(accountKey, merged);
            if (manualSync)
                log.debug("[merge] sync-absolute upload: {}", uploaded ? "OK" : "FAILED");
        }
        catch (IOException e)
        {
            uploadError = e.getMessage();
            if (manualSync)
                log.debug("[merge] sync-absolute upload failed: {}", uploadError);
        }

        // ── 8. Build result summary ───────────────────────────────────────────
        int itemsTotal = merged.stream().mapToInt(s -> s.items.size()).sum();
        return MergeResult.success(
                accountKey,
                merged.size(),
                itemsTotal,
                uploaded,
                !rlAvailable || rlSkippedDueToAccount,
                uploadError);
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    /**
     * Writes the merged item totals back to the plugin local cache so that
     * the UI immediately reflects the highest-known absolute quantities.
     *
     * <p>This updates the {@link LootStorageData.BossKillData#aggregatedDrops}
     * map for each source using max(existing, merged) — it does NOT add
     * fake kill records.</p>
     *
     * @param manualSync when {@code true}, verbose merge details are logged
     */
    private void applyMergedToLocalStorage(List<MergedSource> merged, LootStorageData localData, boolean manualSync)
    {
        for (MergedSource src : merged)
        {
            // Skip sources with no actual loot AND no kill count — don't create
            // an empty placeholder row (0 KC, no drops) on the panel.
            boolean hasLoot = src.items.stream().anyMatch(i -> i.quantity > 0);
            if (!hasLoot && src.killCount <= 0) continue;

            // Resolve the storage key by canonical name, not the raw merge
            // name. RuneLite's tracker / the website snapshot can report a
            // source name that differs slightly in case/spacing from
            // whatever LootTrackerManager.normalizeBossName() produced when
            // the entry was first created locally (e.g. via real gameplay).
            // Without this, a pre-existing local entry (real kills/drops)
            // and the merge's entry land under two different exact map
            // keys, fragmenting the boss's data across two rows — one of
            // which silently shadows the other on the panel.
            String canonicalName = LootTrackerManager.normalizeBossName(src.sourceName);
            String existingKey = null;
            for (String key : localData.getBossKills().keySet())
            {
                if (canonicalName.equalsIgnoreCase(LootTrackerManager.normalizeBossName(key)))
                {
                    existingKey = key;
                    break;
                }
            }

            LootStorageData.BossKillData bossData =
                    localData.getBossKills().computeIfAbsent(
                            existingKey != null ? existingKey : canonicalName, k -> {
                                LootStorageData.BossKillData bd = new LootStorageData.BossKillData();
                                bd.setNpcName(k);
                                return bd;
                            });

            if (src.killCount > bossData.getKillCount())
            {
                bossData.setKillCount(src.killCount);
            }

            for (MergedItem item : src.items)
            {
                if (item.quantity <= 0) continue;

                LootStorageData.AggregatedDrop existing =
                        bossData.getAggregatedDrops().get(item.itemId > 0 ? item.itemId : -1);

                if (existing == null)
                {
                    LootStorageData.AggregatedDrop agg = new LootStorageData.AggregatedDrop();
                    agg.setItemId(item.itemId);
                    agg.setItemName(item.itemName);
                    agg.setTotalQuantity((int) Math.min(item.quantity, Integer.MAX_VALUE));
                    agg.setDropCount(1);
                    // GE/alch price + totalValue are resolved later on the
                    // client thread by LootTrackerManager.backfillAllMissingDropValues
                    // — ItemManager can't be called from this background thread.
                    bossData.getAggregatedDrops().put(item.itemId > 0 ? item.itemId : -1, agg);
                }
                else
                {
                    int newQty = (int) Math.min(
                            Math.max(existing.getTotalQuantity(), item.quantity), Integer.MAX_VALUE);
                    existing.setTotalQuantity(newQty);
                }
            }
        }

        storageManager.scheduleSave();
        if (manualSync)
            log.debug("[merge] Applied merged totals to local storage");
    }

    /**
     * Detects raw chat-message markup (e.g. {@code <col=00ffff>...</col>})
     * leaking into a source/item name — a sign of malformed upstream data
     * that must never reach the merge or the panel.
     */
    private static boolean hasMarkup(String s)
    {
        return s != null && s.contains("<col=");
    }

    /**
     * Normalizes a boss/source name to a stable lowercase key, matching the
     * server-side normalization in {@code RuneLiteLootService::normalizeSourceKey}.
     */
    static String normalizeBossKey(String name)
    {
        if (name == null) return "";
        name = name.replace('\u00A0', ' ').trim().toLowerCase();
        name = name.replaceAll("['\u2019\u2018]", "");
        name = name.replaceAll("\\s+", "_");
        return name;
    }

    /**
     * Resolves display names for the given item IDs via {@link ItemManager}.
     *
     * <p>{@code ItemManager.getItemComposition} asserts it is called on the
     * client thread, so the whole batch is resolved inside a single
     * {@link ClientThread} hop and we block (with a timeout) for the result.
     * This method is only ever called from the background sync executor — never
     * the client thread — so blocking here cannot deadlock the game loop. Item
     * IDs that can't be resolved fall back to {@code "Item <id>"}.</p>
     */
    private Map<Integer, String> resolveItemNames(Set<Integer> itemIds)
    {
        Map<Integer, String> names = new java.util.concurrent.ConcurrentHashMap<>();
        if (itemIds == null || itemIds.isEmpty()) return names;

        CountDownLatch latch = new CountDownLatch(1);
        clientThread.invokeLater(() ->
        {
            try     { for (int id : itemIds) names.put(id, safeItemName(id)); }
            finally { latch.countDown(); }
        });

        try
        {
            if (!latch.await(NAME_RESOLVE_TIMEOUT_MS, TimeUnit.MILLISECONDS))
            {
                log.debug("[merge] Timed out resolving {} RuneLite item name(s); using fallbacks",
                        itemIds.size());
            }
        }
        catch (InterruptedException e)
        {
            log.debug("[merge] Interrupted while resolving item names; using fallbacks");
        }

        // Backfill any IDs the client thread didn't resolve in time.
        for (int id : itemIds) names.putIfAbsent(id, "Item " + id);
        return names;
    }

    /** Resolves a single item name; MUST be called on the client thread. */
    private String safeItemName(int itemId)
    {
        try
        {
            net.runelite.api.ItemComposition comp = itemManager.getItemComposition(itemId);
            return comp != null && comp.getName() != null ? comp.getName() : "Item " + itemId;
        }
        catch (Exception e)
        {
            return "Item " + itemId;
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  MERGE CONTEXT (internal accumulator)
    // ═════════════════════════════════════════════════════════════════════════

    private static class MergeContext
    {
        /** Map: sourceKey → (itemKey → MutableItem) */
        private final Map<String, Map<String, MutableItem>> data = new LinkedHashMap<>();
        /** Map: sourceKey → merged (max) kill count seen so far. */
        private final Map<String, Integer> killCounts       = new LinkedHashMap<>();
        /** Map: sourceKey → which source ("website"/"runelite_default_loot_tracker") last won the kill count. */
        private final Map<String, String>  killCountWinners = new LinkedHashMap<>();
        /** Map: sourceKey → display name, captured even if a source has no items. */
        private final Map<String, String>  killCountSourceNames = new LinkedHashMap<>();
        private final String accountKey;

        MergeContext(String accountKey)
        {
            this.accountKey = accountKey;
        }

        void mergeItem(String sourceKey, String sourceName, String sourceType,
                int itemId, String itemName, long quantity, String source)
        {
            String itemKey = itemId > 0
                    ? "id_" + itemId
                    : "name_" + (itemName != null ? itemName.toLowerCase().trim() : "");

            Map<String, MutableItem> sourceMap =
                    data.computeIfAbsent(sourceKey, k -> new LinkedHashMap<>());

            MutableItem item = sourceMap.get(itemKey);
            if (item == null)
            {
                item = new MutableItem(itemKey, itemId, itemName, sourceType);
                sourceMap.put(itemKey, item);
            }

            if (quantity > item.quantity)
            {
                item.quantity    = quantity;
                item.winnerSource = source;
            }

            // Prefer itemId / itemName from the richer source.
            if (item.itemId <= 0 && itemId > 0) item.itemId = itemId;
            if ((item.itemName == null || item.itemName.isEmpty()) && itemName != null)
                item.itemName = itemName;

            // Persist the source name (for snapshot sourceName field).
            item.sourceNames.put(source, sourceName);
        }

        /**
         * Merges a source's reported kill count using max-wins semantics — the
         * same rule applied to item quantities: whichever source (website or
         * RuneLite's own tracker) reports the higher kill count wins.
         */
        void mergeKillCount(String sourceKey, String sourceName, int killCount, String source)
        {
            killCountSourceNames.putIfAbsent(sourceKey, sourceName);
            int existing = killCounts.getOrDefault(sourceKey, 0);
            if (killCount > existing)
            {
                killCounts.put(sourceKey, killCount);
                killCountWinners.put(sourceKey, source);
            }
        }

        List<MergedSource> build()
        {
            // Sources that only ever received a kill-count merge (e.g. RuneLite
            // tracked kills with no recorded drops) don't appear in `data` yet —
            // make sure they still produce a MergedSource so their KC isn't lost.
            Set<String> allSourceKeys = new LinkedHashSet<>(data.keySet());
            allSourceKeys.addAll(killCounts.keySet());

            List<MergedSource> result = new ArrayList<>();
            for (String sourceKey : allSourceKeys)
            {
                Map<String, MutableItem> itemMap = data.getOrDefault(sourceKey, Collections.emptyMap());
                List<MergedItem> items = new ArrayList<>();

                String sourceName = null;
                String sourceType = null;

                for (MutableItem mi : itemMap.values())
                {
                    if (sourceName == null && !mi.sourceNames.isEmpty())
                        sourceName = mi.sourceNames.values().iterator().next();
                    if (sourceType == null && mi.sourceType != null)
                        sourceType = mi.sourceType;

                    String reason = "max_of_website_runelite (winner: " + mi.winnerSource + ")";
                    items.add(new MergedItem(mi.itemId,
                            mi.itemName != null ? mi.itemName : "Unknown",
                            mi.quantity,
                            reason));
                }

                int    killCount       = killCounts.getOrDefault(sourceKey, 0);
                String killCountWinner = killCountWinners.get(sourceKey);
                if (sourceName == null) sourceName = killCountSourceNames.get(sourceKey);

                result.add(new MergedSource(sourceKey,
                        sourceName != null ? sourceName : sourceKey,
                        sourceType,
                        items,
                        killCount,
                        killCountWinner));
            }
            return result;
        }
    }

    private static class MutableItem
    {
        final String itemKey;
        int    itemId;
        String itemName;
        String sourceType;
        long   quantity;
        String winnerSource;
        final Map<String, String> sourceNames = new LinkedHashMap<>();

        MutableItem(String itemKey, int itemId, String itemName, String sourceType)
        {
            this.itemKey    = itemKey;
            this.itemId     = itemId;
            this.itemName   = itemName;
            this.sourceType = sourceType;
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  PUBLIC DATA CLASSES (used by LootTrackerApiClient, panel, plugin)
    // ═════════════════════════════════════════════════════════════════════════

    public static class MergedSource
    {
        public final String           sourceKey;
        public final String           sourceName;
        public final String           sourceType;
        public final List<MergedItem> items;
        /** Max-merged kill count for this source: max(website, runelite_default). */
        public final int              killCount;
        /** Which source ("website" / "runelite_default_loot_tracker") provided the winning kill count. */
        public final String           killCountWinner;

        public MergedSource(String sourceKey, String sourceName,
                String sourceType, List<MergedItem> items,
                int killCount, String killCountWinner)
        {
            this.sourceKey       = sourceKey;
            this.sourceName      = sourceName;
            this.sourceType      = sourceType;
            this.items           = items;
            this.killCount       = killCount;
            this.killCountWinner = killCountWinner;
        }
    }

    public static class MergedItem
    {
        public final int    itemId;
        public final String itemName;
        public final long   quantity;
        public final String mergeReason;

        public MergedItem(int itemId, String itemName, long quantity, String mergeReason)
        {
            this.itemId      = itemId;
            this.itemName    = itemName;
            this.quantity    = quantity;
            this.mergeReason = mergeReason;
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  MERGE RESULT
    // ═════════════════════════════════════════════════════════════════════════

    public static class MergeResult
    {
        /** True if the merge completed (possibly with upload failure). */
        @Getter public final boolean success;
        /** If {@code !success}, the human-readable reason sync was blocked. */
        @Getter public final String  blockedReason;

        @Getter public final String  accountKey;
        @Getter public final int     sourcesCount;
        @Getter public final int     itemsCount;
        @Getter public final boolean uploadedToWebsite;
        /** True if RuneLite tracker history was skipped due to account safety. */
        @Getter public final boolean runeliteHistorySkipped;
        @Getter public final String  uploadError;

        private MergeResult(boolean success, String blockedReason, String accountKey,
                int sourcesCount, int itemsCount, boolean uploadedToWebsite,
                boolean runeliteHistorySkipped, String uploadError)
        {
            this.success                = success;
            this.blockedReason          = blockedReason;
            this.accountKey             = accountKey;
            this.sourcesCount           = sourcesCount;
            this.itemsCount             = itemsCount;
            this.uploadedToWebsite      = uploadedToWebsite;
            this.runeliteHistorySkipped = runeliteHistorySkipped;
            this.uploadError            = uploadError;
        }

        static MergeResult blocked(String reason)
        {
            return new MergeResult(false, reason, null, 0, 0, false, false, null);
        }

        static MergeResult success(String accountKey, int sources, int items,
                boolean uploaded, boolean rlSkipped, String uploadError)
        {
            return new MergeResult(true, null, accountKey, sources, items,
                    uploaded, rlSkipped, uploadError);
        }

        /** Returns a one-line summary suitable for UI display. */
        public String toSummaryLine()
        {
            if (!success) return "Loot sync blocked: " + blockedReason;

            String base = String.format("Loot synced for %s: %d source(s), %d item(s)%s",
                    accountKey, sourcesCount, itemsCount,
                    uploadedToWebsite ? " — uploaded to website" : " (website upload failed)");

            if (runeliteHistorySkipped)
            {
                base += ". RuneLite Loot Tracker history was not imported (cannot verify account ownership).";
            }

            return base;
        }
    }
}

package com.runealytics;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import static com.runealytics.RuneAlyticsHttp.JSON;

/**
 * HTTP client for the loot-related RuneAlytics endpoints: batch upload
 * ({@link #bulkSyncKills}) and history download
 * ({@link #fetchKillHistoryFromServer}). Payload construction is delegated to
 * {@link LootKillJsonBuilder}.
 */
@Slf4j
@Singleton
public class LootTrackerApiClient
{
    private static final String LOOT_BULK_SYNC_PATH    = "/loot/bulk-sync";
    private static final String LOOT_HISTORY_PATH      = "/loot/history/";
    private static final String LOOT_SNAPSHOT_PATH     = "/runelite/loot/snapshot";
    private static final String LOOT_SYNC_ABSOLUTE_PATH = "/runelite/loot/sync-absolute";
    private static final String PLAYER_DEATH_EVENT_PATH = "/runelite/player/death-event";

    private final OkHttpClient       httpClient;
    private final RunealyticsConfig  config;
    private final RuneAlyticsState   state;
    private final Gson               gson;
    private final ItemManager        itemManager;
    private final ClientThread       clientThread;

    @Inject
    public LootTrackerApiClient(
            OkHttpClient httpClient,
            RunealyticsConfig config,
            RuneAlyticsState state,
            Gson gson,
            ItemManager itemManager,
            ClientThread clientThread)
    {
        this.itemManager  = itemManager;
        this.clientThread = clientThread;
        // Apply the configured timeout so loot uploads/downloads don't hang on
        // RuneLite's shared-client defaults.
        this.httpClient = httpClient.newBuilder()
                .connectTimeout(config.syncTimeout(), TimeUnit.SECONDS)
                .readTimeout(config.syncTimeout(),    TimeUnit.SECONDS)
                .writeTimeout(config.syncTimeout(),   TimeUnit.SECONDS)
                .build();
        this.config     = config;
        this.state      = state;
        this.gson       = gson;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  UPLOAD – BULK
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Uploads a batch of unsynced kills to {@code /loot/bulk-sync}.
     *
     * <p>NPC id and prestige come from the per-boss {@link LootStorageData.BossKillData},
     * since kills don't store these themselves.</p>
     *
     * @param username    verified RSN
     * @param killsByBoss map of {npcName → kills to sync}
     * @param bossLookup  full per-boss data, used to resolve npcId / prestige
     * @return true on HTTP 2xx
     */
    public boolean bulkSyncKills(
            String username,
            Map<String, List<LootStorageData.KillRecord>> killsByBoss,
            Map<String, LootStorageData.BossKillData> bossLookup) throws IOException
    {
        if (killsByBoss == null || killsByBoss.isEmpty()) return true;

        List<JsonObject> killPayloads = new ArrayList<>();
        int skippedZeroLoot = 0;

        for (Map.Entry<String, List<LootStorageData.KillRecord>> e : killsByBoss.entrySet())
        {
            String npcName = e.getKey();
            LootStorageData.BossKillData boss = bossLookup != null ? bossLookup.get(npcName) : null;

            int npcId    = boss != null ? boss.getNpcId()    : 0;
            int prestige = boss != null ? boss.getPrestige() : 0;

            for (LootStorageData.KillRecord kill : e.getValue())
            {
                // The server requires a non-empty drops array (HTTP 422 otherwise).
                // Zero-loot kills are tracked locally for kill-count accuracy but
                // are not sent to the server — they carry no drop data to store.
                List<LootStorageData.DropRecord> drops = kill.getDrops();
                if (drops == null || drops.isEmpty())
                {
                    skippedZeroLoot++;
                    // Mark synced so they are not retried on the next batch pass.
                    kill.setSyncedToServer(true);
                    continue;
                }

                JsonObject killPayload = LootKillJsonBuilder.buildKill(kill, npcName, npcId, prestige);

                if (log.isDebugEnabled())
                {
                    log.debug("[bulk-sync] kill '{}' #{} location payload: {}",
                            npcName, kill.getKillNumber(),
                            killPayload.has("location") ? killPayload.get("location") : "<none>");
                }

                killPayloads.add(killPayload);
            }
        }

        if (skippedZeroLoot > 0)
            log.debug("[bulk-sync] skipped {} zero-loot kill(s) — counted locally only", skippedZeroLoot);

        if (killPayloads.isEmpty()) return true;

        JsonObject envelope = LootKillJsonBuilder.buildBulkEnvelope(
                username,
                state.getCurrentGameMode(),
                state.getCurrentAccountSubtype(),
                killPayloads);
        return postJson(LOOT_BULK_SYNC_PATH, envelope, "bulk-sync " + killPayloads.size() + " kills");
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SNAPSHOT  –  GET /runelite/loot/snapshot
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Fetches the website's saved absolute loot totals for {@code username}.
     *
     * <p>Used by {@link LootSyncMergeService} to obtain the "website" leg of
     * the three-source merge before computing the max-absolute totals.</p>
     *
     * @return a parsed snapshot, or {@code null} on any error/auth failure
     */
    public LootSnapshot fetchLootSnapshot(String username) throws IOException
    {
        String url = config.apiUrl() + LOOT_SNAPSHOT_PATH
                + "?username=" + encodePathSegment(username)
                + "&game=osrs";

        Request.Builder rb = new Request.Builder()
                .url(url)
                .get()
                .addHeader("Accept", "application/json");

        String token = state.getVerificationCode();
        if (token != null && !token.isEmpty())
        {
            rb.addHeader("Authorization", "Bearer " + token);
        }

        try (Response response = httpClient.newCall(rb.build()).execute())
        {
            if (response.code() == 401 || response.code() == 403)
            {
                log.debug("[snapshot] auth error: HTTP {}", response.code());
                return null;
            }
            if (!response.isSuccessful() || response.body() == null)
            {
                log.debug("[snapshot] failed: HTTP {}", response.code());
                return null;
            }

            String json = response.body().string();
            return parseSnapshot(gson.fromJson(json, JsonObject.class));
        }
        catch (IOException e)
        {
            log.debug("[snapshot] network failure: {}", e.getMessage());
            throw e;
        }
    }

    /**
     * Parses a {@code /runelite/loot/snapshot} response into a {@link LootSnapshot}.
     */
    private LootSnapshot parseSnapshot(JsonObject obj)
    {
        if (obj == null || !obj.has("success") || !obj.get("success").getAsBoolean())
        {
            return null;
        }

        LootSnapshot snapshot = new LootSnapshot();
        snapshot.username = getString(obj, "username", "");

        if (!obj.has("sources") || !obj.get("sources").isJsonArray())
        {
            return snapshot;
        }

        for (JsonElement sourceEl : obj.getAsJsonArray("sources"))
        {
            if (!sourceEl.isJsonObject()) continue;
            JsonObject src = sourceEl.getAsJsonObject();

            String sourceKey  = getString(src, "source_key",  "");
            String sourceName = getString(src, "source_name", sourceKey);

            if (!src.has("items") || !src.get("items").isJsonArray()) continue;

            Map<String, Long> itemTotals = new HashMap<>();

            for (JsonElement itemEl : src.getAsJsonArray("items"))
            {
                if (!itemEl.isJsonObject()) continue;
                JsonObject item = itemEl.getAsJsonObject();

                int    itemId  = getInt(item, "item_id", 0);
                String name    = getString(item, "item_name", "");
                long   qty     = getLong(item, "quantity", 0L);

                // Use "id_{itemId}" as key when the ID is present, otherwise
                // "name_{normalized}" — mirrors the server's item_key logic.
                String key = itemId > 0
                        ? "id_" + itemId
                        : "name_" + name.toLowerCase().trim();

                itemTotals.merge(key, qty, Math::max);
                if (itemId > 0)
                {
                    snapshot.itemIdsByKey.put(key, itemId);
                    snapshot.itemNamesByKey.put(key, name);
                }
            }

            snapshot.sources.put(sourceKey, new LootSnapshot.SourceData(sourceKey, sourceName, itemTotals));
        }

        return snapshot;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SYNC-ABSOLUTE  –  POST /runelite/loot/sync-absolute
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Submits merged absolute loot totals to the website.
     *
     * <p>This endpoint is idempotent: the server only updates stored quantities
     * when the submitted value is ≥ the stored value (max-wins merge).  Repeated
     * calls with the same data produce no changes.</p>
     *
     * @param  username  normalized RuneScape account name
     * @param  sources   merged source/item totals from {@link LootSyncMergeService}
     * @return true on HTTP 2xx
     */
    public boolean syncAbsolute(String username,
            List<LootSyncMergeService.MergedSource> sources) throws IOException
    {
        if (sources == null || sources.isEmpty()) return true;

        JsonObject envelope = new JsonObject();
        envelope.addProperty("username",  username);
        envelope.addProperty("game",      "osrs");
        envelope.addProperty("sync_mode", "absolute_merge");
        envelope.addProperty("force_resync", false);
        envelope.addProperty("client_timestamp",
                DateTimeFormatter.ISO_INSTANT.format(Instant.now()));

        JsonArray sourcesArr = new JsonArray();
        for (LootSyncMergeService.MergedSource src : sources)
        {
            JsonObject srcObj = new JsonObject();
            srcObj.addProperty("source_key",  src.sourceKey);
            srcObj.addProperty("source_name", src.sourceName);
            if (src.sourceType != null) srcObj.addProperty("source_type", src.sourceType);
            if (src.killCount > 0) srcObj.addProperty("kill_count", src.killCount);

            JsonArray itemsArr = new JsonArray();
            for (LootSyncMergeService.MergedItem item : src.items)
            {
                JsonObject itemObj = new JsonObject();
                if (item.itemId > 0) itemObj.addProperty("item_id", item.itemId);
                itemObj.addProperty("item_name",    item.itemName);
                itemObj.addProperty("quantity",     item.quantity);
                itemObj.addProperty("merge_reason", item.mergeReason);
                itemsArr.add(itemObj);
            }
            srcObj.add("items", itemsArr);
            sourcesArr.add(srcObj);
        }
        envelope.add("sources", sourcesArr);

        return postJson(LOOT_SYNC_ABSOLUTE_PATH, envelope,
                "sync-absolute " + sources.size() + " sources");
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  DEATH EVENT  –  POST /runelite/player/death-event
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Notifies the website of a player death or item-recovery event.
     *
     * <p>Recovered items sent in this call are stored as metadata only and
     * are never counted toward loot totals.</p>
     *
     * @return true on HTTP 2xx
     */
    public boolean sendDeathEvent(String username,
            String eventType,
            int world,
            int regionId,
            PlayerLocationSnapshot location,
            List<LootStorageData.DropRecord> recoveredItems) throws IOException
    {
        JsonObject envelope = new JsonObject();
        envelope.addProperty("username",          username);
        envelope.addProperty("game",              "osrs");
        envelope.addProperty("event_type",        eventType);
        envelope.addProperty("client_timestamp",
                DateTimeFormatter.ISO_INSTANT.format(Instant.now()));
        envelope.addProperty("world",             world);
        envelope.addProperty("region_id",         regionId);

        if (location != null)
        {
            JsonObject loc = new JsonObject();
            loc.addProperty("x",     location.getWorldX());
            loc.addProperty("y",     location.getWorldY());
            loc.addProperty("plane", location.getPlane());
            envelope.add("location", loc);
        }

        if (recoveredItems != null && !recoveredItems.isEmpty())
        {
            JsonArray reclaimed = new JsonArray();
            for (LootStorageData.DropRecord dr : recoveredItems)
            {
                JsonObject r = new JsonObject();
                r.addProperty("item_id",   dr.getItemId());
                r.addProperty("item_name", dr.getItemName());
                r.addProperty("quantity",  dr.getQuantity());
                reclaimed.add(r);
            }
            JsonObject ctx = new JsonObject();
            ctx.add("items_recovered", reclaimed);
            envelope.add("death_context", ctx);
        }

        return postJson(PLAYER_DEATH_EVENT_PATH, envelope, "death-event " + eventType);
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  SNAPSHOT DATA CLASSES
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Parsed representation of a {@code /runelite/loot/snapshot} response.
     */
    public static class LootSnapshot
    {
        public String username = "";
        /** Map from normalized sourceKey to {@link SourceData}. */
        public final Map<String, SourceData>  sources        = new HashMap<>();
        public final Map<String, Integer>     itemIdsByKey   = new HashMap<>();
        public final Map<String, String>      itemNamesByKey = new HashMap<>();

        public static class SourceData
        {
            public final String              sourceKey;
            public final String              sourceName;
            /** Map from item_key ("id_536" / "name_dragon bones") to absolute quantity. */
            public final Map<String, Long>   itemTotals;

            SourceData(String sourceKey, String sourceName, Map<String, Long> itemTotals)
            {
                this.sourceKey  = sourceKey;
                this.sourceName = sourceName;
                this.itemTotals = itemTotals;
            }
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  DOWNLOAD – HISTORY (existing, unchanged)
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Fetches the complete kill history for {@code username} from the server,
     * grouped by boss for use by {@link LootStorageManager#mergeServerData}.
     */
    public Map<String, LootStorageData.BossKillData> fetchKillHistoryFromServer(String username) throws IOException
    {
        return fetchKillHistoryFromServer(username, true);
    }

    /**
     * Fetches the complete kill history for {@code username} from the server,
     * grouped by boss for use by {@link LootStorageManager#mergeServerData}.
     *
     * @param manualSync when {@code true}, verbose response logs are shown;
     *                   when {@code false}, only essential debug info is logged
     */
    public Map<String, LootStorageData.BossKillData> fetchKillHistoryFromServer(String username, boolean manualSync) throws IOException
    {
        Request request = new Request.Builder()
                .url(config.apiUrl() + LOOT_HISTORY_PATH + encodePathSegment(username))
                .get()
                .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                log.debug("Failed to fetch kill history: HTTP {}", response.code());
                return new HashMap<>();
            }

            String json = response.body().string();
            if (manualSync)
                log.debug("History response: {}", json);

            JsonObject responseObj = gson.fromJson(json, JsonObject.class);
            if (responseObj == null || !responseObj.has("kills") || !responseObj.get("kills").isJsonArray())
            {
                log.debug("Invalid history response – missing 'kills' array");
                return new HashMap<>();
            }

            return parseHistory(responseObj.getAsJsonArray("kills"));
        }
        catch (Exception e)
        {
            log.debug("Error fetching kill history from server", e);
            return new HashMap<>();
        }
    }

    private Map<String, LootStorageData.BossKillData> parseHistory(JsonArray killsArray)
    {
        Map<String, LootStorageData.BossKillData> result = new HashMap<>();
        int skipped = 0;

        for (int i = 0; i < killsArray.size(); i++)
        {
            try
            {
                JsonElement el = killsArray.get(i);
                if (!el.isJsonObject())
                {
                    skipped++;
                    continue;
                }
                JsonObject killObj = el.getAsJsonObject();

                String bossName = getString(killObj, "boss_name", null);
                if (bossName == null || bossName.isEmpty())
                {
                    // No boss name = unusable row; skip rather than bucketing under null.
                    skipped++;
                    continue;
                }

                final int  bossId          = getInt(killObj, "boss_id", 0);
                int        combatLevel      = getInt(killObj, "combat_level", 0);
                int        world            = getInt(killObj, "world", 0);
                long       killTimeSeconds  = getLong(killObj, "kill_time", 0L);

                LootStorageData.BossKillData bossData = result.computeIfAbsent(bossName, k -> {
                    LootStorageData.BossKillData bd = new LootStorageData.BossKillData();
                    bd.setNpcName(bossName);
                    bd.setNpcId(bossId);
                    bd.setKillCount(0);
                    bd.setPrestige(0);
                    bd.setTotalLootValue(0);
                    bd.setKills(new ArrayList<>());
                    bd.setAggregatedDrops(new HashMap<>());
                    return bd;
                });

                LootStorageData.KillRecord killRecord = new LootStorageData.KillRecord();
                killRecord.setTimestamp(killTimeSeconds * 1000);
                killRecord.setWorld(world);
                killRecord.setCombatLevel(combatLevel);
                killRecord.setSyncedToServer(true);
                killRecord.setDrops(new ArrayList<>());

                if (killObj.has("drops") && killObj.get("drops").isJsonArray())
                {
                    JsonArray dropsArray = killObj.getAsJsonArray("drops");

                    for (int j = 0; j < dropsArray.size(); j++)
                    {
                        JsonElement dropEl = dropsArray.get(j);
                        if (!dropEl.isJsonObject()) continue;
                        JsonObject dropObj = dropEl.getAsJsonObject();

                        int itemId  = getInt(dropObj, "item_id", 0);
                        int gePrice = getInt(dropObj, "ge_price", 0);
                        int highAlch = getInt(dropObj, "high_alch", 0);

                        LootStorageData.DropRecord drop = new LootStorageData.DropRecord();
                        drop.setItemId(itemId);
                        drop.setItemName(getString(dropObj, "item_name", ""));
                        drop.setQuantity(getInt(dropObj, "quantity", 0));
                        drop.setGePrice(gePrice);
                        drop.setHighAlch(highAlch);
                        drop.setTotalValue((long) gePrice * drop.getQuantity());
                        drop.setHidden(false);

                        killRecord.getDrops().add(drop);
                    }
                }

                bossData.getKills().add(killRecord);
                bossData.setKillCount(bossData.getKillCount() + 1);
            }
            catch (RuntimeException ex)
            {
                // One malformed row must not discard the whole download.
                skipped++;
            }
        }

        if (skipped > 0)
            log.debug("Skipped {} malformed kill record(s) in history response", skipped);

        // Re-resolve GE price / high alch for drops stored as 0 (noted, charged,
        // or untradeable items). ItemManager reads the client's item cache and
        // must run on the client thread; this method runs on a background sync
        // thread, so the whole history is resolved in a single client-thread hop.
        clientThread.invoke(() ->
        {
            for (LootStorageData.BossKillData bossData : result.values())
            {
                for (LootStorageData.KillRecord killRecord : bossData.getKills())
                {
                    for (LootStorageData.DropRecord drop : killRecord.getDrops())
                    {
                        int itemId = drop.getItemId();
                        if (itemId <= 0) continue;

                        if (drop.getGePrice() <= 0)
                        {
                            int gePrice = ItemValueResolver.perItemGeValue(itemManager, itemId);
                            if (gePrice > 0)
                            {
                                drop.setGePrice(gePrice);
                                drop.setTotalValue((long) gePrice * drop.getQuantity());
                            }
                        }
                        if (drop.getHighAlch() <= 0)
                        {
                            ItemComposition comp = itemManager.getItemComposition(itemId);
                            if (comp != null) drop.setHighAlch(comp.getHaPrice());
                        }
                    }
                }
            }
        });

        log.debug("Fetched {} bosses with total {} kills from server",
                result.size(),
                result.values().stream().mapToInt(b -> b.getKills().size()).sum());

        return result;
    }

    // ── JSON field helpers (null/type-safe) ───────────────────────────────────

    private static String getString(JsonObject obj, String key, String def)
    {
        JsonElement el = obj.get(key);
        return (el != null && el.isJsonPrimitive()) ? el.getAsString() : def;
    }

    private static int getInt(JsonObject obj, String key, int def)
    {
        JsonElement el = obj.get(key);
        try
        {
            return (el != null && el.isJsonPrimitive()) ? el.getAsInt() : def;
        }
        catch (NumberFormatException e)
        {
            return def;
        }
    }

    private static long getLong(JsonObject obj, String key, long def)
    {
        JsonElement el = obj.get(key);
        try
        {
            return (el != null && el.isJsonPrimitive()) ? el.getAsLong() : def;
        }
        catch (NumberFormatException e)
        {
            return def;
        }
    }

    private static String encodePathSegment(String value)
    {
        if (value == null) return "";
        try
        {
            // URLEncoder targets query strings (space → '+'); convert to %20 for paths.
            return URLEncoder.encode(value, "UTF-8").replace("+", "%20");
        }
        catch (UnsupportedEncodingException e)
        {
            return value;
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  INTERNAL
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Shared POST helper. Adds the auth header if available and logs the result.
     *
     * @return true on HTTP 2xx
     */
    private boolean postJson(String path, JsonObject payload, String contextForLog)
    {
        String url = config.apiUrl() + path;
        RequestBody body = RequestBody.create(JSON, gson.toJson(payload));

        Request.Builder rb = new Request.Builder()
                .url(url)
                .post(body)
                .addHeader("Content-Type", "application/json")
                .addHeader("Accept",       "application/json");

        String token = state.getVerificationCode();
        if (token != null && !token.isEmpty())
        {
            rb.addHeader("Authorization", "Bearer " + token);
        }

        try (Response response = httpClient.newCall(rb.build()).execute())
        {
            if (!response.isSuccessful())
            {
                String responseBody = response.body() != null ? response.body().string() : "";
                log.debug("[{}] failed: HTTP {} — {}", contextForLog, response.code(), responseBody);
                return false;
            }
            log.debug("[{}] ok", contextForLog);
            return true;
        }
        catch (IOException e)
        {
            log.debug("[{}] network failure: {}", contextForLog, e.getMessage());
            return false;
        }
    }
}

