    // ═════════════════════════════════════════════════════════════════════════
    //  LOOT PATH 1 – NPC GROUND DROPS  (NpcLootReceived)
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Processes loot from a standard NPC ground-drop kill.
     *
     * <p>Called from RuneAlyticsPlugin.onNpcLootReceived(). No deduplication is
     * applied because RuneLite guarantees this event fires exactly once per kill.</p>
     *
     * @param npc   the NPC that was killed
     * @param items the dropped items in our internal {@link ItemStack} format
     */
    public void processNpcLoot(NPC npc, List<ItemStack> items)
    {
        if (!config.enableLootTracking() || npc == null || npc.getName() == null)
            return;

        log.debug("NPC loot: '{}' id={} cb={} items={}",
                npc.getName(), npc.getId(), npc.getCombatLevel(), items.size());

        String name = normalizeBossName(npc.getName());
        boolean isBoss = isBoss(npc.getId(), name);

        if (!isBoss && !config.trackAllNpcs())
        {
            log.debug("Filtered NPC (not a tracked boss): '{}' id={} "
                            + "→ enable 'Track All NPCs' or add id to TRACKED_BOSS_IDS",
                    name, npc.getId());
            return;
        }

        // Record the kill even if every drop was filtered out by
        // minimumLootValue, so the kill counter stays accurate. Zero-drop kills
        // stay local-only; the bulk-sync path skips them from server upload.
        List<LootStorageData.DropRecord> drops = convertToDropRecords(items);
        recordKill(name, npc.getId(), npc.getCombatLevel(), client.getWorld(), drops);
    }

    /**
     * Deferred version of processNpcLoot that accepts primitive NPC data instead
     * of an NPC reference. Safe to call from background executors where NPC refs
     * may be stale. Does the same loot processing as processNpcLoot.
     */
    public void processNpcLootDeferred(String npcName, int npcId, int combatLevel,
                                       int world, List<ItemStack> items)
    {
        processNpcLootDeferred(npcName, npcId, combatLevel, world, items, null);
    }

    public void processNpcLootDeferred(String npcName, int npcId, int combatLevel,
                                       int world, List<ItemStack> items, PlayerLocationSnapshot location)
    {
        if (!config.enableLootTracking() || npcName == null || npcName.isEmpty())
            return;

        final List<ItemStack> itemList = items == null ? Collections.emptyList() : items;

        log.debug("NPC loot (deferred): '{}' id={} cb={} items={}",
                npcName, npcId, combatLevel, itemList.size());

        String name = normalizeBossName(npcName);
        boolean isBoss = isBoss(npcId, name);

        if (!isBoss && !config.trackAllNpcs())
        {
            log.debug("Filtered NPC (not a tracked boss): '{}' id={} "
                            + "→ enable 'Track All NPCs' or add id to TRACKED_BOSS_IDS",
                    name, npcId);
            return;
        }

        // ItemManager lookups must run on the client thread. ClientThread.invoke
        // is async when called off-thread, so convert AND persist must both live
        // inside the callback — reading an AtomicReference immediately after
        // invoke() races and records a null drop list.
        clientThread.invoke(() ->
        {
            List<LootStorageData.DropRecord> drops = convertToDropRecords(itemList);
            executorService.execute(() ->
                    recordKillWithLocation(name, npcId, combatLevel, world, drops, location));
        });
    }

    /**
     * Attaches a late-arriving {@code NpcLootReceived} to a kill that was
     * already counted as zero-loot, instead of recording a new kill.
     *
     * <p>Under load (e.g. an AOE kill that drops several NPCs at once),
     * {@code NpcLootReceived} can lag past the zero-loot grace window, so
     * {@code RuneAlyticsPlugin} flushes the zero-loot kill first. If the real
     * loot event then arrives, calling {@link #processNpcLoot} would record a
     * second kill for the same death — doubling the kill count. The caller
     * only invokes this when its own NPC-index-keyed bookkeeping confirms a
     * zero-loot kill was just flushed for this exact NPC.</p>
     *
     * @return {@code true} if the drops were attached to the existing kill;
     *         {@code false} if there was nothing eligible to upgrade, in
     *         which case the caller should fall back to {@link #processNpcLoot}
     */
    public boolean upgradeRecentZeroLootKill(NPC npc, List<ItemStack> items)
    {
        if (!config.enableLootTracking() || npc == null || npc.getName() == null) return false;
        if (items == null || items.isEmpty()) return false;

        String name = normalizeBossName(npc.getName());
        return upgradeRecentZeroLootKillDeferred(name, items);
    }

    public boolean upgradeRecentZeroLootKillDeferred(String normalizedName, List<ItemStack> items)
    {
        if (!config.enableLootTracking() || normalizedName == null) return false;
        if (items == null || items.isEmpty()) return false;

        // Callers (including the plugin event path) may pass a raw NPC name.
        String name = normalizeBossName(normalizedName);
        BossKillStats stats = bossKillStats.get(name);
        if (stats == null || stats.getKillHistory().isEmpty()) return false;

        LootStorageData.KillRecord lastKill =
                stats.getKillHistory().get(stats.getKillHistory().size() - 1);
        if (!lastKill.getDrops().isEmpty()) return false; // last kill wasn't zero-loot

        appendDropsToLastKill(name, items);
        log.debug("Upgraded zero-loot kill for '{}' with {} late drop(s) from a delayed NpcLootReceived",
                name, items.size());
        return true;
    }

