    /**
     * Permanently delete an item from a boss's loot history.
     * Removes the item from all kill records for that boss and recalculates totals.
     * Updates both storage and in-memory cache.
     * Tracks deletion so deleted items don't reappear during sync.
     */
    public void deleteDropForNpc(String npcName, int itemId)
    {
        LootStorageData data = storageManager.getCurrentData();
        if (data == null) return;

        LootStorageData.BossKillData bossData = data.getBossKills().get(npcName);
        if (bossData == null) return;

        long totalValueRemoved = 0;

        // Remove from all kill records in storage
        for (LootStorageData.KillRecord kill : bossData.getKills())
        {
            for (Iterator<LootStorageData.DropRecord> it = kill.getDrops().iterator(); it.hasNext(); )
            {
                LootStorageData.DropRecord drop = it.next();
                if (drop.getItemId() == itemId)
                {
                    totalValueRemoved += drop.getTotalValue();
                    it.remove();
                }
            }
        }

        // Merge-only sources (website / RuneLite tracker) have aggregated
        // totals but no per-kill records — fall back to the aggregate value
        // so the displayed total actually drops.
        LootStorageData.AggregatedDrop removedAgg = bossData.getAggregatedDrops().get(itemId);
        if (totalValueRemoved == 0 && removedAgg != null)
        {
            totalValueRemoved = removedAgg.getTotalValue();
        }

        // Also update the in-memory BossKillStats cache so panel sees the change
        BossKillStats stats = bossKillStats.get(npcName);
        if (stats != null)
        {
            List<LootStorageData.KillRecord> killHistory = stats.getKillHistory();
            if (killHistory != null)
            {
                for (LootStorageData.KillRecord kill : killHistory)
                {
                    for (Iterator<LootStorageData.DropRecord> it = kill.getDrops().iterator(); it.hasNext(); )
                    {
                        LootStorageData.DropRecord drop = it.next();
                        if (drop.getItemId() == itemId)
                            it.remove();
                    }
                }
            }
            // Also remove from preloaded drops (for kills synced from server with no per-kill records)
            List<BossKillStats.AggregatedDrop> preloaded = stats.getPreloadedDrops();
            if (preloaded != null)
            {
                preloaded.removeIf(drop -> drop.getItemId() == itemId);
            }
            stats.setTotalLootValue(Math.max(0, stats.getTotalLootValue() - totalValueRemoved));
        }

        // Remove from aggregated drops and recalculate totals
        bossData.getAggregatedDrops().remove(itemId);
        bossData.setTotalLootValue(Math.max(0, bossData.getTotalLootValue() - totalValueRemoved));

        // Clear the hide flag in both the in-memory map (what the panel
        // reads) and persisted storage so a deleted item is not still
        // treated as hidden after the next rehydrate.
        Set<Integer> memHidden = hiddenDrops.get(npcName);
        if (memHidden != null)
        {
            memHidden.remove(itemId);
            if (memHidden.isEmpty()) hiddenDrops.remove(npcName);
        }
        Set<Integer> hidden = data.getHiddenDropsByBoss().get(npcName);
        if (hidden != null)
        {
            hidden.remove(itemId);
            if (hidden.isEmpty()) data.getHiddenDropsByBoss().remove(npcName);
        }

        // Track the deletion so it survives sync - prevents deleted items from
        // reappearing when server data is merged back in
        Set<Integer> deleted = data.getDeletedDropsByBoss().computeIfAbsent(npcName, k -> new HashSet<>());
        deleted.add(itemId);

        storageManager.scheduleSave();
        log.debug("Deleted item {} from boss {}, removed {} gp", itemId, npcName, totalValueRemoved);
    }

    /**
     * Pushes the in-memory hidden-drops map down to {@link LootStorageData} so
     * it survives a restart. Independent of RuneLite's own ignore feature.
     */
    private void persistHiddenDrops()
    {
        LootStorageData data = storageManager.getCurrentData();
        if (data == null) data = storageManager.loadData();
        if (data == null) return;
        // Defensive copy so future mutations don't accidentally surface to disk.
        Map<String, Set<Integer>> snapshot = new HashMap<>();
        for (Map.Entry<String, Set<Integer>> e : hiddenDrops.entrySet())
            snapshot.put(e.getKey(), new HashSet<>(e.getValue()));
        data.setHiddenDropsByBoss(snapshot);
        storageManager.scheduleSave();
    }

    /**
     * Restores hidden-drops from persisted storage. Called by
     * {@link #loadFromStorage}.
     */
    private void rehydrateHiddenDrops()
    {
        LootStorageData data = storageManager.getCurrentData();
        if (data == null) return;
        Map<String, Set<Integer>> saved = data.getHiddenDropsByBoss();
        if (saved == null) return;
        hiddenDrops.clear();
        for (Map.Entry<String, Set<Integer>> e : saved.entrySet())
        {
            Set<Integer> concurrentSet = ConcurrentHashMap.newKeySet();
            concurrentSet.addAll(e.getValue());
            hiddenDrops.put(e.getKey(), concurrentSet);
        }
    }

