    // ═════════════════════════════════════════════════════════════════════════
    //  UTILITY – CHAT MESSAGE PARSING
    // ═════════════════════════════════════════════════════════════════════════

    /**
     * Feeds a game chat message into the {@link KillCountResolver}.
     *
     * <p>Handles both orderings of the KC-message / loot-event race:</p>
     * <ul>
     *   <li><b>Message first:</b> the observation waits as pending state and
     *       is consumed by the next {@code recordKill} for the same boss.</li>
     *   <li><b>Loot first:</b> the kill was already recorded with the local
     *       counter — {@link #applyLateGameKc} relabels that kill in place
     *       (never adds a second kill) when it is recent and still unsynced.</li>
     * </ul>
     */
    public void parseKillCountMessage(String message)
    {
        try
        {
            KillCountResolver.KcObservation obs =
                    killCountResolver.observe(message, System.currentTimeMillis());
            if (obs == null) return;

            log.debug("KC from chat: '{}' = {}", obs.getBossName(), obs.getKillCount());
            applyLateGameKc(obs.getBossName(), obs.getKillCount());
        }
        catch (Exception e)
        {
            // Chat parsing must never take down the message pipeline.
            log.debug("parseKillCountMessage failed: {}", e.getMessage());
        }
    }

    /**
     * Relabels the just-recorded kill for {@code npcName} with the
     * authoritative game KC when the chat message arrived <em>after</em> the
     * loot event. Strictly a rename of the existing record — the kill count
     * of kills is never changed here, so chat + death + widget signals can
     * never produce two increments for one kill.
     *
     * <p>Skipped when the last kill is older than
     * {@value #LATE_KC_APPLY_WINDOW_MS} ms (the observation then stays pending
     * for the next kill) or when it already synced to the server (relabeling
     * a synced record would re-upload it as a new kill).</p>
     */
    private void applyLateGameKc(String npcName, int gameKC)
    {
        BossKillStats stats = bossKillStats.get(npcName);
        if (stats == null || stats.getKillHistory().isEmpty()) return;

        LootStorageData.KillRecord lastKill =
                stats.getKillHistory().get(stats.getKillHistory().size() - 1);

        long ageMs = System.currentTimeMillis() - lastKill.getTimestamp();
        if (ageMs > LATE_KC_APPLY_WINDOW_MS) return;

        // A kill this recent is the one this KC belongs to — claim the
        // observation NOW, before any early return below, so it can never
        // leak onto the next kill of the same boss.
        killCountResolver.consume(npcName, System.currentTimeMillis());

        if (lastKill.getKillNumber() >= gameKC) return; // already correct or ahead
        if (lastKill.isSyncedToServer()) return;        // too late — avoid dup upload

        if (!storageManager.relabelLastKill(npcName, gameKC))
        {
            return; // storage-side record already synced/ahead — keep in sync
        }

        lastKill.setKillNumber(gameKC);
        if (gameKC > stats.getKillCount())
        {
            stats.setKillCount(gameKC);
        }

        notifyListeners(stats, lastKill);
        log.debug("Late game KC {} applied to last '{}' kill ({}ms after record)",
                gameKC, npcName, ageMs);
    }

    public String detectChestSource(String lower)
    {
        if (lower.contains("wintertodt") || lower.contains("cold of the wintertodt"))
            return "Wintertodt";

        if (lower.contains("subdued the spirit") || lower.contains("you have helped to subdue"))
            return "Tempoross";

        if (lower.contains("zalcano") && (lower.contains("loot") || lower.contains("defeated")))
            return "Zalcano";

        if (lower.contains("congratulations - your raid is complete")
                || lower.contains("congratulations! your raid is complete"))
            return "Chambers of Xeric";

        if (lower.contains("theatre of blood") && lower.contains("complete"))
            return "Theatre of Blood";

        if (lower.contains("tombs of amascut") && lower.contains("complete"))
            return "Tombs of Amascut";

        if (lower.contains("gauntlet") && lower.contains("complete"))
            return lower.contains("corrupted") ? "Corrupted Gauntlet" : "The Gauntlet";

        if (lower.contains("mokhaiotl"))
            return "Doom of Mokhaiotl";

        if (lower.contains("phosani") && lower.contains("defeated"))
            return "Phosani's Nightmare";
        if (lower.contains("nightmare") && lower.contains("defeated"))
            return "The Nightmare";

        if (lower.contains("royal titans") || lower.contains("eldric the ice king")
                || lower.contains("branda the fire queen"))
            return "Royal Titans";

        if (lower.contains("colosseum") || lower.contains("fortis"))
            return "Fortis Colosseum";

        if (lower.contains("treasure trail"))
        {
            if (lower.contains("beginner")) return "Beginner Clue";
            if (lower.contains("easy"))     return "Easy Clue";
            if (lower.contains("medium"))   return "Medium Clue";
            if (lower.contains("hard"))     return "Hard Clue";
            if (lower.contains("elite"))    return "Elite Clue";
            if (lower.contains("master"))   return "Master Clue";
            return "Clue Scroll";
        }

        return null;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  UTILITY – DROP RECORD CONVERSION
    // ═════════════════════════════════════════════════════════════════════════

    private List<LootStorageData.DropRecord> convertToDropRecords(List<ItemStack> items)
    {
        List<LootStorageData.DropRecord> drops = new ArrayList<>();
        boolean isClientThread = client.isClientThread();
        log.debug("convertToDropRecords: processing {} items (thread={}, isClientThread={})",
                items.size(), Thread.currentThread().getName(), isClientThread);

        for (ItemStack item : items)
        {
            int itemId = item.getId();

            // Cache canonicalize upfront to avoid redundant calls
            int canonicalId = itemManager.canonicalize(itemId);
            ItemComposition comp = itemManager.getItemComposition(itemId);
            ItemComposition canonicalComp = (canonicalId != itemId)
                    ? itemManager.getItemComposition(canonicalId)
                    : comp;

            // Resolve GE price (ItemValueResolver caches canonicalize internally)
            int  gePrice    = ItemValueResolver.perItemGeValue(itemManager, itemId);
            long totalValue = (long) gePrice * item.getQuantity();

            if (totalValue > 0 && totalValue < config.minimumLootValue())
            {
                log.debug("  Item filtered by minimum value: id={} name={} value={}", itemId, comp != null ? comp.getName() : "?", totalValue);
                continue;
            }

            LootStorageData.DropRecord drop = new LootStorageData.DropRecord();
            drop.setItemId   (itemId);
            drop.setItemName (comp != null ? comp.getName() : "Unknown Item");
            drop.setQuantity (item.getQuantity());
            drop.setGePrice  (gePrice);
            drop.setHighAlch (comp != null ? Math.max(comp.getHaPrice(), canonicalComp != null ? canonicalComp.getHaPrice() : 0) : 0);
            drop.setTotalValue(totalValue);
            drop.setHidden   (false);

            drops.add(drop);
            log.debug("  Drop recorded: id={} name={} qty={} gePrice={} totalValue={}", itemId, drop.getItemName(), item.getQuantity(), gePrice, totalValue);
        }

        log.debug("convertToDropRecords: returning {} drops from {} items", drops.size(), items.size());
        return drops;
    }

    /**
     * Converts a list of {@link ItemStack}s to drop records for skilling loot,
     * without applying the minimum-value filter. All items are recorded
     * regardless of GE value, ensuring farming crops and other low-value
     * skilling products are never filtered out by the minimumLootValue config.
     *
     * @param items list of items gained during skilling
     * @return list of drop records (never filters by value)
     */
    private List<LootStorageData.DropRecord> convertToDropRecordsSkilling(List<ItemStack> items)
    {
        List<LootStorageData.DropRecord> drops = new ArrayList<>();

        for (ItemStack item : items)
        {
            try
            {
                int itemId = item.getId();
                ItemComposition comp = itemManager.getItemComposition(itemId);
                int  gePrice    = ItemValueResolver.perItemGeValue(itemManager, itemId);
                long totalValue = (long) gePrice * item.getQuantity();

                // Only lookup canonical composition if it differs from the original
                int canonicalId = itemManager.canonicalize(itemId);
                ItemComposition canonicalComp = (canonicalId != itemId)
                        ? itemManager.getItemComposition(canonicalId)
                        : comp;

                LootStorageData.DropRecord drop = new LootStorageData.DropRecord();
                drop.setItemId   (itemId);
                drop.setItemName (comp.getName());
                drop.setQuantity (item.getQuantity());
                drop.setGePrice  (gePrice);
                drop.setHighAlch (Math.max(comp.getHaPrice(), canonicalComp.getHaPrice()));
                drop.setTotalValue(totalValue);
                drop.setHidden   (false);

                drops.add(drop);
            }
            catch (Exception e)
            {
                log.debug("[Farming] Failed to convert item id={}: {}", item.getId(), e.getMessage(), e);
            }
        }

        return drops;
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  LISTENERS
    // ═════════════════════════════════════════════════════════════════════════

    public void addListener(LootTrackerUpdateListener listener)
    {
        listeners.add(listener);
    }

    /**
     * Schedules a debounced listener notification for the given NPC. Rapid updates
     * within {@value #LISTENER_UPDATE_DEBOUNCE_MS}ms are batched into a single
     * notification to prevent excessive UI updates and client thread blocking.
     *
     * <p>Notification runs on background thread. The panel (LootTrackerPanel) already
     * defers its heavy UI work to background (buildItemGrid) and uses SwingUtilities
     * for EDT marshalling, so we don't need to marshal back to client thread.</p>
     */
    private void scheduleListenerUpdate(String npcName, BossKillStats stats, LootStorageData.KillRecord kill)
    {
        pendingListenerUpdates.put(npcName, stats);
        pendingKillRecords.put(npcName, kill);

        // Schedule notification on background thread after debounce delay
        executorService.schedule(() ->
        {
            BossKillStats debouncedStats = pendingListenerUpdates.remove(npcName);
            LootStorageData.KillRecord debouncedKill = pendingKillRecords.remove(npcName);

            if (debouncedStats != null && debouncedKill != null)
            {
                notifyListeners(debouncedStats, debouncedKill);
            }
        }, LISTENER_UPDATE_DEBOUNCE_MS, java.util.concurrent.TimeUnit.MILLISECONDS);
    }

    private void notifyListeners(BossKillStats stats, LootStorageData.KillRecord kill)
    {
        for (LootTrackerUpdateListener l : listeners)
        {
            l.onLootUpdated(stats, kill);
        }
    }

    private void notifyDataRefresh()
    {
        for (LootTrackerUpdateListener l : listeners) l.onDataRefresh();
    }
}

