    /**
     * Reorder all boss cards to match the given order without rebuilding.
     * Used when sort mode or filter changes but the boss set remains the same.
     * Pre-condition: All bosses in newOrder must already be in bossListPanel.
     */
    public void reorderBossCards(List<String> newOrder)
    {
        if (newOrder.equals(currentBossOrder)) return; // No reordering needed

        SwingUtilities.invokeLater(() ->
        {
            try
            {
                // Build a new component list in the desired order
                List<Component> reorderedComps = new ArrayList<>();
                for (String npcName : newOrder)
                {
                    JPanel card = bossCardMap.get(npcName);
                    if (card != null) reorderedComps.add(card);
                    // Skip struts for now, they'll be re-added below
                }

                // Remove all but keep component maps intact
                bossListPanel.removeAll();

                // Re-add in new order with struts
                for (int i = 0; i < reorderedComps.size(); i++)
                {
                    if (i > 0) bossListPanel.add(Box.createVerticalStrut(5));
                    bossListPanel.add(reorderedComps.get(i));
                }

                currentBossOrder = newOrder;
                bossListPanel.revalidate();
                bossListPanel.repaint();
            }
            catch (Throwable ex)
            {
                log.debug("Boss card reordering failed, falling back to refresh", ex);
                refreshDisplay();
            }
        });
    }

    /**
     * Toggle visibility of a boss card without rebuilding the entire panel.
     * Used when a filter change only affects one or a few bosses.
     * Pre-condition: Card must exist in bossCardMap.
     */
    public void setBossCardVisibility(String npcName, boolean visible)
    {
        SwingUtilities.invokeLater(() ->
        {
            JPanel card = bossCardMap.get(npcName);
            if (card != null && card.isVisible() != visible)
            {
                card.setVisible(visible);
                bossListPanel.revalidate();
                bossListPanel.repaint();
            }
        });
    }

    /**
     * Remove a single boss card incrementally without full rebuild.
     * Used when a boss is cleared or removed from data.
     * Falls back to full refresh if card doesn't exist.
     *
     * @param npcName the boss to remove
     */
    public void removeBossCard(String npcName)
    {
        SwingUtilities.invokeLater(() ->
        {
            JPanel card = bossCardMap.get(npcName);
            if (card == null)
            {
                // Card doesn't exist, just refresh
                invalidateFingerprint();
                refreshDisplay();
                return;
            }

            try
            {
                // Remove strut before the card (if it exists)
                Component[] components = bossListPanel.getComponents();
                int cardIndex = -1;
                for (int i = 0; i < components.length; i++)
                {
                    if (components[i] == card)
                    {
                        cardIndex = i;
                        break;
                    }
                }

                if (cardIndex >= 0)
                {
                    // Remove strut before (if exists and is a strut)
                    if (cardIndex > 0 && components[cardIndex - 1] instanceof javax.swing.Box.Filler)
                        bossListPanel.remove(cardIndex - 1);
                    // Remove the card itself
                    bossListPanel.remove(card);
                }

                // Update indexes
                bossCardMap.remove(npcName);
                bossValueLabelMap.remove(npcName);
                bossNameLabelMap.remove(npcName);
                bossGridWrapperMap.remove(npcName);
                currentBossOrder.remove(npcName);

                // Remove item slots for this boss
                itemSlotMap.keySet().removeIf(k -> k.startsWith(npcName + "_"));

                // Clear debounce timer for this boss
                javax.swing.Timer debounce = lootDebounceMap.get(npcName);
                if (debounce != null) debounce.stop();
                lootDebounceMap.remove(npcName);

                invalidateFingerprint();
                bossListPanel.revalidate();
                bossListPanel.repaint();
            }
            catch (Throwable ex)
            {
                log.debug("Incremental boss removal failed, falling back to refresh", ex);
                invalidateFingerprint();
                refreshDisplay();
            }
        });
    }

    /**
     * Reconcile bulk data updates (e.g., after sync reconciliation).
     * Attempts incremental updates if the boss set hasn't changed;
     * falls back to full refresh if structure changed.
     *
     * Called by LootTrackerManager after:
     * - Sync reconciliation (3-way merge)
     * - Data import
     * - Any large data change
     *
     * @param updatedStats the new boss stats after reconciliation
     */
    public void reconcileBulkUpdate(List<BossKillStats> updatedStats)
    {
        long startMs = System.currentTimeMillis();
        // Defer to background to avoid blocking EDT with data processing
        executorService.execute(() ->
        {
            try
            {
                // Build new fingerprint with updated data
                String newFp = buildDisplayFingerprint(updatedStats, highlightedBoss);

                // If structure hasn't changed, do incremental updates
                if (newFp.equals(lastDisplayFingerprint))
                {
                    // Structure same: just update values and kill counts on EDT
                    long edtStartMs = System.currentTimeMillis();
                    SwingUtilities.invokeLater(() ->
                    {
                        long totalVal = 0;
                        int totalKills = 0;
                        for (BossKillStats stats : updatedStats)
                        {
                            String npcName = stats.getNpcName();
                            if (!passesFilter(npcName) || isEmptyBossEntry(stats)) continue;

                            totalVal += stats.getTotalLootValue();
                            totalKills += stats.getKillCount();

                            // Update labels directly on EDT (no nested invokeLater)
                            JLabel nameLabel = bossNameLabelMap.get(npcName);
                            if (nameLabel != null)
                                nameLabel.setText(buildNameLabel(npcName, stats.getKillCount()));

                            JLabel valueLabel = bossValueLabelMap.get(npcName);
                            if (valueLabel != null)
                                valueLabel.setText(stats.getTotalLootValue() > 0 ? formatGp(stats.getTotalLootValue()) : "");
                        }
                        totalKillsLabel.setText("Kills " + formatNumber(totalKills));
                        totalValueLabel.setText("Value " + formatGp(totalVal));

                        long edtMs = System.currentTimeMillis() - edtStartMs;
                        long totalMs = System.currentTimeMillis() - startMs;
                        log.debug(LogCategory.UI_UPDATE.format(
                            "Bulk reconciliation (incremental): %d bosses, total %dms, EDT %dms",
                            updatedStats.size(), totalMs, edtMs));
                    });
                    return;
                }

                // Structure changed: invalidate and trigger full refresh
                log.debug(LogCategory.UI_UPDATE.format(
                    "Bulk reconciliation (structure changed): falling back to full refresh"));
                lastDisplayFingerprint = null;
                SwingUtilities.invokeLater(this::refreshDisplay);
            }
            catch (Throwable ex)
            {
                log.debug("Bulk reconciliation failed, forcing full refresh", ex);
                SwingUtilities.invokeLater(this::refreshDisplay);
            }
        });
    }

    public void refreshDisplay()
    {
        if (SwingUtilities.isEventDispatchThread())
            refreshDebounce.restart();
        else
            SwingUtilities.invokeLater(refreshDebounce::restart);
    }

    private void executeRefresh()
    {
        if (!refreshing.compareAndSet(false, true)) return;

        long startMs = System.currentTimeMillis();
        executorService.execute(() ->
        {
            try
            {
                List<BossKillStats> allStats = lootManager.getAllBossStats();

                // Filter and sort once, then build fingerprint from sorted result
                List<BossKillStats> sorted = new ArrayList<>();
                for (BossKillStats s : allStats)
                    if (passesFilter(s.getNpcName())
                            && (showIgnoredItems || !lootManager.isBossHidden(s.getNpcName()))
                            && !isEmptyBossEntry(s))
                        sorted.add(s);

                sortStats(sorted);

                String fp = buildDisplayFingerprint(sorted, highlightedBoss);
                String oldFp = lastDisplayFingerprint;
                lastDisplayFingerprint = fp;

                // If fingerprint was invalidated (set to null by invalidateFingerprint()),
                // force a slow-path rebuild even if structure looks the same
                boolean fingerprintChanged = (oldFp == null) || !fp.equals(oldFp);

                final long totalVal   = sorted.stream().mapToLong(BossKillStats::getTotalLootValue).sum();
                final int  totalKills = sorted.stream().mapToInt(BossKillStats::getKillCount).sum();
                final boolean forceSlowPath = fingerprintChanged;

                SwingUtilities.invokeLater(() ->
                {
                    try
                    {
                        List<String> newOrder = new ArrayList<>(sorted.size());
                        for (BossKillStats s : sorted) newOrder.add(s.getNpcName());

                        // Fast path: same bosses, same order, same highlight → update
                        // the existing cards in place. No removeAll, so no flicker.
                        // Skip if fingerprint was invalidated (force slow path for structure changes)
                        boolean inPlace = !forceSlowPath && !sorted.isEmpty()
                                && newOrder.equals(displayedOrder)
                                && java.util.Objects.equals(highlightedBoss, displayedHighlight)
                                && bossCardMap.size() == newOrder.size();

                        if (inPlace)
                        {
                            long edtStartMs = System.currentTimeMillis();
                            currentBossOrder = newOrder;
                            displayedOrder = newOrder;
                            displayedHighlight = highlightedBoss;

                            // Fast path: structure unchanged, just sync totals.
                            // Per-boss debounce mechanism (80ms) handles individual boss updates.
                            // Don't loop all bosses to avoid repainting every card on every data refresh.
                            totalKillsLabel.setText("Kills " + formatNumber(totalKills));
                            totalValueLabel.setText("Value " + formatGp(totalVal));

                            long totalMs = System.currentTimeMillis() - startMs;
                            long edtMs = System.currentTimeMillis() - edtStartMs;
                            log.debug(LogCategory.UI_UPDATE.format(
                                "Fast path: structure stable, totals synced (total %dms, EDT %dms)",
                                totalMs, edtMs));
                            return;
                        }

                        // Mid path: same boss set but different order (e.g., sort by value changed)
                        // Reorder cards without removeAll
                        boolean sameBossSet = !sorted.isEmpty()
                                && bossCardMap.size() == newOrder.size()
                                && java.util.Objects.equals(highlightedBoss, displayedHighlight)
                                && bossCardMap.keySet().containsAll(newOrder);

                        if (sameBossSet)
                        {
                            long edtStartMs = System.currentTimeMillis();

                            // Mid path: boss set unchanged, but order changed (e.g., sort by value).
                            // Don't call updateLoot() on all bosses - per-boss mechanism handles those.
                            // Skip expensive removeAll/re-add when order matches current layout.

                            boolean orderMatches = true;
                            Component[] comps = bossListPanel.getComponents();
                            int compIdx = 0;
                            for (String npcName : newOrder)
                            {
                                // Skip vertical struts (every other component)
                                if (compIdx >= comps.length) { orderMatches = false; break; }
                                JPanel card = bossCardMap.get(npcName);
                                if (comps[compIdx] != card) { orderMatches = false; break; }
                                // Move to next card (skip strut)
                                compIdx += 2;
                            }

                            if (!orderMatches)
                            {
                                // Order changed: rebuild component list (expensive but necessary)
                                // This should be rare - only happens when sort order actually changes
                                List<Component> reorderedComps = new ArrayList<>();
                                for (String npcName : newOrder)
                                {
                                    JPanel card = bossCardMap.get(npcName);
                                    if (card != null) reorderedComps.add(card);
                                }

                                bossListPanel.removeAll();
                                for (int i = 0; i < reorderedComps.size(); i++)
                                {
                                    if (i > 0) bossListPanel.add(Box.createVerticalStrut(5));
                                    bossListPanel.add(reorderedComps.get(i));
                                }
                                // Repaint after structure change
                                bossListPanel.repaint();
                            }

                            currentBossOrder = newOrder;
                            displayedOrder = newOrder;
                            displayedHighlight = highlightedBoss;
                            totalKillsLabel.setText("Kills " + formatNumber(totalKills));
                            totalValueLabel.setText("Value " + formatGp(totalVal));

                            long totalMs = System.currentTimeMillis() - startMs;
                            long edtMs = System.currentTimeMillis() - edtStartMs;
                            log.debug(LogCategory.UI_UPDATE.format(
                                "Mid path: %s %d bosses (total %dms, EDT %dms)",
                                orderMatches ? "matched order for" : "reordered",
                                sorted.size(), totalMs, edtMs));
                            return;
                        }

                        // Slow path: boss set changed (added/removed) → rebuild the list.
                        int savedScroll = scrollPane.getVerticalScrollBar().getValue();
                        bossListPanel.removeAll();
                        itemSlotMap.clear();
                        bossCardMap.clear();
                        bossValueLabelMap.clear();
                        bossNameLabelMap.clear();
                        bossGridWrapperMap.clear();
                        bossBySourceGroup.clear();
                        currentBossOrder.clear();
                        lootDebounceMap.values().forEach(javax.swing.Timer::stop);
                        lootDebounceMap.clear();

                        if (sorted.isEmpty())
                        {
                            bossListPanel.add(buildEmptyState());
                        }
                        else
                        {
                            for (BossKillStats stats : sorted)
                            {
                                String npcName = stats.getNpcName();
                                bossListPanel.add(buildBossCard(stats));
                                bossListPanel.add(Box.createVerticalStrut(5));

                                // Populate source group index for incremental updates
                                currentBossOrder.add(npcName);
                                String sourceGroup = getSourceGroupKey(npcName);
                                bossBySourceGroup.computeIfAbsent(sourceGroup, k -> new ArrayList<>())
                                        .add(npcName);
                            }
                            totalKillsLabel.setText("Kills " + formatNumber(totalKills));
                            totalValueLabel.setText("Value " + formatGp(totalVal));
                        }

                        displayedOrder     = newOrder;
                        displayedHighlight = highlightedBoss;

                        long edtStartMs = System.currentTimeMillis();
                        // Don't call revalidate() - removeAll() already invalidated the panel.
                        // Let the repaint trigger layout validation instead of blocking EDT with explicit traversal.
                        bossListPanel.repaint();
                        scrollPane.getVerticalScrollBar().setValue(savedScroll);

                        long edtMs = System.currentTimeMillis() - edtStartMs;
                        long totalMs = System.currentTimeMillis() - startMs;
                        log.debug(LogCategory.UI_UPDATE.format(
                            "Slow path: rebuilt %d bosses (total %dms, layout %dms)",
                            sorted.size(), totalMs, edtMs));
                    }
                    catch (Throwable ex)
                    {
                        // Catch Throwable so Errors from RuneLite APIs don't leave refreshing=true.
                        log.debug("Refresh EDT rebuild failed", ex);
                    }
                    finally
                    {
                        refreshing.set(false);
                    }
                });
            }
            catch (Throwable e)
            {
                log.debug("Refresh background thread failed", e);
                refreshing.set(false);
            }
        });
    }

    /** Returns the source group key for a boss (COMBAT, PICKPOCKET, or SKILL). */
    private String getSourceGroupKey(String npcName)
    {
        if (lootManager.isPickpocketSource(npcName)) return "PICKPOCKET";
        if (lootManager.isSkillingSource(npcName))   return "SKILLING";
        return "COMBAT";
    }

    private boolean passesFilter(String npcName)
    {
        boolean isSkilling   = lootManager.isSkillingSource(npcName);
        boolean isPickpocket = lootManager.isPickpocketSource(npcName);
        switch (currentFilter)
        {
            case COMBAT:
                return !isSkilling && !isPickpocket;
            case SKILLS:
                if (currentSkillFilter == null)
                    return isSkilling || isPickpocket;
                if ("Thieving".equals(currentSkillFilter))
                    return isPickpocket;
                return npcName.equals(LootTrackerManager.SKILLING_PREFIX + currentSkillFilter);
            default:
                return true;
        }
    }

    /**
     * Returns true if this boss entry should be filtered out from display.
     * Filters out entries with 0 items AND 0 value (no-drop encounters like
     * raid adds). Does NOT filter entries that have items but 0 value.
     */
    private boolean isEmptyBossEntry(BossKillStats stats)
    {
        if (stats == null) return true;

        List<BossKillStats.AggregatedDrop> drops = stats.getAggregatedDrops();
        boolean hasItems = !drops.isEmpty();
        boolean hasValue = stats.getTotalLootValue() > 0;

        // Only filter out if BOTH conditions are true: no items AND no value
        return !hasItems && !hasValue;
    }

    private String buildDisplayFingerprint(List<BossKillStats> sortedStats, String highlight)
    {
        StringBuilder sb = new StringBuilder(sortedStats.size() * 40 + 32);
        sb.append(highlight == null ? "" : highlight)
                .append('|').append(currentSort.name())
                .append('|').append(currentFilter.name())
                .append('|').append(currentSkillFilter == null ? "" : currentSkillFilter)
                .append('|').append(showIgnoredItems).append('|');

        for (BossKillStats s : sortedStats)
        {
            // Only fingerprint structure: boss name + kill count + sort order
            // Exclude timestamp (changes on every kill) and values (change with items)
            // This allows fast path to trigger for incremental updates while detecting
            // structural changes (new bosses, removed bosses, reordering, filter changes)
            sb.append(s.getNpcName())
                    .append(':').append(s.getKillCount())
                    .append(';');
        }
        return sb.toString();
    }

    private void invalidateFingerprint() { lastDisplayFingerprint = null; }

    private String buildNameLabel(String npcName, int killCount)
    {
        String dn = displayNameFor(npcName);
        return truncate(dn, 18) + " × " + String.format("%,d", killCount);
    }

    /** Strips the internal pickpocket/skilling prefix so menus/labels show the plain NPC name. */
    private String displayNameFor(String npcName)
    {
        boolean ip = lootManager.isPickpocketSource(npcName);
        boolean is = lootManager.isSkillingSource(npcName);
        return ip ? lootManager.stripPickpocketPrefix(npcName)
                : is ? lootManager.stripSkillingPrefix(npcName)
                : npcName;
    }

    private JPanel buildBossCard(BossKillStats stats)
    {
        final String npcName = stats.getNpcName();
        boolean ip = lootManager.isPickpocketSource(npcName);
        boolean is = lootManager.isSkillingSource(npcName);
        boolean hl = npcName.equals(highlightedBoss);

        List<BossKillStats.AggregatedDrop> drops = lootManager.getStorageDropsForBoss(npcName);
        long totalValue = drops.stream().mapToLong(BossKillStats.AggregatedDrop::getTotalValue).sum();
        if (totalValue <= 0) totalValue = stats.getTotalLootValue();

        JPanel card = new JPanel(new BorderLayout());
        card.setBackground(new Color(28, 28, 28));
        card.setBorder(new EmptyBorder(0, 0, 0, 0));

        Color borderCol = hl ? (ip ? new Color(160, 80, 255) : is ? new Color(60, 180, 80) : new Color(0, 180, 60))
                : new Color(50, 50, 50);

        JPanel container = new JPanel(new BorderLayout());
        container.setBorder(BorderFactory.createLineBorder(borderCol, hl ? 2 : 1));
        container.setOpaque(false);

        Color headerBg = hl ? (ip ? PICKPOCKET_HEADER_HL : is ? SKILLING_HEADER_HL : new Color(20, 35, 20))
                : (ip ? PICKPOCKET_HEADER_BASE : is ? SKILLING_HEADER_BASE : new Color(36, 36, 36));

        JPanel headerRow = new JPanel(new BorderLayout());
        headerRow.setBackground(headerBg);
        headerRow.setPreferredSize(new Dimension(0, 28));
        headerRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        Color nameCol = hl ? (ip ? new Color(200, 160, 255) : is ? new Color(140, 230, 140) : new Color(100, 255, 100))
                : new Color(210, 210, 210);

        boolean bossHiddenForLabel = lootManager.isBossHidden(npcName);
        String  nameText = buildNameLabel(npcName, stats.getKillCount()) + (bossHiddenForLabel ? "  (hidden)" : "");
        JLabel nameLabel = new JLabel(nameText);
        nameLabel.setForeground(bossHiddenForLabel ? new Color(140, 90, 90) : nameCol);
        nameLabel.setFont(CALIBRI_BOLD);
        nameLabel.setBorder(new EmptyBorder(0, 8, 0, 4));
        nameLabel.setVerticalAlignment(JLabel.CENTER);

        JLabel valueLabel = new JLabel(totalValue > 0 ? formatGp(totalValue) : "");
        valueLabel.setForeground(new Color(200, 180, 80));
        valueLabel.setFont(CALIBRI_VALUE);
        valueLabel.setBorder(new EmptyBorder(0, 4, 0, 8));
        valueLabel.setVerticalAlignment(JLabel.CENTER);
        if (totalValue > 0)
            valueLabel.setToolTipText(String.format("%,d GP", totalValue));

        // Count hidden items for this boss
        long hiddenItemCount = drops.stream()
                .filter(d -> lootManager.isDropHidden(npcName, d.getItemId()))
                .count();

        JPanel rightPanel = new JPanel(new BorderLayout());
        rightPanel.setOpaque(false);
        rightPanel.add(valueLabel, BorderLayout.EAST);

        headerRow.add(nameLabel,  BorderLayout.WEST);
        headerRow.add(rightPanel, BorderLayout.EAST);

        bossNameLabelMap.put(npcName,  nameLabel);
        bossValueLabelMap.put(npcName, valueLabel);

        JPanel grid = buildItemGrid(drops, npcName);
        JPanel gridWrapper = new JPanel(new BorderLayout());
        gridWrapper.setBackground(new Color(28, 28, 28));
        gridWrapper.add(grid, BorderLayout.NORTH);
        gridWrapper.setVisible(bossExpandedState.getOrDefault(npcName, true));
        bossGridWrapperMap.put(npcName, gridWrapper);

        boolean bossHidden = lootManager.isBossHidden(npcName);
        String  bossDisplayName = displayNameFor(npcName);
        JPopupMenu headerMenu = new JPopupMenu();
        JMenuItem toggleBossHide = new JMenuItem(bossHidden
                ? "Unhide \"" + bossDisplayName + "\"'s loot"
                : "Hide \"" + bossDisplayName + "\"'s loot");
        toggleBossHide.addActionListener(e -> {
            if (lootManager.isBossHidden(npcName)) lootManager.unhideBoss(npcName);
            else                                    lootManager.hideBoss(npcName);
            invalidateFingerprint();
            refreshDisplay();
        });
        headerMenu.add(toggleBossHide);
        headerMenu.addSeparator();

        // Add "Hide Items" option if there are visible items
        long visibleItemCount = drops.stream()
                .filter(d -> !lootManager.isDropHidden(npcName, d.getItemId()))
                .count();
        if (visibleItemCount > 0)
        {
            JMenuItem hideItems = new JMenuItem("Hide Items (" + visibleItemCount + ")");
            hideItems.addActionListener(e -> {
                for (BossKillStats.AggregatedDrop drop : drops)
                {
                    if (!lootManager.isDropHidden(npcName, drop.getItemId()))
                        lootManager.hideDropForNpc(npcName, drop.getItemId());
                }
                invalidateFingerprint();
                refreshDisplay();
            });
            headerMenu.add(hideItems);
        }

        // Add "Unhide Items" option if there are hidden items
        if (hiddenItemCount > 0)
        {
            JMenuItem unhideItems = new JMenuItem("Unhide Items (" + hiddenItemCount + ")");
            unhideItems.addActionListener(e -> {
                for (BossKillStats.AggregatedDrop drop : drops)
                {
                    if (lootManager.isDropHidden(npcName, drop.getItemId()))
                        lootManager.unhideDropForNpc(npcName, drop.getItemId());
                }
                invalidateFingerprint();
                refreshDisplay();
            });
            headerMenu.add(unhideItems);
        }

        headerRow.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (!SwingUtilities.isLeftMouseButton(e)) return;
                boolean nowVisible = !gridWrapper.isVisible();
                gridWrapper.setVisible(nowVisible);
                bossExpandedState.put(npcName, nowVisible);
                container.revalidate();
                container.repaint();
                SwingUtilities.invokeLater(() -> {
                    bossListPanel.revalidate();
                    bossListPanel.repaint();
                });
            }

            @Override
            public void mousePressed(MouseEvent e)  { if (e.isPopupTrigger()) headerMenu.show(e.getComponent(), e.getX(), e.getY()); }
            @Override
            public void mouseReleased(MouseEvent e) { if (e.isPopupTrigger()) headerMenu.show(e.getComponent(), e.getX(), e.getY()); }
        });

        container.add(headerRow,   BorderLayout.NORTH);
        container.add(gridWrapper, BorderLayout.CENTER);
        card.add(container, BorderLayout.CENTER);

        bossCardMap.put(npcName, card);
        return card;
    }

    private JPanel buildItemGrid(List<BossKillStats.AggregatedDrop> drops, String npcName)
    {
        List<BossKillStats.AggregatedDrop> visible = new ArrayList<>();
        for (BossKillStats.AggregatedDrop d : drops)
            if (!lootManager.isDropHidden(npcName, d.getItemId()) || showIgnoredItems)
                visible.add(d);

        JPanel grid = new JPanel(new GridLayout(0, ITEMS_PER_ROW, ITEM_GAP, ITEM_GAP));
        grid.setBackground(new Color(28, 28, 28));
        grid.setBorder(new EmptyBorder(4, 4, 5, 4));

        if (visible.isEmpty())
        {
            grid.setLayout(new FlowLayout(FlowLayout.LEFT));
            JLabel none = new JLabel("No drops recorded yet");
            none.setForeground(new Color(80, 80, 80));
            none.setFont(CALIBRI_PLAIN);
            grid.add(none);
            return grid;
        }

        for (BossKillStats.AggregatedDrop drop : visible)
        {
            boolean hidden  = lootManager.isDropHidden(npcName, drop.getItemId());
            boolean isPet   = drop.isPet();
            String  tooltip = buildTooltip(drop);
            String  slotKey = npcName + "_" + drop.getItemId();

            JPanel slot = new JPanel(new BorderLayout());
            slot.setOpaque(true);
            if (isPet)
                slot.setBackground(new Color(50, 40, 10));
            else
                // Hidden items have a more distinct dark red background
                slot.setBackground(hidden ? new Color(60, 30, 30) : new Color(35, 35, 35));

            Color borderColor = isPet ? new Color(200, 160, 40)
                    : hidden ? new Color(220, 40, 40) : new Color(58, 58, 58);  // Bright red for hidden items
            slot.setBorder(BorderFactory.createLineBorder(borderColor, hidden ? 2 : (isPet ? 2 : 1)));
            slot.setPreferredSize(new Dimension(ITEM_SIZE, ITEM_SIZE));
            slot.setToolTipText(tooltip);

            // Use layered pane so the ★ badge can float over the item icon
            JLayeredPane layers = new JLayeredPane();
            layers.setPreferredSize(new Dimension(ITEM_SIZE, ITEM_SIZE));
            layers.setOpaque(false);

            JLabel iconLabel = new JLabel();
            iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
            iconLabel.setVerticalAlignment(SwingConstants.CENTER);
            iconLabel.setToolTipText(tooltip);
            iconLabel.setBounds(0, 0, ITEM_SIZE, ITEM_SIZE);
            iconLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            if (isPet && drop.getItemId() == LootTrackerManager.PET_ITEM_ID_UNKNOWN)
            {
                // No sprite available — show a placeholder star icon
                iconLabel.setText("★");
                iconLabel.setFont(iconLabel.getFont().deriveFont(java.awt.Font.BOLD, 20f));
                iconLabel.setForeground(new Color(220, 180, 40));
            }
            else
            {
                long qty = drop.getTotalQuantity();
                itemManager.getImage(drop.getItemId(), (int) qty, qty > 1)
                        .addTo(iconLabel);
            }

            layers.add(iconLabel, JLayeredPane.DEFAULT_LAYER);

            if (isPet)
            {
                JLabel badge = new JLabel("★");
                badge.setFont(badge.getFont().deriveFont(java.awt.Font.BOLD, 9f));
                badge.setForeground(new Color(220, 180, 40));
                badge.setBounds(ITEM_SIZE - 12, ITEM_SIZE - 12, 12, 12);
                layers.add(badge, JLayeredPane.PALETTE_LAYER);
            }

            slot.add(layers, BorderLayout.CENTER);
            itemSlotMap.put(slotKey, iconLabel);

            JPopupMenu menu = new JPopupMenu();
            JMenuItem toggleHide = new JMenuItem(hidden
                    ? "Unhide \"" + drop.getItemName() + "\""
                    : "Hide \"" + drop.getItemName() + "\"");
            toggleHide.addActionListener(e -> {
                if (hidden) lootManager.unhideDropForNpc(npcName, drop.getItemId());
                else        lootManager.hideDropForNpc  (npcName, drop.getItemId());
                // Immediately update the grid for this boss (don't wait for debounce)
                SwingUtilities.invokeLater(() -> updateLoot(npcName));
            });
            menu.add(toggleHide);

            JMenuItem deleteItem = new JMenuItem("Delete \"" + drop.getItemName() + "\"");
            deleteItem.addActionListener(e -> {
                lootManager.deleteDropForNpc(npcName, drop.getItemId());
                // Immediately update the grid for this boss (don't wait for debounce)
                SwingUtilities.invokeLater(() -> updateLoot(npcName));
            });
            menu.add(deleteItem);

            // Add right-click listener to both slot and iconLabel to ensure menu shows
            MouseAdapter rightClickAdapter = new MouseAdapter()
            {
                @Override public void mousePressed (MouseEvent e) { if (e.isPopupTrigger()) menu.show(e.getComponent(), e.getX(), e.getY()); }
                @Override public void mouseReleased(MouseEvent e) { if (e.isPopupTrigger()) menu.show(e.getComponent(), e.getX(), e.getY()); }
            };
            slot.addMouseListener(rightClickAdapter);
            iconLabel.addMouseListener(rightClickAdapter);
            layers.addMouseListener(rightClickAdapter);

            grid.add(slot);
        }

        int rem = (ITEMS_PER_ROW - (visible.size() % ITEMS_PER_ROW)) % ITEMS_PER_ROW;
        for (int i = 0; i < rem; i++) { JPanel p = new JPanel(); p.setOpaque(false); grid.add(p); }

        return grid;
    }

