            JLabel titleLbl = new JLabel(title);
            titleLbl.setFont(cf(Font.BOLD, 11f));
            titleLbl.setForeground(TEAL_COLOR);
            header.add(titleLbl);

            card.add(header);
            card.add(RuneAlyticsUi.vSpace(8));
        }

        card.add(body);
        return card;
