    }

    // ═════════════════════════════════════════════════════════════════════════
    //  Inner classes
    // ═════════════════════════════════════════════════════════════════════════

    /** Circular avatar with a single initial letter, matching the mockup style. */
    private static class AvatarLabel extends JComponent
    {
        private char initial;
        private static final int SIZE = 36;

        AvatarLabel(String name)
        {
            this.initial = name != null && !name.isEmpty() ? Character.toUpperCase(name.charAt(0)) : '?';
            Dimension d = new Dimension(SIZE, SIZE);
            setPreferredSize(d);
            setMinimumSize(d);
            setMaximumSize(d);
        }

        void setInitial(char c)
        {
            this.initial = Character.toUpperCase(c);
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);

            // circle background
            g2.setColor(new Color(55, 55, 65));
            g2.fillOval(0, 0, SIZE, SIZE);
            g2.setColor(new Color(80, 80, 95));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawOval(0, 0, SIZE - 1, SIZE - 1);

            // initial letter
            g2.setColor(COL_WHITE);
            g2.setFont(new Font("Calibri", Font.BOLD, 15));
            FontMetrics fm = g2.getFontMetrics();
            String s = String.valueOf(initial);
            int x = (SIZE - fm.stringWidth(s)) / 2;
            int y = (SIZE - fm.getHeight()) / 2 + fm.getAscent();
            g2.drawString(s, x, y);
            g2.dispose();
        }
    }

    /** Green trophy circle, drawn entirely in code (no image dependency). */
    private static class TrophyIcon extends JComponent
    {
        private static final int SIZE = 40;

        TrophyIcon()
        {
            Dimension d = new Dimension(SIZE, SIZE);
            setPreferredSize(d);
            setMinimumSize(d);
            setMaximumSize(d);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);

            g2.setColor(new Color(30, 80, 50));
            g2.fillOval(0, 0, SIZE, SIZE);
            g2.setColor(COL_GREEN);
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawOval(0, 0, SIZE - 1, SIZE - 1);

            g2.setColor(COL_GREEN);
            g2.setFont(new Font("Calibri", Font.BOLD, 20));
            FontMetrics fm = g2.getFontMetrics();
            String s = "🏆";
            // fallback to text glyph for environments without emoji font
            if (fm.stringWidth(s) == 0) s = "W";
            int x = (SIZE - fm.stringWidth(s)) / 2;
            int y = (SIZE - fm.getHeight()) / 2 + fm.getAscent();
            g2.drawString(s, x, y);
            g2.dispose();
        }
    }

    /**
     * FlowLayout variant that wraps items to a new row when the container
     * is too narrow, rather than clipping.  Used for the gear-rules pill strip.
     */
    private static class WrapLayout extends FlowLayout
    {
        WrapLayout(int align, int hgap, int vgap)
        { super(align, hgap, vgap); }

        @Override
        public Dimension preferredLayoutSize(Container target)
        { return layoutSize(target, true); }

        @Override
        public Dimension minimumLayoutSize(Container target)
        { return layoutSize(target, false); }

        private Dimension layoutSize(Container target, boolean preferred)
        {
            synchronized (target.getTreeLock())
            {
                int targetWidth = target.getSize().width;
                if (targetWidth == 0) targetWidth = Integer.MAX_VALUE;

                int hgap = getHgap(), vgap = getVgap();
                Insets insets = target.getInsets();
                int maxWidth = targetWidth - (insets.left + insets.right + hgap * 2);

                Dimension dim = new Dimension(0, 0);
                int rowWidth = 0, rowHeight = 0;

                int nmembers = target.getComponentCount();
                for (int i = 0; i < nmembers; i++)
                {
                    Component m = target.getComponent(i);
                    if (m.isVisible())
                    {
                        Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();
                        if (rowWidth + d.width > maxWidth && rowWidth > 0)
                        {
                            dim.width = Math.max(dim.width, rowWidth);
                            dim.height += rowHeight + vgap;
                            rowWidth = 0;
                            rowHeight = 0;
                        }
                        rowWidth += d.width + hgap;
                        rowHeight = Math.max(rowHeight, d.height);
                    }
                }
                dim.width  = Math.max(dim.width, rowWidth);
                dim.height += rowHeight + insets.top + insets.bottom + vgap * 2;
                return dim;
            }
        }
    }

    private static final class AutoHeightPanel extends JPanel
    {
        @Override
        public Dimension getMaximumSize()
        {
            Dimension preferred = getPreferredSize();
            return new Dimension(Integer.MAX_VALUE, preferred.height);
        }
    }

    /**
     * Scroll-pane content panel that always matches the viewport width (so cards
     * fill the panel rather than being clipped) but keeps its natural height (so
     * vertical overflow scrolls).  Tracking the viewport width — together with
     * the shrinkable long-text labels — guarantees a card can never demand more
     * horizontal space than the sidebar provides.
     */
    private static final class ScrollableContentPanel extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return Math.max(16, visibleRect.height - 32);
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }

    /**
     * Allows a label/component to shrink below its preferred (text) width so it
     * clips instead of forcing its container — and therefore the whole sidebar —
     * to grow.  The full text is still available via a tooltip.
     */
    private static void makeShrinkable(JComponent c)
    {
        c.setMinimumSize(new Dimension(0, c.getPreferredSize().height));
    }

    @Override
    public void onDataRefresh() { }
}

