    // ─────────────────────────────────────────────────────────────────────────
    //  ZERO-LOOT KILL TRACKING
    //
    //  NpcLootReceived fires only when a kill produced loot, so dry kills are
    //  captured here:
    //
    //    1. Track every NPC the local player damaged (HitsplatApplied with
    //       hitsplat.isMine())
    //    2. On ActorDeath for a damaged NPC, queue a pending zero-loot kill
    //       that flushes ZERO_LOOT_FLUSH_TICKS game ticks later
    //    3. If NpcLootReceived arrives first, the pending entry is cancelled
    //
    //  Chest-only bosses (raids, Nightmare, Yama, Royal Titans, etc.) are
    //  excluded inside LootTrackerManager#processZeroLootKill.
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Game ticks to wait after ActorDeath before flushing a pending zero-loot
     * kill, allowing NpcLootReceived time to cancel it. 3 ticks ≈ 1.8 s.
     */
    private static final int ZERO_LOOT_FLUSH_TICKS = 3;

    /** NPC indexes the local player damaged this combat. */
    private final Map<Integer, NPC> damagedNpcs = new HashMap<>();

    /**
     * NPCs that have entered the dying animation and are awaiting either a
     * cancelling {@link NpcLootReceived} or a scheduled flush as a zero-loot
     * kill.  Keyed by NPC index.
     */
    private final Map<Integer, PendingDeath> pendingDeaths = new HashMap<>();

    /** Plugin-local game tick counter; incremented every {@link #onGameTick}. */
    private long gameTickCount = 0;

    /**
     * NPC index → wall-clock time a zero-loot kill was flushed for it. Under
     * load (e.g. an AOE kill that drops several NPCs at once) NpcLootReceived
     * can lag past {@link #ZERO_LOOT_FLUSH_TICKS}, so the zero-loot kill gets
     * recorded first and the real loot event arrives afterwards — without this,
     * that late event would record a SECOND kill instead of attaching its drops
     * to the kill that's already counted, doubling the kill count.
     */
    private final Map<Integer, Long> recentZeroLootFlushes = new HashMap<>();

    /** How long a {@link #recentZeroLootFlushes} entry stays eligible for upgrade. */
    private static final long ZERO_LOOT_UPGRADE_WINDOW_MS = 8_000;

    private static final class PendingDeath
    {
        final NPC  npc;
        final long flushAtTick;

        PendingDeath(NPC npc, long flushAtTick)
        {
            this.npc         = npc;
            this.flushAtTick = flushAtTick;
        }
    }

    // ═════════════════════════════════════════════════════════════════════════
    //  STARTUP / SHUTDOWN
    // ═════════════════════════════════════════════════════════════════════════

    @Override
    protected void startUp() throws Exception
    {
        log.debug("RuneAlytics starting");

        // Loot files live in ~/.runelite/plugin-data/runealytics. If the directory
        // can't be resolved, loot tracking still works in memory for the session.
        // Older builds wrote runealytics-loot-*.json in ~/.runelite itself; move
        // those across before anything can save.
        try
        {
            lootStorageManager.setDataDirectory(getPluginDirectory());
            lootStorageManager.migrateLegacyLootFiles(RuneLite.RUNELITE_DIR);
        }
        catch (Exception e)
        {
            log.debug("Unable to resolve RuneAlytics data directory; loot history will not be saved", e);
        }

        // Create dedicated executor for loot sync operations (separate from RuneLite's pool)
        syncExecutor = SyncExecutorFactory.createSyncExecutor();

        // Start health monitors for both executors to detect starvation
        syncExecutorMonitor = new ExecutorHealthMonitor(syncExecutor, "loot-sync");
        syncExecutorMonitor.start();
        sharedExecutorMonitor = new ExecutorHealthMonitor(executorService, "shared");
        sharedExecutorMonitor.start();

        // Initialize queue depth trackers if executors are ThreadPoolExecutor instances
        // Note: ScheduledExecutorService doesn't expose queue directly, so tracking
        // may not be available for the dedicated syncExecutor
        if (executorService instanceof java.util.concurrent.ThreadPoolExecutor)
        {
            sharedQueueTracker = new AsyncQueueDepthTracker(
                (java.util.concurrent.ThreadPoolExecutor) executorService, "shared");
            log.debug("[monitoring] Shared executor queue depth tracking enabled");
        }

        // Build the root panel on the EDT, then register the nav button.
        buildOnEdt(() -> mainPanel = injector.getInstance(RuneAlyticsPanel.class));

        navButton = NavigationButton.builder()
                .tooltip("RuneAlytics")
                .icon(loadPluginIcon())
                .priority(1)
                .panel(mainPanel)
                .build();
        clientToolbar.addNavigation(navButton);
        overlayManager.add(matchmakingOverlay);
        overlayManager.add(liveMapOverlay);
        log.debug("RuneAlytics nav button registered");

        // Construct the heavy sub-panels on the EDT.
        SwingUtilities.invokeLater(() ->
        {
            try
            {
                LootTrackerPanel        lootPanel        = injector.getInstance(LootTrackerPanel.class);
                RuneAlyticsXpTrackerPanel xpPanel        = injector.getInstance(RuneAlyticsXpTrackerPanel.class);
                MatchmakingPanel        matchmakingPanel = injector.getInstance(MatchmakingPanel.class);
                RuneAlyticsSettingsPanel settingsPanel   = injector.getInstance(RuneAlyticsSettingsPanel.class);
                // Create the verification panel singleton on the EDT.
                injector.getInstance(RuneAlyticsVerificationPanel.class);

                lootTrackerPanel = lootPanel;
                xpTrackerPanel   = xpPanel;
                // Give the panels a reference to this plugin for their buttons.
                lootPanel.setPlugin(this);
                xpPanel.setPlugin(this);
                // Sync starts in a neutral "checking…" state until feature flags
                // confirm whether it is active — never assert it's turned off
                // before we actually know (it defaults ON for verified players).
                lootPanel.setSyncChecking();

                // Loot Tracker has no feature gate — local tracking is always
                // available. The XP Tracker tab is gated by the server "xp_tracker"
                // flag; Matches by "match_finder"; Settings by verification.
                mainPanel.addTab("Loot Tracker", null,                 lootPanel);
                mainPanel.addTab("XP",           FEATURE_XP_TRACKER,   xpPanel);
                mainPanel.addTab("Matches",      FEATURE_MATCHES,      matchmakingPanel);
                mainPanel.addTab("Settings",     FEATURE_VERIFICATION, settingsPanel);
                log.debug("RuneAlytics tabs populated");
            }
            catch (Exception ex)
            {
                log.debug("Failed to populate RuneAlytics tabs", ex);
            }
        });
    }

    /**
     * Runs {@code r} on the Swing EDT and waits for it to finish. Runs inline if
     * already on the EDT, otherwise blocks via {@link SwingUtilities#invokeAndWait}.
     * Used so panel (Swing) construction never happens off the EDT.
     */
    private static void buildOnEdt(Runnable r) throws Exception
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            r.run();
        }
        else
        {
            SwingUtilities.invokeAndWait(r);
        }
    }

    @Override
    protected void shutDown()
    {
        log.debug("RuneAlytics shutting down");

        // Stop the live-map heartbeat so no pings fire after the plugin is gone.
        stopHeartbeat();

        // Cancel the pending whisperer loot flush.
        if (whispererFlushTask != null)
        {
            whispererFlushTask.cancel(false);
            whispererFlushTask = null;
        }

        // Stop health monitors before shutting down executors.
        try { if (syncExecutorMonitor != null) syncExecutorMonitor.stop(); } catch (Exception e) { log.debug("Sync executor health monitor stop failed: {}", e.getMessage()); }
        try { if (sharedExecutorMonitor != null) sharedExecutorMonitor.stop(); } catch (Exception e) { log.debug("Shared executor health monitor stop failed: {}", e.getMessage()); }

        // Clear all caches on shutdown.
        try { itemMetadataCache.clear(); } catch (Exception e) { log.debug("Item metadata cache clear failed: {}", e.getMessage()); }
        try { gePriceCache.clear(); } catch (Exception e) { log.debug("GE price cache clear failed: {}", e.getMessage()); }
        try { trackerResultsCache.clear(); } catch (Exception e) { log.debug("Tracker results cache clear failed: {}", e.getMessage()); }

        // Flush accumulated XP before the executor shuts down.
        try { xpTrackerManager.flushImmediate(); } catch (Exception e) { log.debug("XP flush on shutdown failed: {}", e.getMessage()); }
        // Flush the current XP session snapshot (final XP/hr) and pause its clock.
        try { flushXpSessionOnLogout(); } catch (Exception e) { log.debug("XP session flush on shutdown failed: {}", e.getMessage()); }
        try { xpSessionManager.setLoggedIn(false); } catch (Exception e) { log.debug("XP session pause on shutdown failed: {}", e.getMessage()); }
        try { lootManager.shutdown();             } catch (Exception e) { log.debug("Loot manager shutdown failed: {}", e.getMessage()); }
        try { matchmakingManager.reset();         } catch (Exception e) { log.debug("Matchmaking reset on shutdown failed: {}", e.getMessage()); }
        try { overlayManager.remove(matchmakingOverlay); } catch (Exception e) { log.debug("Matchmaking overlay removal failed: {}", e.getMessage()); }
        try { overlayManager.remove(liveMapOverlay);     } catch (Exception e) { log.debug("Live-map overlay removal failed: {}", e.getMessage()); }

        // Shutdown the dedicated sync executor.
        try { SyncExecutorFactory.shutdown(syncExecutor); } catch (Exception e) { log.debug("Sync executor shutdown failed: {}", e.getMessage()); }

        // Remove the nav button.
        if (navButton != null)
        {
            try { clientToolbar.removeNavigation(navButton); }
            catch (Exception e) { log.debug("Nav button removal failed: {}", e.getMessage()); }
            navButton = null;
        }

        state.reset();
    }

    private void clearTransientLootState()
    {
        lastKilledBoss            = null;
        lastKillTime              = 0L;
        lastChestSource           = null;
        inventorySnapshot         = null;
        waitingForTemporossLoot   = false;
        waitingForWintertodtLoot  = false;
        crateLootWaitExpiry       = 0L;
        whispererGroundItemWindow = false;
        whispererKillTime         = 0L;
        whispererGroundItems.clear();
        // Cancel the pending Whisperer flush.
        if (whispererFlushTask != null)
        {
            whispererFlushTask.cancel(false);
            whispererFlushTask = null;
        }
        groundLootSessions.clear();

        // Clear Ring of Wealth snapshot
        rowInventorySnapshot = null;
        rowSnapshotBoss      = null;
        rowSnapshotExpiry    = 0L;

        // Clear pickpocket state
        pendingPickpocketNpc        = null;
        pickpocketInventorySnapshot = null;
        pickpocketWindowExpiry      = 0L;

        // Clear impling jar state
        pendingImpJarName       = null;
        impJarInventorySnapshot = null;
        impJarWindowExpiry      = 0L;

        // Clear zero-loot kill tracking (damage history is per-world)
        damagedNpcs.clear();
        pendingDeaths.clear();
        recentZeroLootFlushes.clear();

        // Clear interface-open suppression state
        inventoryDiffGuard.reset();

        // Clear skilling state
        skillingSnapshot.clear();
        skillingExpiry.clear();
        preFarmingSnapshot = null;
    }

