    /**
     * Unified loot sync triggered by the single "Sync" button and by the
     * automatic login sync.
     *
     * <p>Runs the full pipeline for the <em>currently logged-in</em> account:
     * pull server history → import RuneLite tracker → upload unsynced kills →
     * three-source absolute-merge reconcile → upload. All scoped to the live
     * account so no other profile's data can leak in.</p>
     *
     * <p>Blocked (with a UI message when {@code userInitiated}) if no account is
     * logged in or the logged-in account doesn't match the linked RuneAlytics
     * account. Always runs off the client thread.</p>
     */
    public void performLootSync(boolean userInitiated)
    {
        if (!currentPlayerIdentity.canSync())
        {
            if (userInitiated && lootTrackerPanel != null)
            {
                String msg = currentPlayerIdentity.getMismatchMessage();
                if (msg != null) lootTrackerPanel.showAccountMismatch(msg);
                else                lootTrackerPanel.showSyncBusy("Log in to sync loot…");
            }
            return;
        }

        final String accountKey = currentPlayerIdentity.getAccountKey();
        if (accountKey == null)
        {
            if (userInitiated && lootTrackerPanel != null)
            {
                lootTrackerPanel.showSyncBusy("Log in to sync loot…");
            }
            return;
        }

        SyncRequest request = new SyncRequest(
            userInitiated ? SyncRequest.Priority.MANUAL : SyncRequest.Priority.AUTO,
            true,
            userInitiated ? "manual_user_click" : "auto_trigger"
        );

        syncExecutor.submit(() ->
        {
            if (!syncCoordinator.tryStartSync(request))
            {
                if (userInitiated && lootTrackerPanel != null)
                {
                    SwingUtilities.invokeLater(() ->
                            lootTrackerPanel.showSyncBusy("A sync is already running…"));
                }
                return;
            }
            try
            {
                runSyncPipeline(accountKey, true, userInitiated);
            }
            finally
            {
                SyncRequest pending = syncCoordinator.endSync();
                if (pending != null && pending.isFullReconcile())
                {
                    log.debug("[Sync] Starting coalesced follow-up sync: {}", pending);
                    performLootSync(userInitiated);
                }
            }
        });
    }

    /**
     * Flushes the current account's loot to the server on logout.
     *
     * <p>Must be called on the client thread <em>before</em> {@code loggedIn} is
     * flipped to {@code false}, so the sync slot can be claimed while the
     * session is still valid. Upload-only (no pull) to keep logout snappy.</p>
     */
    private void performLogoutSyncFlush()
    {
        final String accountKey = currentPlayerIdentity.getLastKnownAccountKey();
        if (accountKey == null) return;
        if (!currentPlayerIdentity.isLinkedAccount(accountKey)) return;

        SyncRequest request = new SyncRequest(
            SyncRequest.Priority.LOGOUT,
            false,
            "logout_flush_upload_only"
        );

        if (!syncCoordinator.tryStartSync(request)) return;

        syncExecutor.submit(() ->
        {
            try     { runSyncPipeline(accountKey, false, false); }
            finally
            {
                SyncRequest pending = syncCoordinator.endSync();
                if (pending != null && pending.isFullReconcile())
                {
                    log.debug("[Sync] Starting coalesced follow-up sync after logout: {}", pending);
                    performLootSync(false);
                }
            }
        });
    }

    /**
     * Shared sync body. The caller MUST already hold the sync slot.
     *
     * @param accountKey    normalized account to scope every step to
     * @param pull          when {@code true}, also pull server history + import
     *                      RuneLite tracker before uploading; {@code false} for
     *                      an upload-only logout flush
     * @param userInitiated when {@code true}, surface failures in the UI
     */
    private void runSyncPipeline(String accountKey, boolean pull, boolean userInitiated)
    {
        // Capture immutable context at sync start so stale results cannot
        // alter a different account/session after logout/switch
        final SyncContext syncContext = new SyncContext(
            state.getVerifiedUsername(),
            accountKey,
            state.getSessionGeneration(),
            userInitiated ? "manual" : "auto"
        );

        PerformanceMetrics metrics = new PerformanceMetrics();
        SyncWatchdog watchdog = new SyncWatchdog();

        try
        {
            log.debug("[plugin] Loot sync start (account='{}', pull={} session={})",
                accountKey, pull, syncContext.getSessionGeneration());

            if (userInitiated && lootTrackerPanel != null)
            {
                SwingUtilities.invokeLater(() -> lootTrackerPanel.showSyncPhase("Syncing with server…"));
            }

            // 1. Legacy per-kill website history pull + upload.
            //    Pull from website first to establish baseline before merge.
            lootManager.syncLegacyBlocking(accountKey, pull, userInitiated);
            metrics.markLegacySyncComplete();

            if (watchdog.hasTimedOut())
            {
                log.debug("[watchdog] Sync timed out during legacy sync phase ({}ms elapsed)",
                        watchdog.getElapsedMs());
                throw new RuntimeException("Sync operation timed out");
            }

            if (userInitiated && lootTrackerPanel != null)
            {
                SwingUtilities.invokeLater(() -> lootTrackerPanel.showSyncPhase("Reconciling data…"));
            }

            // 2. Absolute-merge reconcile: reads fresh data from RuneLite's loot tracker
            //    file and website snapshot, merges all available values (local, RuneLite,
            //    website) using max semantics so the highest value from any source wins,
            //    then applies the result back to local storage.
            LootSyncMergeService.MergeResult result =
                    lootSyncMergeService.performMergeForAccount(accountKey, userInitiated);
            metrics.markMergeComplete(
                lootManager.getStorageRecordCount(),
                lootManager.getStorageUniqueItemCount()
            );

            if (watchdog.hasTimedOut())
            {
                log.debug("[watchdog] Sync timed out during merge phase ({}ms elapsed)",
                        watchdog.getElapsedMs());
                throw new RuntimeException("Sync operation timed out");
            }

            // Validate context before applying merge result
            // If account switched or session changed, discard result
            if (!syncContext.isStillValid(state))
            {
                log.debug("[plugin] Discarding stale sync result (context no longer valid): {}", syncContext);
                return;
            }

            // The merge writes straight to LootStorageData, bypassing the
            // in-memory display cache — rebuild it now so the panel reflects
            // the merged KCs/drops (and any newly-empty placeholders get
            // purged) instead of showing a stale pre-merge snapshot.
            lootManager.refreshFromStorage(userInitiated);
            metrics.markUiRefreshComplete();

            if (watchdog.hasTimedOut())
            {
                log.debug("[watchdog] Sync timed out during UI refresh phase ({}ms elapsed)",
                        watchdog.getElapsedMs());
            }

            metrics.logSummary(accountKey, syncContext.getReason());

            // Log cache statistics and memory pressure at end of sync
            logMonitoringMetrics();

            SwingUtilities.invokeLater(() ->
            {
                if (lootTrackerPanel == null) return;
                if (result.isSuccess())          lootTrackerPanel.showAbsoluteMergeResult(result);
                else if (userInitiated)          lootTrackerPanel.showSyncFailed(result.getBlockedReason());
            });
        }
        catch (Throwable t)
        {
            // Catch Throwable (not just Exception) so an Error — e.g. an
            // ItemManager "must be called on client thread" assertion — still
            // resets the Sync button instead of leaving it stuck on "Syncing…".
            log.debug("[plugin] Loot sync failed (account='{}' session={} elapsed={}ms): {}",
                accountKey, syncContext.getSessionGeneration(), watchdog.getElapsedMs(), t.getMessage());
            if (userInitiated)
            {
                SwingUtilities.invokeLater(() -> {
                    if (lootTrackerPanel != null) lootTrackerPanel.showSyncFailed(t.getMessage());
                });
            }
        }
    }

    /**
     * Logs monitoring metrics including cache statistics and memory pressure.
     * Called at the end of sync pipeline to capture performance data.
     */
    private void logMonitoringMetrics()
    {
        // Cache statistics
        double itemCacheHitRate = itemMetadataCache.getHitRate();
        double geCacheHitRate = gePriceCache.getHitRate();
        double trackerCacheHitRate = trackerResultsCache.getHitRate();

        log.debug(LogCategory.PERF.format(
            "Sync metrics - ItemCache: %.1f%% (%d/%d) | " +
            "GECache: %.1f%% (%d/%d) | MergeCache: %.1f%% (%d/%d)",
            itemCacheHitRate, itemMetadataCache.getHits(),
            itemMetadataCache.getHits() + itemMetadataCache.getMisses(),
            geCacheHitRate, gePriceCache.getHits(),
            gePriceCache.getHits() + gePriceCache.getMisses(),
            trackerCacheHitRate, trackerResultsCache.getHits(),
            trackerResultsCache.getHits() + trackerResultsCache.getMisses()
        ));

        // Log queue depth if available
        if (sharedQueueTracker != null)
        {
            log.debug(LogCategory.EXECUTOR.format(
                "Shared executor - Queue: %d | Active: %d | Peak: %d | " +
                "Submitted: %d | Completed: %d",
                sharedQueueTracker.getQueueDepth(),
                sharedQueueTracker.getActiveThreadCount(),
                sharedQueueTracker.getPeakQueueDepth(),
                sharedQueueTracker.getTotalSubmitted(),
                sharedQueueTracker.getTotalCompleted()
            ));
        }
    }

