    private JLabel sectionLabel(String text)
    {
        JLabel l = new JLabel(text);
        l.setFont(SECTION_FONT);
        l.setForeground(GOLD);
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        return l;
    }
}

package com.runealytics;

import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;

import static com.runealytics.RuneAlyticsXpTrackerPanel.CARD_BG;
import static com.runealytics.RuneAlyticsXpTrackerPanel.CARD_BORDER;
import static com.runealytics.RuneAlyticsXpTrackerPanel.GOLD;
import static com.runealytics.RuneAlyticsXpTrackerPanel.MUTED;
import static com.runealytics.RuneAlyticsXpTrackerPanel.XP_GREEN;

/**
 * One skill row in the XP Tracker skill list.
 *
 * <p>Created once per skill and reused — {@link #update} only mutates label text
 * and the progress fraction, so polling it from the refresh timer is cheap and
 * causes no structural relayout. Left-clicking the row opens that skill's detail
 * view; right-clicking opens a menu to reset the skill's XP/hr or session XP.</p>
 */
class RuneAlyticsXpSkillRow extends JPanel
{
    private static final Font NAME_FONT  = new Font("Calibri", Font.BOLD, 13);
    private static final Font LVL_FONT    = new Font("Calibri", Font.PLAIN, 11);
    private static final Font VALUE_FONT  = new Font("Calibri", Font.BOLD, 12);
    private static final Font SMALL_FONT  = new Font("Calibri", Font.PLAIN, 11);
    private static final Font LIVE_FONT   = new Font("Calibri", Font.BOLD, 9);

    private static final Color HOVER_BG = new Color(34, 41, 60);
    private static final Color DIM_ACCENT = new Color(90, 96, 110);

    /** "LIVE" shows at full opacity for this long after the last XP gain… */
    private static final long LIVE_WINDOW_MS = 15_000L;
    /** …then fades out over this long before disappearing. */
    private static final long LIVE_FADE_MS   = 2_500L;

    private final Skill skill;
    private final RunealyticsConfig config;
    private final Color skillColor;

    // LIVE fade state (driven by the panel's animation tick).
    private long lastGainWallMs = 0L;
    private boolean hiddenNow = false;
    private int lastLiveAlpha = -1;

    private final JLabel nameLabel   = new JLabel();
    private final JLabel starLabel   = new JLabel("★");
    private final JLabel liveLabel   = new JLabel("● LIVE");
    private final JLabel levelLabel  = new JLabel();
    private final JLabel gainedLabel = new JLabel();
    private final JLabel rateLabel   = new JLabel();
    private final JLabel infoLabel   = new JLabel();
    private final XpProgressBar bar  = new XpProgressBar();
    private final JPanel bottomRow;
    private final JMenuItem hideItem = new JMenuItem("Hide skill");
    private final JMenuItem favItem  = new JMenuItem("Favorite skill");

    RuneAlyticsXpSkillRow(Skill skill, SkillIconManager iconManager, RunealyticsConfig config,
                          Consumer<Skill> onClick, Consumer<Skill> onResetRate,
                          Consumer<Skill> onResetSession, Consumer<Skill> onToggleHide,
                          Consumer<Skill> onToggleFavorite)
    {
        this.skill      = skill;
        this.config     = config;
        this.skillColor = SkillColors.of(skill);

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(CARD_BG);
        setOpaque(true);
        setAlignmentX(Component.LEFT_ALIGNMENT);
        setBorder(new CompoundBorder(
                new LineBorder(CARD_BORDER, 1, true),
                new EmptyBorder(6, 8, 6, 8)));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 65));

        // ── Top row: [icon] name / level ............ gained  rate ──
        JPanel top = new JPanel(new BorderLayout(6, 0));
        top.setOpaque(false);
        top.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Skill sprite on a circular MEDIUM_GRAY backing so it stays legible.
        XpSkillIcon iconLabel = new XpSkillIcon(24);
        try
        {
            iconLabel.setImage(iconManager.getSkillImage(skill, true));
        }
        catch (Exception ignored)
        {
            // Fall back to an empty circle if icons are unavailable.
        }

        JPanel nameCol = new JPanel();
        nameCol.setLayout(new BoxLayout(nameCol, BoxLayout.Y_AXIS));
        nameCol.setOpaque(false);
        nameLabel.setFont(NAME_FONT);
        nameLabel.setForeground(skillColor);
        nameLabel.setText(prettyName(skill));
        bar.setAccent(skillColor);

        // Name line: [Skill name]  ● LIVE (green, only while actively training)
        JPanel nameLine = new JPanel();
        nameLine.setLayout(new BoxLayout(nameLine, BoxLayout.X_AXIS));
        nameLine.setOpaque(false);
        nameLine.setAlignmentX(Component.LEFT_ALIGNMENT);
        starLabel.setFont(LIVE_FONT);
        starLabel.setForeground(GOLD);
        starLabel.setVisible(false);
        liveLabel.setFont(LIVE_FONT);
        liveLabel.setForeground(XP_GREEN);
        liveLabel.setVisible(false);
        nameLine.add(nameLabel);
        nameLine.add(Box.createRigidArea(new Dimension(4, 0)));
        nameLine.add(starLabel);
        nameLine.add(Box.createRigidArea(new Dimension(4, 0)));
        nameLine.add(liveLabel);
        nameLine.add(Box.createHorizontalGlue());

        levelLabel.setFont(LVL_FONT);
        levelLabel.setForeground(MUTED);
        levelLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        nameCol.add(nameLine);
        nameCol.add(levelLabel);

        JPanel left = new JPanel(new BorderLayout(6, 0));
        left.setOpaque(false);
        left.add(iconLabel, BorderLayout.WEST);
        left.add(nameCol,   BorderLayout.CENTER);

        JPanel valueCol = new JPanel();
        valueCol.setLayout(new BoxLayout(valueCol, BoxLayout.Y_AXIS));
        valueCol.setOpaque(false);
        gainedLabel.setFont(VALUE_FONT);
        gainedLabel.setForeground(GOLD);
        gainedLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);
        rateLabel.setFont(SMALL_FONT);
        rateLabel.setForeground(XP_GREEN);
        rateLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);
        valueCol.add(gainedLabel);
        valueCol.add(rateLabel);

        top.add(left,     BorderLayout.CENTER);
        top.add(valueCol, BorderLayout.EAST);

        // ── Bottom row: [progress bar] .......... time-to-level · xp to next ──
        bottomRow = new JPanel(new BorderLayout(6, 0));
        bottomRow.setOpaque(false);
        bottomRow.setBorder(new EmptyBorder(4, 0, 0, 0));
        bottomRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        infoLabel.setFont(SMALL_FONT);
        infoLabel.setForeground(MUTED);
        infoLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        bottomRow.add(bar,       BorderLayout.CENTER);
        bottomRow.add(infoLabel, BorderLayout.EAST);

        add(top);
        add(Box.createRigidArea(new Dimension(0, 2)));
        add(bottomRow);

        // ── Right-click menu: hide + resets ──
        JPopupMenu menu = new JPopupMenu();
        JMenuItem header = new JMenuItem(prettyName(skill));
        header.setEnabled(false);
        menu.add(header);
        menu.addSeparator();
        favItem.addActionListener(e -> { if (onToggleFavorite != null) onToggleFavorite.accept(skill); });
        hideItem.addActionListener(e -> { if (onToggleHide != null) onToggleHide.accept(skill); });
        JMenuItem resetRateItem = new JMenuItem("Reset XP/hr");
        resetRateItem.addActionListener(e -> { if (onResetRate != null) onResetRate.accept(skill); });
        JMenuItem resetSessionItem = new JMenuItem("Reset session XP");
        resetSessionItem.addActionListener(e -> { if (onResetSession != null) onResetSession.accept(skill); });
        menu.add(favItem);
        menu.add(hideItem);
        menu.addSeparator();
        menu.add(resetRateItem);
        menu.add(resetSessionItem);

        // Install one mouse handler on the row and every descendant so a click or
        // right-click anywhere on the row works (Swing does not bubble to parents).
        installMouse(this, onClick, menu);
    }

    private void installMouse(Component c, Consumer<Skill> onClick, JPopupMenu menu)
    {
        MouseAdapter ma = new MouseAdapter()
        {
            @Override public void mousePressed(MouseEvent e)  { maybePopup(e, menu); }
            @Override public void mouseReleased(MouseEvent e) { maybePopup(e, menu); }

            @Override public void mouseClicked(MouseEvent e)
            {
                if (SwingUtilities.isLeftMouseButton(e) && !e.isPopupTrigger() && onClick != null)
                {
                    onClick.accept(skill);
                }
            }

            @Override public void mouseEntered(MouseEvent e) { setBackground(HOVER_BG); repaint(); }

            @Override public void mouseExited(MouseEvent e)
            {
                Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(),
                        RuneAlyticsXpSkillRow.this);
                if (!contains(p)) { setBackground(CARD_BG); repaint(); }
            }
        };
        c.addMouseListener(ma);
        if (c instanceof java.awt.Container)
        {
            for (Component child : ((java.awt.Container) c).getComponents())
            {
                installMouse(child, onClick, menu);
            }
        }
    }

    private void maybePopup(MouseEvent e, JPopupMenu menu)
    {
        if (e.isPopupTrigger())
        {
            menu.show(e.getComponent(), e.getX(), e.getY());
        }
    }

    Skill getSkill()
    {
        return skill;
    }

    /**
     * Refreshes this row's values. Runs on the EDT.
     *
     * @param activeNow active-session-clock ms (pauses when logged out) used for
     *                  all rate/time calculations
     */
    void update(RuneAlyticsXpSkillState st, long activeNow, boolean hidden, boolean favorite)
    {
        boolean ignoreAfk = config.xpIgnoreAfk();
        long afk = Math.max(1, config.xpAfkTimeout()) * 60_000L;

        // Hidden rows (only shown while "reveal hidden" is on) are dimmed and never
        // marked LIVE, but still update their values.
        hideItem.setText(hidden ? "Unhide skill" : "Hide skill");
        favItem.setText(favorite ? "Unfavorite skill" : "Favorite skill");
        if (starLabel.isVisible() != favorite) starLabel.setVisible(favorite);
        nameLabel.setForeground(hidden ? MUTED : skillColor);
        bar.setAccent(hidden ? DIM_ACCENT : skillColor);

        // LIVE indicator: full for 15s after the last gain, then fades out.
        this.lastGainWallMs = st.getLastGainWallMs();
        this.hiddenNow = hidden;
        applyLiveFade(System.currentTimeMillis());

        levelLabel.setText("Lvl. " + st.displayLevel());
        // True XP-gained value (e.g. 1,441,027), never abbreviated.
        gainedLabel.setText(XpFormat.comma(st.getTotalGained()));

        if (config.xpShowPerHour())
        {
            rateLabel.setText(XpFormat.compactUpper(st.xpPerHour(activeNow, ignoreAfk, afk)) + "/hr");
            rateLabel.setVisible(true);
        }
        else
        {
            rateLabel.setVisible(false);
        }

        boolean showBottom = !config.xpCompactMode();
        bottomRow.setVisible(showBottom);
        if (showBottom)
        {
            bar.setFraction(st.levelProgress());
            infoLabel.setText(buildInfo(st, activeNow, ignoreAfk, afk));
            infoLabel.setVisible(true);
        }
    }

    /**
     * Animation tick (driven by the panel) that fades the LIVE indicator without
     * needing a full data refresh — cheap: it no-ops unless the alpha changed.
     */
    void tickLiveFade(long nowMs)
    {
        applyLiveFade(nowMs);
    }

    /**
     * Recomputes the LIVE dot+text opacity: full for {@link #LIVE_WINDOW_MS} after
     * the last gain, then fading to nothing over {@link #LIVE_FADE_MS}. Hidden rows
     * never show LIVE.
     */
    private void applyLiveFade(long nowMs)
    {
        int alpha;
        if (hiddenNow || lastGainWallMs <= 0L)
        {
            alpha = 0;
        }
        else
        {
            long since = nowMs - lastGainWallMs;
            if (since < LIVE_WINDOW_MS)
            {
                alpha = 255;
            }
            else if (since < LIVE_WINDOW_MS + LIVE_FADE_MS)
            {
                double t = (since - LIVE_WINDOW_MS) / (double) LIVE_FADE_MS;
                alpha = (int) Math.round(255.0 * (1.0 - t));
            }
            else
            {
                alpha = 0;
            }
        }

        if (alpha == lastLiveAlpha) return; // nothing changed — skip the repaint
        lastLiveAlpha = alpha;

        if (alpha <= 0)
        {
            if (liveLabel.isVisible()) liveLabel.setVisible(false);
        }
        else
        {
            liveLabel.setForeground(new Color(
                    XP_GREEN.getRed(), XP_GREEN.getGreen(), XP_GREEN.getBlue(), alpha));
            if (!liveLabel.isVisible()) liveLabel.setVisible(true);
            liveLabel.repaint();
        }
    }

    /** Builds the "time-to-level · xp-to-next" info string for the bottom row. */
    private String buildInfo(RuneAlyticsXpSkillState st, long activeNow, boolean ignoreAfk, long afk)
    {
        long toNext = st.xpToNextLevel();
        if (toNext <= 0) return "maxed";

        String ttl = XpFormat.timeToLevel(st.timeToNextLevelMs(activeNow, ignoreAfk, afk));
        String toNextStr = config.xpShowXpToNext()
                ? XpFormat.compactUpper(toNext) + " to " + (st.displayLevel() + 1)
                : "";

        boolean hasTtl = !"—".equals(ttl);
        if (hasTtl && !toNextStr.isEmpty()) return ttl + "  ·  " + toNextStr;
        if (hasTtl)                          return ttl;
        return toNextStr;
    }

    static String prettyName(Skill skill)
    {
        String n = skill.getName();
        if (n.isEmpty()) return n;
        return Character.toUpperCase(n.charAt(0)) + n.substring(1).toLowerCase();
    }
}

package com.runealytics;

import lombok.Getter;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

/**
 * Per-skill XP session state for the RuneAlytics XP Tracker.
 *
 * <p>One instance is created per skill the moment the first
 * {@link net.runelite.api.events.StatChanged} for that skill is observed after
 * login. That first observation is treated as the <em>baseline</em> — its XP is
 * recorded as {@link #startXp} and no gain is counted, which is how invalid
 * startup XP spikes are ignored.</p>
 *
 * <h2>Timekeeping</h2>
 * All rate math ({@link #xpPerHour}, {@link #actionsPerHour},
 * {@link #timeToNextLevelMs}) works in the <em>active-session clock</em> supplied
 * by {@link RuneAlyticsXpSessionManager}. That clock excludes logged-out time, so
 * XP/hr and time-to-level freeze while the player is logged out and resume on
 * login — the rate is computed purely from time actually spent in-game. When AFK
 * smoothing is enabled, in-game idle beyond the AFK timeout is also excluded.
 *
 * <p>Drop timestamps, the "LIVE" marker and chart sample X-positions use real
 * wall-clock time so "time ago" and the last-hour window stay truthful.</p>
 */
@Getter
class RuneAlyticsXpSkillState
{
    /** Max recent XP drops retained for the detail view. */
    static final int MAX_RECENT_DROPS = 25;
    /** Max trend samples retained per skill (down-sampled when exceeded). */
    static final int MAX_SAMPLES = 120;

    private final Skill skill;

    private final long startXp;
    private final int  startLevel;

    private volatile long currentXp;
    private volatile int  currentLevel;
    private volatile long totalGained;

    /** True once at least one real gain has been recorded. */
    private volatile boolean started;
    /** Active-clock ms of the first real gain. */
    private volatile long firstActiveMs;
    /** Active-clock ms of the most recent real gain. */
    private volatile long lastActiveMs;
    /** Accumulated in-game idle (active-clock ms) beyond the AFK grace window. */
    private volatile long afkPausedMs;

    /** Wall-clock ms of the most recent gain — drives "LIVE" + list ordering. */
    private volatile long lastGainWallMs;

    private volatile int lastDropXp;
    private volatile int actions;

    /** Most-recent-first list of XP drops (amount + wall time). Guarded by {@code this}. */
    private final Deque<XpDrop> recentDrops = new ArrayDeque<>();
    /** Cumulative-gained trend samples (wall time). Guarded by {@code this}. */
    private final List<Sample> samples = new ArrayList<>();
    /** Rolling XP/hr samples (last hour, wall time). Guarded by {@code this}. */
    private final List<Sample> rateHistory = new ArrayList<>();

    RuneAlyticsXpSkillState(Skill skill, long baselineXp)
    {
        this.skill        = skill;
        this.startXp      = baselineXp;
        this.currentXp    = baselineXp;
        this.startLevel   = levelForXp(baselineXp);
        this.currentLevel = this.startLevel;
    }

    // ── Mutation (client thread) ──────────────────────────────────────────────

    /**
     * Records a raw XP observation for this skill.
     *
     * @param newXp     the skill's current total XP
     * @param wallNow   real wall-clock ms
     * @param activeNow active-session-clock ms (excludes logged-out time)
     * @return the positive XP gained, or {@code 0} when not a forward gain.
     */
    synchronized int record(long newXp, long wallNow, long activeNow, boolean ignoreAfk, long afkTimeoutMs)
    {
        int gained = (int) (newXp - currentXp);
        if (gained <= 0)
        {
            if (newXp > currentXp) currentXp = newXp;
            return 0;
        }

        if (!started)
        {
            started       = true;
            firstActiveMs = activeNow;
        }
        else
        {
            long gap = activeNow - lastActiveMs;
            if (gap > afkTimeoutMs) afkPausedMs += (gap - afkTimeoutMs);
        }
        lastActiveMs   = activeNow;
        lastGainWallMs = wallNow;

        currentXp    = newXp;
        currentLevel = levelForXp(newXp);
        totalGained  = currentXp - startXp;
        lastDropXp   = gained;
        actions++;

        recentDrops.addFirst(new XpDrop(gained, wallNow));
        while (recentDrops.size() > MAX_RECENT_DROPS) recentDrops.removeLast();

        samples.add(new Sample(wallNow, totalGained));
        if (samples.size() > MAX_SAMPLES) downSample();

        return gained;
    }

    private void downSample()
    {
        List<Sample> compact = new ArrayList<>(MAX_SAMPLES / 2 + 2);
        for (int i = 0; i < samples.size(); i += 2) compact.add(samples.get(i));
        Sample last = samples.get(samples.size() - 1);
        if (compact.isEmpty() || compact.get(compact.size() - 1) != last) compact.add(last);
        samples.clear();
        samples.addAll(compact);
    }

    // ── Derived stats (EDT-safe reads) ────────────────────────────────────────

    int displayLevel()
    {
        return Math.min(currentLevel, Experience.MAX_REAL_LEVEL);
    }

    boolean hasGains()
    {
        return totalGained > 0L;
    }

    long xpToNextLevel()
    {
        int next = levelForXp(currentXp) + 1;
        if (next > Experience.MAX_VIRT_LEVEL) return 0L;
        return Experience.getXpForLevel(next) - currentXp;
    }

    double levelProgress()
    {
        int lvl = levelForXp(currentXp);
        if (lvl >= Experience.MAX_VIRT_LEVEL) return 1.0;
        long base = Experience.getXpForLevel(lvl);
        long next = Experience.getXpForLevel(lvl + 1);
        if (next <= base) return 1.0;
        double p = (currentXp - base) / (double) (next - base);
        return Math.max(0.0, Math.min(1.0, p));
    }

    /** Active training time (active-clock ms), AFK-adjusted when enabled. */
    long activeMillis(long activeNow, boolean ignoreAfk, long afkTimeoutMs)
    {
        if (!started) return 0L;
        long elapsed = activeNow - firstActiveMs;
        if (elapsed < 0L) elapsed = 0L;
        if (!ignoreAfk) return elapsed;

        long paused = afkPausedMs;
        long idle = activeNow - lastActiveMs;
        if (idle > afkTimeoutMs) paused += (idle - afkTimeoutMs);
        return Math.max(0L, elapsed - paused);
    }

    long xpPerHour(long activeNow, boolean ignoreAfk, long afkTimeoutMs)
    {
        long active = activeMillis(activeNow, ignoreAfk, afkTimeoutMs);
        if (active < 3_000L || totalGained <= 0L) return 0L;
        return totalGained * 3_600_000L / active;
    }

    long actionsPerHour(long activeNow, boolean ignoreAfk, long afkTimeoutMs)
    {
        long active = activeMillis(activeNow, ignoreAfk, afkTimeoutMs);
        if (active < 3_000L || actions <= 0) return 0L;
        return (long) actions * 3_600_000L / active;
    }

    long timeToNextLevelMs(long activeNow, boolean ignoreAfk, long afkTimeoutMs)
    {
        long rate = xpPerHour(activeNow, ignoreAfk, afkTimeoutMs);
        long toNext = xpToNextLevel();
        if (rate <= 0L || toNext <= 0L) return -1L;
        return toNext * 3_600_000L / rate;
    }

    synchronized List<XpDrop> recentDropsSnapshot()
    {
        return new ArrayList<>(recentDrops);
    }

    synchronized List<Sample> samplesSnapshot()
    {
        return samples.isEmpty() ? Collections.emptyList() : new ArrayList<>(samples);
    }

    /** Appends a rolling XP/hr sample (wall X, rate Y) and prunes past {@code windowMs}. */
    synchronized void sampleRate(long wallNow, long activeNow, boolean ignoreAfk,
                                 long afkTimeoutMs, long windowMs)
    {
        rateHistory.add(new Sample(wallNow, xpPerHour(activeNow, ignoreAfk, afkTimeoutMs)));
        long cutoff = wallNow - windowMs;
        rateHistory.removeIf(s -> s.timeMs < cutoff);
        while (rateHistory.size() > MAX_SAMPLES * 3) rateHistory.remove(0);
    }

    synchronized List<Sample> rateHistorySnapshot()
    {
        return rateHistory.isEmpty() ? Collections.emptyList() : new ArrayList<>(rateHistory);
    }

    /** Resets only the XP/hr timing (and rate history), keeping the XP gained. */
    synchronized void resetRate()
    {
        started        = false;
        firstActiveMs  = 0L;
        lastActiveMs   = 0L;
        afkPausedMs    = 0L;
        lastGainWallMs = 0L;
        rateHistory.clear();
    }

    private static int levelForXp(long xp)
    {
        int clamped = (int) Math.min(Math.max(xp, 0L), Experience.MAX_SKILL_XP);
        return Experience.getLevelForXp(clamped);
    }

    // ── Value types ───────────────────────────────────────────────────────────

    static final class XpDrop
    {
        final int  amount;
        final long timeMs;

        XpDrop(int amount, long timeMs)
        {
            this.amount = amount;
            this.timeMs = timeMs;
        }
    }

    static final class Sample
    {
        final long timeMs;
        final long totalGained;

        Sample(long timeMs, long totalGained)
        {
            this.timeMs      = timeMs;
            this.totalGained = totalGained;
        }
    }
}

package com.runealytics;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import java.util.List;

/**
 * Immutable snapshot of the current account's XP session, ready to POST to the
 * RuneAlytics website ({@code /api/plugin/xp/session}).
 *
 * <p>Carries <em>only</em> the currently logged-in account's session data — it is
 * built by {@link RuneAlyticsXpSessionManager#buildPayload} which is scoped to a
 * single account key, so no other local RuneLite profile's XP can leak in.</p>
 *
 * <p>Contains no auth token — the token is attached as a {@code Bearer} header by
 * {@link RunealyticsApiClient#syncXpSession} so it never ends up in a logged
 * payload body.</p>
 */
final class RuneAlyticsXpSyncPayload
{
    /** Normalized RuneScape username of the account this session belongs to. */
    final String username;
    /** RuneLite rsprofile / account identifier, if resolvable ({@code null} otherwise). */
    final String profileId;
    final String gameMode;
    final String accountType;

    /** Session start (epoch seconds) — the session key on the server. */
    final long sessionStartSec;
    /** Active session duration in seconds (excludes logged-out time). */
    final long durationSec;
    /** Total XP gained across all skills this session. */
    final long totalXp;
    /** {@code true} for the final post of a session (logout / shutdown / reset). */
    final boolean ended;

    final List<SkillEntry> skills;

    RuneAlyticsXpSyncPayload(String username, String profileId, String gameMode, String accountType,
                             long sessionStartSec, long durationSec, long totalXp,
                             boolean ended, List<SkillEntry> skills)
    {
        this.username        = username;
        this.profileId       = profileId;
        this.gameMode        = gameMode;
        this.accountType     = accountType;
        this.sessionStartSec = sessionStartSec;
        this.durationSec     = durationSec;
        this.totalXp         = totalXp;
        this.ended           = ended;
        this.skills          = skills;
    }

    /** Per-skill line item in the payload. */
    static final class SkillEntry
    {
        final String skill;      // lowercase skill name
        final long   xpGained;   // gained this session
        final long   xpPerHour;
        final int    level;      // current level
        final long   currentXp;  // current total XP

        SkillEntry(String skill, long xpGained, long xpPerHour, int level, long currentXp)
        {
            this.skill     = skill;
            this.xpGained  = xpGained;
            this.xpPerHour = xpPerHour;
            this.level     = level;
            this.currentXp = currentXp;
        }
    }

    /**
     * Serializes to the JSON body expected by {@code POST /api/plugin/xp/session}:
     *
     * <pre>
     * {
     *   "username": "playername",
     *   "session_start": 1720000000,
     *   "duration_sec": 3600,
     *   "total_xp": 45000,
     *   "ended": true,
     *   "game_mode": "regular",
     *   "account_type": "normal",
     *   "profile_id": "abc123",
     *   "skills": [
     *     { "skill": "mining", "xp_gained": 12000, "xp_per_hour": 12000, "level": 70, "current_xp": 755000 }
     *   ]
     * }
     * </pre>
     */
    JsonObject toJson()
    {
        JsonObject root = new JsonObject();
        root.addProperty("username",     username);
        root.addProperty("session_start", sessionStartSec);
        root.addProperty("duration_sec", durationSec);
        root.addProperty("total_xp",     totalXp);
        root.addProperty("ended",        ended);
        root.addProperty("game_mode",    gameMode    != null ? gameMode    : "regular");
        root.addProperty("account_type", accountType != null ? accountType : "normal");
        if (profileId != null && !profileId.isEmpty())
        {
            root.addProperty("profile_id", profileId);
        }

        JsonArray skillsArr = new JsonArray();
        for (SkillEntry e : skills)
        {
            JsonObject s = new JsonObject();
            s.addProperty("skill",       e.skill);
            s.addProperty("xp_gained",   e.xpGained);
            s.addProperty("xp_per_hour", e.xpPerHour);
            s.addProperty("level",       e.level);
            s.addProperty("current_xp",  e.currentXp);
            skillsArr.add(s);
        }
        root.add("skills", skillsArr);

        return root;
    }
}

