/**
 * Per-skill accent colours for the XP Tracker, matching the RuneAlytics palette.
 *
 * <p>Keyed by lowercase skill name so it tolerates RuneLite {@link Skill} enum
 * differences across client versions (e.g. skills that may not exist yet simply
 * fall through to the neutral default).</p>
 */
final class SkillColors
{
    private static final Color DEFAULT = new Color(148, 163, 184); // slate

    private static final Map<String, Color> BY_NAME = new HashMap<>();

    static
    {
        put("attack",       0xef4444);
        put("strength",     0x22c55e);
        put("defence",      0x3b82f6);
        put("hitpoints",    0xf87171);
        put("ranged",       0x84cc16);
        put("prayer",       0xf59e0b);
        put("magic",        0xa855f7);
        put("cooking",      0xfb923c);
        put("woodcutting",  0x65a30d);
        put("fletching",    0x10b981);
        put("fishing",      0x0ea5e9);
        put("firemaking",   0xf97316);
        put("crafting",     0x8b5cf6);
        put("smithing",     0x6b7280);
        put("mining",       0x94a3b8);
        put("herblore",     0x16a34a);
        put("agility",      0x06b6d4);
        put("thieving",     0x7c3aed);
        put("slayer",       0xdc2626);
        put("farming",      0x4ade80);
        put("runecraft",    0x60a5fa);
        put("hunter",       0xd97706);
        put("construction", 0x92400e);
        put("sailing",      0x0891b2);
    }

    private SkillColors() {}

    private static void put(String name, int rgb)
    {
        BY_NAME.put(name, new Color(rgb));
    }

    /** Accent colour for a skill; a neutral slate for anything unmapped. */
    static Color of(Skill skill)
    {
        if (skill == null) return DEFAULT;
        Color c = BY_NAME.get(skill.getName().toLowerCase());
        return c != null ? c : DEFAULT;
    }
}

package com.runealytics;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

/**
 * Per-skill training economics for the XP Tracker: GP made (outputs produced),
 * GP spent (supplies consumed) and the resulting profit, kept per session and
 * per calendar day — valued <b>both</b> at Grand Exchange prices and at high
 * alchemy prices, so the detail panel can show a GE profit section and a
 * separate alch section.
 *
 * <p>Fed by {@code RuneAlyticsPlugin}'s skilling inventory diff — the same
 * attribution window that ties item changes to the skill that just gained XP —
 * with item values resolved on the client thread before they reach this class.
 * Owned by {@link RuneAlyticsXpSessionManager}, which scopes it to the active
 * account exactly like the XP session itself.</p>
 *
 * <h2>Account scoping</h2>
 * {@link #setAccount(String)} clears the session state and loads that
 * account's persisted "today" totals; data recorded before an account is set
 * is dropped. Day totals persist through the injected {@link Store}
 * (production: RuneLite's ConfigManager) and reset at local midnight.
 *
 * <h2>Threading</h2>
 * {@link #record} runs on the client thread; snapshots are read from the EDT.
 * All public methods are synchronized and snapshots are deep copies.
 *
 * <p>Pure Java apart from Gson — fully unit-testable without a client.</p>
 */
class SkillEconomyTracker
{
    /** Throttle between persisting the day state to the store. */
    private static final long PERSIST_INTERVAL_MS = 10_000L;

    /** Max distinct supply items kept per skill (session and day alike). */
    private static final int MAX_ITEMS_PER_SKILL = 64;

    // ── Collaborator seams ────────────────────────────────────────────────────

    /** Minimal key/value persistence seam (production: ConfigManager-backed). */
    interface Store
    {
        String get(String key);

        void put(String key, String value);
    }

    // ── Value types ───────────────────────────────────────────────────────────

    /** One item stack with its per-item GE and high-alch values already resolved. */
    static final class ValuedStack
    {
        final int    itemId;
        final String itemName;
        final int    quantity;
        final long   geEach;
        final long   alchEach;

        ValuedStack(int itemId, String itemName, int quantity, long geEach, long alchEach)
        {
            this.itemId   = itemId;
            this.itemName = itemName;
            this.quantity = quantity;
            this.geEach   = geEach;
            this.alchEach = alchEach;
        }
    }

    /** Aggregated flow of one item: quantity consumed plus its GE / alch GP. */
    static final class ItemFlow
    {
        @SerializedName("i") final int    itemId;
        @SerializedName("n") String itemName;
        @SerializedName("q") long   quantity;
        @SerializedName("g") long   geGp;
        @SerializedName("a") long   alchGp;

        ItemFlow(int itemId, String itemName, long quantity, long geGp, long alchGp)
        {
            this.itemId   = itemId;
            this.itemName = itemName;
            this.quantity = quantity;
            this.geGp     = geGp;
            this.alchGp   = alchGp;
        }

        int    getItemId()   { return itemId; }
        String getItemName() { return itemName; }
        long   getQuantity() { return quantity; }
        long   getGeGp()     { return geGp; }
        long   getAlchGp()   { return alchGp; }
    }

    /** Immutable read model for the UI. Supplies are sorted by GE GP descending. */
    static final class Snapshot
    {
        final long sessionOutputGe;
        final long sessionInputGe;
        final long sessionOutputAlch;
        final long sessionInputAlch;
        final long todayOutputGe;
        final long todayInputGe;
        final long todayOutputAlch;
        final long todayInputAlch;
        final List<ItemFlow> sessionSupplies;
        final List<ItemFlow> todaySupplies;

        Snapshot(long sessionOutputGe, long sessionInputGe,
                 long sessionOutputAlch, long sessionInputAlch,
                 long todayOutputGe, long todayInputGe,
                 long todayOutputAlch, long todayInputAlch,
                 List<ItemFlow> sessionSupplies, List<ItemFlow> todaySupplies)
        {
            this.sessionOutputGe   = sessionOutputGe;
            this.sessionInputGe    = sessionInputGe;
            this.sessionOutputAlch = sessionOutputAlch;
            this.sessionInputAlch  = sessionInputAlch;
            this.todayOutputGe     = todayOutputGe;
            this.todayInputGe      = todayInputGe;
            this.todayOutputAlch   = todayOutputAlch;
            this.todayInputAlch    = todayInputAlch;
            this.sessionSupplies   = sessionSupplies;
            this.todaySupplies     = todaySupplies;
        }

        long sessionProfitGe()   { return sessionOutputGe - sessionInputGe; }
        long sessionProfitAlch() { return sessionOutputAlch - sessionInputAlch; }
        long todayProfitGe()     { return todayOutputGe - todayInputGe; }
        long todayProfitAlch()   { return todayOutputAlch - todayInputAlch; }

        boolean hasSessionData()
        {
            return sessionOutputGe != 0 || sessionInputGe != 0
                    || sessionOutputAlch != 0 || sessionInputAlch != 0
                    || !sessionSupplies.isEmpty();
        }

        boolean hasTodayData()
        {
            return todayOutputGe != 0 || todayInputGe != 0
                    || todayOutputAlch != 0 || todayInputAlch != 0
                    || !todaySupplies.isEmpty();
        }

        static final Snapshot EMPTY = new Snapshot(0, 0, 0, 0, 0, 0, 0, 0,
                Collections.emptyList(), Collections.emptyList());
    }

    /** Mutable per-skill totals (used for both session and day scopes). */
    private static final class SkillEconomy
    {
        @SerializedName("outGe") long outputGe;
        @SerializedName("inGe")  long inputGe;
        @SerializedName("outHa") long outputAlch;
        @SerializedName("inHa")  long inputAlch;
        @SerializedName("items") Map<Integer, ItemFlow> consumed = new LinkedHashMap<>();
    }

    /** Persisted day payload: date + per-skill totals. */
    private static final class DayState
    {
        @SerializedName("date")   String date;
        @SerializedName("skills") Map<String, SkillEconomy> skills = new HashMap<>();
    }

    // ── State ─────────────────────────────────────────────────────────────────

    private final Store store;
    private final Gson gson;
    private final Supplier<String> dayKeySupplier;

    private String accountKey;
    private final Map<String, SkillEconomy> session = new HashMap<>();
    private DayState day = new DayState();
    private long lastPersistMs;
    private boolean dayDirty;

    SkillEconomyTracker(Store store, Gson gson)
    {
        this(store, gson, () -> LocalDate.now().toString());
    }

    /** Test seam: deterministic day key. */
    SkillEconomyTracker(Store store, Gson gson, Supplier<String> dayKeySupplier)
    {
        this.store          = store;
        this.gson           = gson;
        this.dayKeySupplier = dayKeySupplier;
    }

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    /**
     * Scopes the tracker to an account: clears session totals and loads that
     * account's persisted day totals. No-op when the account is unchanged.
     */
    synchronized void setAccount(String acct)
    {
        if (acct == null || acct.equals(accountKey)) return;

        flushLocked();
        accountKey = acct;
        session.clear();
        day = loadDay(acct);
    }

    /** Clears the session totals (panel Reset button); day totals are kept. */
    synchronized void resetSession()
    {
        session.clear();
    }

    /** Clears one skill's session totals; its day totals are kept. */
    synchronized void resetSkill(String skillKey)
    {
        if (skillKey != null) session.remove(skillKey);
    }

    /** Persists pending day totals immediately (logout / shutdown). */
    synchronized void flush()
    {
        flushLocked();
    }

    // ── Ingest (client thread) ────────────────────────────────────────────────

    /**
     * Records one skilling inventory delta: items produced (entered the
     * inventory) and supplies consumed (left it), both already valued.
     * Ignored until an account has been set.
     */
    synchronized void record(String skillKey, List<ValuedStack> produced,
                             List<ValuedStack> consumed, long nowMs)
    {
        if (accountKey == null || skillKey == null) return;
        boolean hasProduced = produced != null && !produced.isEmpty();
        boolean hasConsumed = consumed != null && !consumed.isEmpty();
        if (!hasProduced && !hasConsumed) return;

        rollDayIfNeeded();

        SkillEconomy sess = session.computeIfAbsent(skillKey, k -> new SkillEconomy());
        SkillEconomy today = day.skills.computeIfAbsent(skillKey, k -> new SkillEconomy());

        if (hasProduced)
        {
            for (ValuedStack v : produced)
            {
                long ge   = v.geEach * v.quantity;
                long alch = v.alchEach * v.quantity;
                sess.outputGe    += ge;
                sess.outputAlch  += alch;
                today.outputGe   += ge;
                today.outputAlch += alch;
            }
        }

        if (hasConsumed)
        {
            for (ValuedStack v : consumed)
            {
                long ge   = v.geEach * v.quantity;
                long alch = v.alchEach * v.quantity;
                sess.inputGe    += ge;
                sess.inputAlch  += alch;
                today.inputGe   += ge;
                today.inputAlch += alch;
                addConsumed(sess.consumed,  v, ge, alch);
                addConsumed(today.consumed, v, ge, alch);
            }
        }

        dayDirty = true;
        if (nowMs - lastPersistMs > PERSIST_INTERVAL_MS)
        {
            lastPersistMs = nowMs;
            flushLocked();
        }
    }

    private static void addConsumed(Map<Integer, ItemFlow> map, ValuedStack v, long ge, long alch)
    {
        ItemFlow flow = map.get(v.itemId);
        if (flow == null)
        {
            if (map.size() >= MAX_ITEMS_PER_SKILL) return; // bounded; drop the long tail
            map.put(v.itemId, new ItemFlow(v.itemId, v.itemName, v.quantity, ge, alch));
            return;
        }
        flow.quantity += v.quantity;
        flow.geGp     += ge;
        flow.alchGp   += alch;
        if (flow.itemName == null || flow.itemName.isEmpty()) flow.itemName = v.itemName;
    }

    // ── Reads (EDT) ───────────────────────────────────────────────────────────

    /** Deep-copied snapshot for one skill; {@link Snapshot#EMPTY} when nothing recorded. */
    synchronized Snapshot snapshot(String skillKey)
    {
        if (skillKey == null) return Snapshot.EMPTY;
        rollDayIfNeeded();

        SkillEconomy sess = session.get(skillKey);
        SkillEconomy today = day.skills.get(skillKey);
        if (sess == null && today == null) return Snapshot.EMPTY;

        return new Snapshot(
                sess != null ? sess.outputGe : 0L,
                sess != null ? sess.inputGe : 0L,
                sess != null ? sess.outputAlch : 0L,
                sess != null ? sess.inputAlch : 0L,
                today != null ? today.outputGe : 0L,
                today != null ? today.inputGe : 0L,
                today != null ? today.outputAlch : 0L,
                today != null ? today.inputAlch : 0L,
                copySorted(sess != null ? sess.consumed : null),
                copySorted(today != null ? today.consumed : null));
    }

    private static List<ItemFlow> copySorted(Map<Integer, ItemFlow> map)
    {
        if (map == null || map.isEmpty()) return Collections.emptyList();
        List<ItemFlow> list = new ArrayList<>(map.size());
        for (ItemFlow f : map.values())
        {
            list.add(new ItemFlow(f.itemId, f.itemName, f.quantity, f.geGp, f.alchGp));
        }
        list.sort(Comparator.comparingLong(ItemFlow::getGeGp).reversed()
                .thenComparing(ItemFlow::getItemId));
        return list;
    }

    // ── Day persistence ───────────────────────────────────────────────────────

    private void rollDayIfNeeded()
    {
        String today = dayKeySupplier.get();
        if (!today.equals(day.date))
        {
            day = new DayState();
            day.date = today;
            dayDirty = true;
        }
    }

    private DayState loadDay(String acct)
    {
        String today = dayKeySupplier.get();
        try
        {
            String json = store.get(dayDataKey(acct));
            if (json != null && !json.isEmpty())
            {
                DayState loaded = gson.fromJson(json, DayState.class);
                if (loaded != null && today.equals(loaded.date))
                {
                    if (loaded.skills == null) loaded.skills = new HashMap<>();
                    return loaded;
                }
            }
        }
        catch (Exception e)
        {
            // Malformed/stale payload — start the day fresh rather than fail.
        }
        DayState fresh = new DayState();
        fresh.date = today;
        return fresh;
    }

    private void flushLocked()
    {
        if (!dayDirty || accountKey == null) return;
        try
        {
            if (day.date == null) day.date = dayKeySupplier.get();
            store.put(dayDataKey(accountKey), gson.toJson(day));
            dayDirty = false;
        }
        catch (Exception e)
        {
            // Persistence must never break tracking; retry on the next flush.
        }
    }

    private static String dayDataKey(String acct)
    {
        return "xpEconDay_" + (acct == null ? "unknown" : acct.replaceAll("[^a-z0-9]", "_"));
    }
}

package com.runealytics;

/**
 * Immutable snapshot of account/session context for a synchronization operation.
 * Protects against stale asynchronous results from overwriting a different account's
 * or a different session's data after logout, login, or account switch.
 *
 * Each async task captures this at start time and validates it before applying results.
 */
public final class SyncContext
{
    private final String username;
    private final String accountHash;
    private final long sessionGeneration;
    private final long capturedAtMs;
    private final String reason;

    public SyncContext(String username, String accountHash, long sessionGeneration, String reason)
    {
        this.username = username;
        this.accountHash = accountHash;
        this.sessionGeneration = sessionGeneration;
        this.capturedAtMs = System.currentTimeMillis();
        this.reason = reason;
    }

    public String getUsername() { return username; }
    public String getAccountHash() { return accountHash; }
    public long getSessionGeneration() { return sessionGeneration; }
    public long getCapturedAtMs() { return capturedAtMs; }
    public String getReason() { return reason; }

    /**
     * Check if this context is still valid given current state.
     * Returns false if account has switched or plugin has logged out.
     */
    public boolean isStillValid(RuneAlyticsState currentState)
    {
        return currentState != null
            && currentState.isLoggedIn()
            && currentState.isVerified()
            && username != null
            && username.equals(currentState.getVerifiedUsername())
            && sessionGeneration == currentState.getSessionGeneration();
    }

    @Override
    public String toString()
    {
        return String.format("SyncContext{user='%s' hash='%s' gen=%d reason='%s' age=%dms}",
            username, accountHash, sessionGeneration, reason,
            System.currentTimeMillis() - capturedAtMs);
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

/**
 * Coordinates synchronization operations to ensure:
 * 1. Only one full loot sync runs at a time
 * 2. Additional requests during a sync are coalesced (not silently lost)
 * 3. The strongest priority level is honored
 * 4. Exception-safe slot release
 */
@Slf4j
public class SyncCoordinator
{
    private volatile boolean syncInProgress = false;
    private volatile SyncRequest pendingRequest = null;

    /**
     * Attempt to start a synchronization.
     * If one is already running, marks it as pending and returns false.
     * Returns true if the caller should proceed with the sync.
     */
    public synchronized boolean tryStartSync(SyncRequest request)
    {
        if (!syncInProgress)
        {
            syncInProgress = true;
            pendingRequest = null;
            log.debug("[Sync] Starting: {}", request);
            return true;
        }
        else
        {
            // Sync already running — coalesce the pending request
            if (pendingRequest == null)
            {
                pendingRequest = request;
                log.debug("[Sync] Queuing pending: {}", request);
            }
            else
            {
                SyncRequest merged = pendingRequest.mergeWith(request);
                pendingRequest = merged;
                log.debug("[Sync] Coalesced request: {} + {} -> {}",
                    pendingRequest, request, merged);
            }
            return false;
        }
    }

    /**
     * Release the sync slot. If a request was pending, return it.
     * Must be called in a finally block after sync completes.
     */
    public synchronized SyncRequest endSync()
    {
        syncInProgress = false;
        SyncRequest pending = pendingRequest;
        pendingRequest = null;
        if (pending != null)
        {
            log.debug("[Sync] Releasing slot with pending: {}", pending);
        }
        return pending;
    }

    /**
     * Get the current state for UI display.
     */
    public synchronized boolean isSyncRunning()
    {
        return syncInProgress;
    }

    /**
     * Get pending request without clearing it (for UI updates).
     */
    public synchronized SyncRequest getPendingRequest()
    {
        return pendingRequest;
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.*;

/**
 * Factory for creating a dedicated executor for loot sync operations.
 *
 * <p>The sync executor is separate from RuneLite's shared executor pool,
 * ensuring that long-running sync I/O (file reads, network requests) cannot
 * starve other plugin tasks. Uses a single background thread to serialize
 * syncs (they already serialize via SyncCoordinator, so a single-thread pool
 * is sufficient and more efficient).</p>
 *
 * <p>Thread name is "RuneAlytics-Sync" for easy identification in logs and
 * thread dumps.</p>
 */
@Slf4j
public class SyncExecutorFactory
{
    /**
     * Creates a dedicated single-thread scheduled executor for loot syncs.
     *
     * @return a ScheduledExecutorService with one worker thread
     */
    public static ScheduledExecutorService createSyncExecutor()
    {
        ThreadFactory threadFactory = r -> {
            Thread t = new Thread(r, "RuneAlytics-Sync");
            t.setDaemon(true);
            return t;
        };

        ScheduledExecutorService executor = Executors.newScheduledThreadPool(1, threadFactory);
        log.debug("[sync-executor] Created dedicated sync executor");
        return executor;
    }

    /**
     * Shuts down the given sync executor gracefully.
     * Waits up to 5 seconds for pending tasks to complete.
     *
     * @param executor the executor to shut down
     */
    public static void shutdown(ScheduledExecutorService executor)
    {
        if (executor == null) return;

        executor.shutdown();
        try
        {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS))
            {
                log.debug("[sync-executor] Sync executor did not terminate in 5s, forcing shutdown");
                executor.shutdownNow();
            }
            log.debug("[sync-executor] Sync executor shut down");
        }
        catch (InterruptedException e)
        {
            log.debug("[sync-executor] Interrupted while shutting down sync executor: {}", e.getMessage());
            executor.shutdownNow();
        }
    }
}

package com.runealytics;

/**
 * Represents a synchronization request with priority and merge semantics.
 * Used by SyncCoordinator to coalesce multiple requests into a single operation.
 */
public final class SyncRequest
{
    public enum Priority
    {
        /** User explicitly clicked Sync button - highest priority */
        MANUAL(3),
        /** Logout - special case, usually lightweight upload-only */
        LOGOUT(2),
        /** Automatic post-login reconciliation */
        LOGIN(1),
        /** Automatic periodic/heartbeat-related sync */
        AUTO(0);

        public final int level;
        Priority(int level) { this.level = level; }
    }

    private final Priority priority;
    private final boolean fullReconcile;
    private final String reason;
    private final long createdAtMs;

    public SyncRequest(Priority priority, boolean fullReconcile, String reason)
    {
        this.priority = priority;
        this.fullReconcile = fullReconcile;
        this.reason = reason;
        this.createdAtMs = System.currentTimeMillis();
    }

    public Priority getPriority() { return priority; }
    public boolean isFullReconcile() { return fullReconcile; }
    public String getReason() { return reason; }
    public long getCreatedAtMs() { return createdAtMs; }
    public long getAgeMs() { return System.currentTimeMillis() - createdAtMs; }

    /**
     * Merge this request with another pending request.
     * The result satisfies the requirements of both.
     */
    public SyncRequest mergeWith(SyncRequest other)
    {
        if (other == null) return this;

        Priority resultPriority = this.priority.level > other.priority.level
            ? this.priority
            : other.priority;

        boolean resultFull = this.fullReconcile || other.fullReconcile;

        String resultReason = this.reason + " + " + other.reason;

        return new SyncRequest(resultPriority, resultFull, resultReason);
    }

    @Override
    public String toString()
    {
        return String.format("SyncRequest{priority=%s full=%s reason='%s' age=%dms}",
            priority, fullReconcile, reason, getAgeMs());
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

/**
 * Timeout/watchdog mechanism for long-running sync operations.
 *
 * <p>Tracks the start time of a sync operation and provides methods to check
 * whether the operation has exceeded a timeout threshold. This helps detect
 * stalled or hung sync operations and allows graceful recovery.</p>
 *
 * <p>The watchdog does NOT automatically interrupt or cancel operations — it
 * only detects and reports timeout conditions. Callers must check
 * {@link #hasTimedOut()} periodically during long operations and take
 * appropriate action.</p>
 */
@Slf4j
public class SyncWatchdog
{
    /** Maximum time a sync operation is allowed to run (milliseconds). */
    private static final long SYNC_TIMEOUT_MS = 30_000; // 30 seconds

    private final long startTimeMs;

    public SyncWatchdog()
    {
        this.startTimeMs = System.currentTimeMillis();
    }

    /**
     * @return {@code true} if the watchdog has detected a timeout
     */
    public boolean hasTimedOut()
    {
        long elapsedMs = System.currentTimeMillis() - startTimeMs;
        return elapsedMs > SYNC_TIMEOUT_MS;
    }

    /**
     * @return elapsed time since sync start (milliseconds)
     */
    public long getElapsedMs()
    {
        return System.currentTimeMillis() - startTimeMs;
    }

    /**
     * @return remaining time before timeout (milliseconds), or 0 if already timed out
     */
    public long getRemainingMs()
    {
        long remaining = SYNC_TIMEOUT_MS - getElapsedMs();
        return Math.max(0, remaining);
    }

    /**
     * Logs a warning if elapsed time is significant (> 15 seconds).
     * Useful for detecting slow syncs before they timeout.
     */
    public void logWarningIfSlow()
    {
        long elapsed = getElapsedMs();
        if (elapsed > 15_000) // 15 seconds
        {
            log.debug("[watchdog] Sync operation running slowly: {}ms elapsed", elapsed);
        }
    }
}

package com.runealytics;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.ConcurrentHashMap;

/**
 * Caches the results of loot tracker merges, invalidating when RuneLite
 * tracker files are detected to have changed (via lastModifiedTime).
 *
 * <p>When syncing, we merge data from three sources (local, RuneLite, website).
 * If the RuneLite tracker file hasn't been modified since the last merge,
 * we can skip the expensive file read and merge operations and return the
 * cached result instead.</p>
 *
 * <p>Cache is invalidated when:</p>
 * <ul>
 *   <li>RuneLite tracker files are modified (detected via lastModifiedTime)</li>
 *   <li>Local storage revision changes (new loot added)</li>
 *   <li>Time-to-live (60 seconds) expires</li>
 * </ul>
 */
@Slf4j
public class TrackerResultsCache
{
    /** Cache TTL: 60 seconds. Merge results older than this are discarded. */
    private static final long CACHE_TTL_MS = 60 * 1000;

    private static class CacheEntry
    {
        final long runeLiteFileModified;
        final long localStorageRevision;
        final LootSyncMergeService.MergeResult result;
        final long createdAtMs;

        CacheEntry(long runeLiteFileModified, long localStorageRevision,
                   LootSyncMergeService.MergeResult result)
        {
            this.runeLiteFileModified = runeLiteFileModified;
            this.localStorageRevision = localStorageRevision;
            this.result = result;
            this.createdAtMs = System.currentTimeMillis();
        }

        boolean isExpired()
        {
            return System.currentTimeMillis() - createdAtMs > CACHE_TTL_MS;
        }

        boolean isStale(long newRuneLiteFileModified, long newLocalStorageRevision)
        {
            return runeLiteFileModified != newRuneLiteFileModified
                    || localStorageRevision != newLocalStorageRevision;
        }
    }

    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private volatile long cacheHits = 0;
    private volatile long cacheMisses = 0;

    /**
     * Attempts to retrieve a cached merge result for the given account.
     *
     * @param accountKey normalized account name
     * @param runeLiteFileModified timestamp of RuneLite tracker file last modification
     * @param localStorageRevision local storage revision number
     * @return cached merge result if available, valid, and not expired; null otherwise
     */
    public LootSyncMergeService.MergeResult getIfValid(String accountKey,
                                                       long runeLiteFileModified,
                                                       long localStorageRevision)
    {
        CacheEntry entry = cache.get(accountKey);
        if (entry == null)
        {
            cacheMisses++;
            return null;
        }

        if (entry.isExpired())
        {
            cache.remove(accountKey);
            cacheMisses++;
            log.debug("[cache] Merge result cache MISS (expired): account={}", accountKey);
            return null;
        }

        if (entry.isStale(runeLiteFileModified, localStorageRevision))
        {
            cache.remove(accountKey);
            cacheMisses++;
            log.debug("[cache] Merge result cache MISS (stale): account={}", accountKey);
            return null;
        }

        cacheHits++;
        log.debug("[cache] Merge result cache HIT: account={}", accountKey);
        return entry.result;
    }

    /**
     * Stores a merge result in the cache for the given account.
     *
     * @param accountKey normalized account name
     * @param runeLiteFileModified timestamp of RuneLite tracker file last modification
     * @param localStorageRevision local storage revision number
     * @param result the merge result to cache
     */
    public void put(String accountKey,
                    long runeLiteFileModified,
                    long localStorageRevision,
                    LootSyncMergeService.MergeResult result)
    {
        if (accountKey == null || result == null) return;

        cache.put(accountKey, new CacheEntry(runeLiteFileModified, localStorageRevision, result));
        log.debug("[cache] Merge result cached: account={} rlMod={} revision={}",
                accountKey, runeLiteFileModified, localStorageRevision);
    }

    /**
     * Invalidates the cached merge result for the given account.
     * Called when storage is modified or account switches.
     *
     * @param accountKey the account to invalidate
     */
    public void invalidate(String accountKey)
    {
        if (cache.remove(accountKey) != null)
        {
            log.debug("[cache] Merge result cache invalidated: account={}", accountKey);
        }
    }

    /**
     * Clears the entire cache.
     */
    public void clear()
    {
        int sizeBefore = cache.size();
        cache.clear();
        cacheHits = 0;
        cacheMisses = 0;
        log.debug("[cache] Merge result cache cleared ({} entries)", sizeBefore);
    }

    /**
     * @return cache hit rate as percentage (0-100), or 0 if no queries yet
     */
    public double getHitRate()
    {
        long total = cacheHits + cacheMisses;
        return total > 0 ? (100.0 * cacheHits / total) : 0.0;
    }

    /**
     * @return total number of cache hits
     */
    public long getHits()
    {
        return cacheHits;
    }

    /**
     * @return total number of cache misses
     */
    public long getMisses()
    {
        return cacheMisses;
    }

    /**
     * @return current cache size
     */
    public int size()
    {
        return cache.size();
    }
}

package com.runealytics;

/**
 * Small formatting helpers for the RuneAlytics XP Tracker.
 *
 * <p>Kept dependency-free (no RuneLite / Swing types) so it can be unit-tested
 * and reused from every XP panel component.</p>
 *
 * <ul>
 *   <li>{@link #comma(long)}       — {@code 1,250}</li>
 *   <li>{@link #compact(long)}     — {@code 42.1k} / {@code 1.4m}</li>
 *   <li>{@link #compactUpper(long)}— {@code 42.1K} / {@code 1.40M} (UI accent style)</li>
 *   <li>{@link #duration(long)}    — {@code 02:14:33}</li>
 *   <li>{@link #timeToLevel(long)} — {@code 3h 24m}</li>
 * </ul>
 */
final class XpFormat
{
    private XpFormat() {}

    /** {@code 1250 -> "1,250"} */
    static String comma(long n)
    {
        return String.format("%,d", n);
    }

    /**
     * Lower-case compact form: {@code 1250 -> "1.3k"}, {@code 1_400_000 -> "1.4m"}.
     * Mirrors RuneLite's own short XP style.
     */
    static String compact(long n)
    {
        long a = Math.abs(n);
        if (a < 1_000)         return Long.toString(n);
        if (a < 1_000_000)     return trim(n / 1_000.0) + "k";
        if (a < 1_000_000_000) return trim(n / 1_000_000.0) + "m";
        return trim(n / 1_000_000_000.0) + "b";
    }

    /**
     * Upper-case compact form used for the value accents in the panel mockups:
     * {@code 873_000 -> "873K"}, {@code 8_860_000 -> "8.86M"}, {@code 12_450_000 -> "12.45M"}.
     *
     * <p>Thousands render as a whole-number {@code K}; millions/billions render
     * with two decimals so large session totals stay readable.</p>
     */
    static String compactUpper(long n)
    {
        long a = Math.abs(n);
        if (a < 1_000)         return Long.toString(n);
        if (a < 1_000_000)     return (n / 1_000) + "K";
        if (a < 1_000_000_000) return String.format("%.2fM", n / 1_000_000.0);
        return String.format("%.2fB", n / 1_000_000_000.0);
    }

    /** Drops a trailing {@code .0} so {@code 42.0 -> "42"} but {@code 42.1 -> "42.1"}. */
    private static String trim(double v)
    {
        if (v == Math.floor(v) && !Double.isInfinite(v))
        {
            return Long.toString((long) v);
        }
        return String.format("%.1f", v);
    }

    /** Milliseconds -> {@code "02:14:33"} (always HH:MM:SS, hours uncapped). */
    static String duration(long ms)
    {
        if (ms < 0) ms = 0;
        long totalSec = ms / 1_000L;
        long h = totalSec / 3_600L;
        long m = (totalSec % 3_600L) / 60L;
        long s = totalSec % 60L;
        return String.format("%02d:%02d:%02d", h, m, s);
    }

    /**
     * Milliseconds -> human "time to level" string: {@code "3h 24m"}, {@code "24m 10s"},
     * {@code "45s"}. Returns {@code "—"} (em dash) for unknown / non-positive input.
     */
    static String timeToLevel(long ms)
    {
        if (ms <= 0) return "—";
        long totalSec = ms / 1_000L;
        long h = totalSec / 3_600L;
        long m = (totalSec % 3_600L) / 60L;
        long s = totalSec % 60L;

        if (h >= 100) return ">99h";
        if (h > 0)    return h + "h " + m + "m";
        if (m > 0)    return m + "m " + s + "s";
        return s + "s";
    }

    /**
     * Short "time ago" label for recent XP drops: {@code "just now"},
     * {@code "3 min ago"}, {@code "2h ago"}.
     */
    static String ago(long elapsedMs)
    {
        if (elapsedMs < 0) elapsedMs = 0;
        long sec = elapsedMs / 1_000L;
        if (sec < 5)   return "just now";
        if (sec < 60)  return sec + "s ago";
        long min = sec / 60L;
        if (min < 60)  return min + " min ago";
        long h = min / 60L;
        return h + "h ago";
    }
}

package com.runealytics;

import javax.swing.JComponent;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/**
 * Small rounded progress bar with a blue→green XP accent, matching the
 * RuneAlytics XP Tracker theme. Repaints only when the fraction actually
 * changes, so it is cheap to poll from the panel's refresh timer.
 */
class XpProgressBar extends JComponent
{
    private static final Color TRACK   = new Color(38, 44, 62);
    private static final Color FILL_LO = new Color(88, 132, 240);   // blue
    private static final Color FILL_HI = new Color(105, 220, 140);  // green

    private double fraction = 0.0;
    /** Optional solid accent (per-skill colour); when null the blue→green blend is used. */
    private Color accent = null;

    XpProgressBar()
    {
        setOpaque(false);
        Dimension d = new Dimension(120, 6);
        setPreferredSize(d);
        setMinimumSize(new Dimension(20, 6));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 6));
    }

    /** Sets a solid fill colour (e.g. the skill's accent). Pass {@code null} to restore the blend. */
    void setAccent(Color c)
    {
        if (java.util.Objects.equals(accent, c)) return;
        accent = c;
        repaint();
    }

    /** Sets the fill fraction (0..1). No-op repaint when unchanged. */
    void setFraction(double f)
    {
        double clamped = Math.max(0.0, Math.min(1.0, f));
        if (Math.abs(clamped - fraction) < 0.0005) return;
        fraction = clamped;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int w = getWidth();
            int h = getHeight();
            int arc = h;

            g2.setColor(TRACK);
            g2.fillRoundRect(0, 0, w, h, arc, arc);

            int fw = (int) Math.round(w * fraction);
            if (fw > 0)
            {
                // Use the per-skill accent when set, otherwise blend blue→green.
                Color fill = (accent != null) ? accent : blend(FILL_LO, FILL_HI, fraction);
                g2.setColor(fill);
                g2.fillRoundRect(0, 0, Math.max(fw, arc), h, arc, arc);
            }
        }
        finally
        {
            g2.dispose();
        }
    }

    private static Color blend(Color a, Color b, double t)
    {
        t = Math.max(0.0, Math.min(1.0, t));
        int r = (int) Math.round(a.getRed()   + (b.getRed()   - a.getRed())   * t);
        int g = (int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t);
        int bl = (int) Math.round(a.getBlue()  + (b.getBlue()  - a.getBlue())  * t);
        return new Color(r, g, bl);
    }
}

package com.runealytics;

import net.runelite.client.ui.ColorScheme;

import javax.swing.JComponent;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * A skill icon drawn centered on a filled circle so the dark RuneScape skill
 * sprites stay legible against the dark XP Tracker background.
 *
 * <p>The circle uses {@link ColorScheme#MEDIUM_GRAY_COLOR} and the sprite is
 * inset with a little padding.</p>
 */
class XpSkillIcon extends JComponent
{
    private static final Color CIRCLE_BG = ColorScheme.MEDIUM_GRAY_COLOR;

    private final int diameter;
    private final int pad;
    private BufferedImage image;

    XpSkillIcon(int diameter)
    {
        this.diameter = diameter;
        this.pad = Math.max(3, Math.round(diameter * 0.18f));
        Dimension d = new Dimension(diameter, diameter);
        setPreferredSize(d);
        setMinimumSize(d);
        setMaximumSize(d);
        setOpaque(false);
    }

    /** Sets (or clears, with {@code null}) the skill sprite. */
    void setImage(BufferedImage img)
    {
        this.image = img;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

            g2.setColor(CIRCLE_BG);
            g2.fillOval(0, 0, diameter - 1, diameter - 1);

            if (image != null)
            {
                int avail = diameter - pad * 2;
                int iw = image.getWidth();
                int ih = image.getHeight();
                double scale = Math.min(1.0, Math.min(avail / (double) iw, avail / (double) ih));
                int w = (int) Math.round(iw * scale);
                int h = (int) Math.round(ih * scale);
                int x = (diameter - w) / 2;
                int y = (diameter - h) / 2;
                g2.drawImage(image, x, y, w, h, null);
            }
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.runealytics;

import javax.swing.JComponent;
import javax.swing.ToolTipManager;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GradientPaint;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.event.MouseWheelEvent;
import java.awt.geom.GeneralPath;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class XpSparkline extends JComponent
{
    private static final Color GRID = new Color(95, 95, 95, 110);
    private static final Color GOLD_LABEL = new Color(198, 166, 52);
    private static final Color LINE_DEFAULT = new Color(120, 90, 255);
    private static final Color MARKER = new Color(235, 238, 245);
    private static final Color OUTLIER = new Color(255, 190, 80);

    private static final int GRID_LINES = 5;

    private static final long MIN_INCREMENT = 25_000L;
    private static final long MID_INCREMENT = 50_000L;
    private static final long HIGH_INCREMENT = 100_000L;

    private static final long AXIS_REFRESH_MS = 4_000L;
    private static final double OUTLIER_MULTIPLIER = 1.65;
    private static final double ZOOM_STEP = 0.15;
    private static final double MIN_ZOOM = 1.0;
    private static final double MAX_ZOOM = 4.0;

    private Color lineColor = LINE_DEFAULT;
    private List<RuneAlyticsXpSkillState.Sample> samples = java.util.Collections.emptyList();

    private int lastSize = -1;
    private long lastSig = Long.MIN_VALUE;

    private int gPadL, gPlotW;
    private long gT0, gSpan;

    private int hoverIdx = -1;

    private long displayedMaxY = 100_000L;
    private long lastAxisUpdateMs = 0L;
    private double zoom = 1.0;

    XpSparkline()
    {
        setOpaque(false);
        setPreferredSize(new Dimension(200, 90));
        setMinimumSize(new Dimension(120, 60));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 120));

        ToolTipManager.sharedInstance().registerComponent(this);

        addMouseMotionListener(new MouseMotionAdapter()
        {
            @Override public void mouseMoved(MouseEvent e)
            {
                int idx = nearestIndex(e.getX());
                if (idx != hoverIdx)
                {
                    hoverIdx = idx;
                    repaint();
                }
            }
        });

        addMouseWheelListener((MouseWheelEvent e) ->
        {
            if (e.getWheelRotation() < 0)
            {
                zoom = Math.min(MAX_ZOOM, zoom + ZOOM_STEP);
            }
            else
            {
                zoom = Math.max(MIN_ZOOM, zoom - ZOOM_STEP);
            }

            displayedMaxY = calculateVisibleMax(samples);
            repaint();
        });

        addMouseListener(new MouseAdapter()
        {
            @Override public void mouseExited(MouseEvent e)
            {
                if (hoverIdx != -1)
                {
                    hoverIdx = -1;
                    repaint();
                }
            }

            @Override public void mouseClicked(MouseEvent e)
            {
                if (e.getClickCount() >= 2)
                {
                    zoom = 1.0;
                    displayedMaxY = calculateVisibleMax(samples);
                    repaint();
                }
            }
        });
    }

    void setLineColor(Color c)
    {
        Color next = c != null ? c : LINE_DEFAULT;
        if (next.equals(lineColor))
        {
            return;
        }

        lineColor = next;
        repaint();
    }

    void setSamples(List<RuneAlyticsXpSkillState.Sample> s)
    {
        List<RuneAlyticsXpSkillState.Sample> next =
                s != null ? s : java.util.Collections.emptyList();

        samples = next;

        int size = next.size();
        long sig = 0L;

        if (size > 0)
        {
            RuneAlyticsXpSkillState.Sample last = next.get(size - 1);
            sig = last.timeMs * 31L + last.totalGained;
        }

        if (hoverIdx >= size)
        {
            hoverIdx = -1;
        }

        long now = System.currentTimeMillis();
        if (now - lastAxisUpdateMs >= AXIS_REFRESH_MS || displayedMaxY <= 0)
        {
            displayedMaxY = calculateVisibleMax(next);
            lastAxisUpdateMs = now;
        }

        if (size == lastSize && sig == lastSig && hoverIdx < 0)
        {
            return;
        }

        lastSize = size;
        lastSig = sig;
        repaint();
    }

    private int nearestIndex(int mx)
    {
        List<RuneAlyticsXpSkillState.Sample> data = samples;

        if (data.size() < 2 || gSpan <= 0)
        {
            return -1;
        }

        int best = -1;
        int bestDist = Integer.MAX_VALUE;

        for (int i = 0; i < data.size(); i++)
        {
            double fx = (data.get(i).timeMs - gT0) / (double) gSpan;
            int x = gPadL + (int) Math.round(fx * gPlotW);
            int d = Math.abs(x - mx);

            if (d < bestDist)
            {
                bestDist = d;
                best = i;
            }
        }

        return best;
    }

    @Override
    public String getToolTipText(MouseEvent e)
    {
        int idx = nearestIndex(e.getX());

        if (idx < 0 || idx >= samples.size())
        {
            return null;
        }

        RuneAlyticsXpSkillState.Sample s = samples.get(idx);
        String when = XpFormat.ago(System.currentTimeMillis() - s.timeMs);

        return "<html><b>" + XpFormat.compactUpper(s.totalGained) + "</b> xp/hr<br>"
                + "<span style='color:#9aa2b2'>" + when + "</span></html>";
    }

    private long calculateVisibleMax(List<RuneAlyticsXpSkillState.Sample> data)
    {
        if (data == null || data.isEmpty())
        {
            return 100_000L;
        }

        List<Long> values = new ArrayList<>();
        long rawMax = 1L;

        for (RuneAlyticsXpSkillState.Sample s : data)
        {
            long value = Math.max(0L, s.totalGained);
            values.add(value);
            rawMax = Math.max(rawMax, value);
        }

        Collections.sort(values);

        long median = percentile(values, 0.50);
        long p75 = percentile(values, 0.75);
        long p90 = percentile(values, 0.90);

        long stableMax = Math.max(p90, Math.max(median, p75));

        if (rawMax > stableMax * OUTLIER_MULTIPLIER && stableMax > 0)
        {
            stableMax = Math.max(stableMax, p75);
        }
        else
        {
            stableMax = rawMax;
        }

        long zoomedMax = Math.max(25_000L, Math.round(stableMax / zoom));
        long increment = incrementFor(zoomedMax);

        return roundUpToIncrement(zoomedMax, increment);
    }

    static long percentile(List<Long> sorted, double pct)
    {
        if (sorted == null || sorted.isEmpty())
        {
            return 0L;
        }

        int index = (int) Math.floor((sorted.size() - 1) * pct);
        index = Math.max(0, Math.min(sorted.size() - 1, index));

        return sorted.get(index);
    }

    static long incrementFor(long maxValue)
    {
        if (maxValue > 250_000L)
        {
            return HIGH_INCREMENT;
        }

        if (maxValue > 100_000L)
        {
            return MID_INCREMENT;
        }

        return MIN_INCREMENT;
    }

    static long roundUpToIncrement(long value, long increment)
    {
        long top = increment * (GRID_LINES - 1);

        while (top < value)
        {
            top += increment;
        }

        return Math.max(top, increment);
    }

    static String axisLabel(long value)
    {
        if (value >= 1_000_000L)
        {
            double m = value / 1_000_000.0;
            return m == Math.floor(m)
                    ? String.format("%.0fM", m)
                    : String.format("%.1fM", m);
        }

        if (value >= 1_000L)
        {
            return (value / 1_000L) + "k";
        }

        return Long.toString(value);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();

        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

            int w = getWidth();
            int h = getHeight();

            int padL = 6;
            int padR = 6;
            int padT = 6;
            int padB = 6;

            int plotW = Math.max(1, w - padL - padR);
            int plotH = Math.max(1, h - padT - padB);
            int baseY = h - padB;

            List<RuneAlyticsXpSkillState.Sample> data = samples;

            long maxY = displayedMaxY > 0 ? displayedMaxY : calculateVisibleMax(data);
            long increment = Math.max(1L, maxY / (GRID_LINES - 1));

            Font originalFont = g2.getFont();
            Font labelFont = originalFont.deriveFont(Font.BOLD, 7.25f);
            g2.setFont(labelFont);
            FontMetrics fm = g2.getFontMetrics();

            int widestLabel = 0;
            for (int i = 0; i < GRID_LINES; i++)
            {
                widestLabel = Math.max(widestLabel, fm.stringWidth(axisLabel(i * increment)));
            }

            g2.setStroke(new BasicStroke(
                    1f,
                    BasicStroke.CAP_BUTT,
                    BasicStroke.JOIN_BEVEL,
                    0,
                    new float[]{5f, 6f},
                    0
            ));

            for (int i = 0; i < GRID_LINES; i++)
            {
                long value = i * increment;
                double fy = value / (double) maxY;
                int y = padT + (int) Math.round((1.0 - fy) * plotH);

                String label = axisLabel(value);

                int labelX = padL + widestLabel - fm.stringWidth(label);
                int labelY = y - 1;
                int lineStartX = padL + widestLabel + 7;

                if (i == 0)
                {
                    labelY = y - 2;
                }
                else if (i == GRID_LINES - 1)
                {
                    labelY = y + fm.getAscent();
                }

                g2.setColor(GOLD_LABEL);
                g2.drawString(label, labelX, labelY);

                g2.setColor(GRID);
                g2.drawLine(lineStartX, y, w - padR, y);
            }

            g2.setFont(originalFont);

            Color lineCol = lineColor;
            Color fillTop = new Color(lineCol.getRed(), lineCol.getGreen(), lineCol.getBlue(), 80);
            Color fillBot = new Color(lineCol.getRed(), lineCol.getGreen(), lineCol.getBlue(), 0);

            if (data.size() < 2)
            {
                gSpan = 0L;

                g2.setColor(lineCol);
                g2.setStroke(new BasicStroke(2f));
                g2.drawLine(padL, baseY, w - padR, baseY);
                return;
            }

            long t0 = data.get(0).timeMs;
            long t1 = data.get(data.size() - 1).timeMs;
            long span = Math.max(1L, t1 - t0);

            gPadL = padL;
            gPlotW = plotW;
            gT0 = t0;
            gSpan = span;

            GeneralPath line = new GeneralPath();
            Path2D.Float area = new Path2D.Float();

            boolean started = false;
            int lastX = padL;

            for (RuneAlyticsXpSkillState.Sample s : data)
            {
                double fx = (s.timeMs - t0) / (double) span;
                double rawFy = s.totalGained / (double) maxY;
                double fy = Math.min(1.0, rawFy);

                int x = padL + (int) Math.round(fx * plotW);
                int y = padT + (int) Math.round((1.0 - fy) * plotH);

                if (!started)
                {
                    line.moveTo(x, y);
                    area.moveTo(x, baseY);
                    area.lineTo(x, y);
                    started = true;
                }
                else
                {
                    line.lineTo(x, y);
                    area.lineTo(x, y);
                }

                if (rawFy > 1.0)
                {
                    g2.setColor(OUTLIER);
                    g2.fillOval(x - 2, padT - 1, 4, 4);
                }

                lastX = x;
            }

            area.lineTo(lastX, baseY);
            area.closePath();

            g2.setPaint(new GradientPaint(0, padT, fillTop, 0, baseY, fillBot));
            g2.fill(area);

            g2.setColor(lineCol);
            g2.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g2.draw(line);

            if (hoverIdx >= 0 && hoverIdx < data.size())
            {
                RuneAlyticsXpSkillState.Sample s = data.get(hoverIdx);

                double fx = (s.timeMs - t0) / (double) span;
                double fy = Math.min(1.0, s.totalGained / (double) maxY);

                int x = padL + (int) Math.round(fx * plotW);
                int y = padT + (int) Math.round((1.0 - fy) * plotH);

                g2.setColor(new Color(255, 255, 255, 45));
                g2.setStroke(new BasicStroke(1f));
                g2.drawLine(x, padT, x, baseY);

                g2.setColor(lineCol);
                g2.fillOval(x - 3, y - 3, 6, 6);

                g2.setColor(MARKER);
                g2.setStroke(new BasicStroke(1.5f));
                g2.drawOval(x - 3, y - 3, 6, 6);
            }
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.runealytics;

import net.runelite.api.Skill;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Batches XP gains and sends them to the RuneAlytics server every 30 seconds.
 *
 * <h2>Batch window behaviour</h2>
 * <ol>
 *   <li>First call to {@link #onXpGained} opens a 30-second window and schedules
 *       {@link #flushBatch()} via the executor.</li>
 *   <li>All subsequent gains within that window are accumulated in {@link #xpBuffer}
 *       using a simple merge (skill → total gained).</li>
 *   <li>At T+30 s {@link #flushBatch()} drains the buffer atomically and calls
 *       {@link RunealyticsApiClient#syncXpBatch}.</li>
 *   <li>The window flag is reset so the <em>next</em> XP gain opens a fresh window.</li>
 * </ol>
 *
 * <h2>Thread-safety</h2>
 * {@code ConcurrentHashMap.merge} is atomic per-key, so {@link #xpBuffer} is safe
 * for concurrent writes from {@link #onXpGained} (client thread) and reads from
 * {@link #flushBatch()} (executor thread).  {@link #windowOpen} is an
 * {@link AtomicBoolean} so the compare-and-set that opens a new window is race-free.
 *
 * @see RuneAlyticsPlugin#onStatChanged  (calls {@link #onXpGained})
 * @see RuneAlyticsPlugin#shutDown       (calls {@link #flushImmediate})
 */
@Singleton
public class XpTrackerManager
{
    private static final Logger log = LoggerFactory.getLogger(XpTrackerManager.class);

    /** Length of one accumulation window in seconds */
    private static final int BATCH_WINDOW_SECONDS = 30;

    // ── Dependencies ──────────────────────────────────────────────────────────

    /** @see RunealyticsApiClient#syncXpBatch */
    private final RunealyticsApiClient apiClient;
    /** Shared executor injected by RuneLite — never create a new one here */
    private final ScheduledExecutorService executor;

    // ── Buffer ────────────────────────────────────────────────────────────────

    /**
     * Accumulates XP gained per skill within the current 30-second window.
     *
     * <p>Key:   {@link Skill} enum constant (never OVERALL).</p>
     * <p>Value: total XP gained for that skill during the current window.</p>
     *
     * <p>Using {@link ConcurrentHashMap} so both the client thread (writing via
     * {@link #onXpGained}) and the executor thread (reading in {@link #flushBatch})
     * can access it without an explicit lock.</p>
     */
    private final ConcurrentHashMap<Skill, Integer> xpBuffer = new ConcurrentHashMap<>();

    /**
     * {@code true} while a 30-second flush is already scheduled.
     * {@link AtomicBoolean#compareAndSet} guarantees only one window is ever open.
     */
    private final AtomicBoolean windowOpen = new AtomicBoolean(false);

    /**
     * Handle to the pending flush task.
     * Kept so {@link #flushImmediate()} can cancel it on shutdown.
     */
    private volatile ScheduledFuture<?> flushTask;

    // ── Constructor ───────────────────────────────────────────────────────────

    @Inject
    public XpTrackerManager(RunealyticsApiClient apiClient, ScheduledExecutorService executor)
    {
        this.apiClient = apiClient;
        this.executor  = executor;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /**
     * Record a single XP gain event.
     *
     * <p>Call this from {@code RuneAlyticsPlugin.onStatChanged} every time the
     * local player gains XP in a skill.  This method is safe to call from the
     * RuneLite client thread.</p>
     *
     * <p>If no batch window is currently open this will open one and schedule
     * {@link #flushBatch()} to run in {@value #BATCH_WINDOW_SECONDS} seconds.
     * Subsequent calls within the same window just accumulate into the buffer.</p>
     *
     * @param skill     the skill that gained XP (must not be {@link Skill#OVERALL})
     * @param xpGained  the raw XP amount gained this tick (must be &gt; 0)
     */
    public void onXpGained(Skill skill, int xpGained)
    {
        if (xpGained <= 0 || skill == Skill.OVERALL) return;

        // Thread-safe accumulation: atomically adds xpGained to the existing value
        // (or sets it if this is the first gain for this skill in the window).
        xpBuffer.merge(skill, xpGained, Integer::sum);

        // Open a new window on the first gain — compareAndSet is atomic,
        // so only one caller ever transitions false → true and schedules the task.
        if (windowOpen.compareAndSet(false, true))
        {
            log.debug("[XP] Batch window opened — flushing in {}s", BATCH_WINDOW_SECONDS);
            flushTask = executor.schedule(this::flushBatch, BATCH_WINDOW_SECONDS, TimeUnit.SECONDS);
        }
    }

    /**
     * Non-destructive snapshot of XP accumulated in the <em>current</em>
     * 30-second window, for embedding in the live-map heartbeat as a preview.
     *
     * <p>Unlike {@link #flushBatch()}, this does NOT drain {@link #xpBuffer} or
     * touch {@link #windowOpen} — the authoritative 30-second flush to
     * {@code /xp/batch} (via {@link RunealyticsApiClient#syncXpBatch}) is
     * completely unaffected by this method existing or being called. The
     * heartbeat is a read-only passenger on this data, not a second writer.</p>
     *
     * @return skill-name (lowercase) → XP gained so far in the open window;
     *         empty map if no window is currently open
     */
    public Map<String, Integer> peekPendingGains()
    {
        Map<String, Integer> snapshot = new HashMap<>();
        for (Map.Entry<Skill, Integer> e : xpBuffer.entrySet())
        {
            if (e.getValue() != null && e.getValue() > 0)
                snapshot.put(e.getKey().getName().toLowerCase(), e.getValue());
        }
        return snapshot;
    }

    /**
     * Flush any pending XP immediately (e.g. on plugin shutdown or logout).
     *
     * <p>Cancels the scheduled flush task (if any) and calls {@link #flushBatch()}
     * synchronously on the <em>calling</em> thread.  Safe to call from any thread.</p>
     */
    public void flushImmediate()
    {
        // Cancel the 30-second task so it does not double-send
        ScheduledFuture<?> task = flushTask;
        if (task != null && !task.isDone())
        {
            task.cancel(false);
            flushTask = null;
        }

        if (!xpBuffer.isEmpty())
        {
            log.debug("[XP] Immediate flush on shutdown ({} skill(s))", xpBuffer.size());
            flushBatch();
        }
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    /**
     * Drains {@link #xpBuffer}, resets {@link #windowOpen}, and dispatches a
     * single POST to {@code /api/xp/batch}.
     *
     * <p>Runs on the {@link ScheduledExecutorService} thread — never on the
     * RuneLite client thread — so blocking I/O here is safe.</p>
     */
    private void flushBatch()
    {
        // Reset the window flag BEFORE draining the buffer so that any XP events
        // that arrive while we are building `toSend` open a new window rather than
        // being silently dropped.
        windowOpen.set(false);

        if (xpBuffer.isEmpty())
        {
            log.debug("[XP] Flush triggered but buffer is empty — nothing to send");
            return;
        }

        // Drain: remove each skill from the live map so concurrent writes during
        // drain go into a fresh bucket (they will trigger a new window via
        // compareAndSet above because windowOpen is already false).
        // Convert Skill enum keys to lowercase name strings so RunealyticsApiClient
        // has no dependency on the RuneLite API Skill type.
        Map<String, Integer> toSend = new HashMap<>();
        for (Skill skill : Skill.values())
        {
            Integer gained = xpBuffer.remove(skill);
            if (gained != null && gained > 0)
                toSend.put(skill.getName().toLowerCase(), gained);
        }

        if (toSend.isEmpty()) return;

        log.debug("[XP] Sending batch: {} skill(s) — {}",
                toSend.size(),
                toSend.entrySet().stream()
                        .map(e -> e.getKey() + "+" + e.getValue())
                        .reduce((a, b) -> a + ", " + b)
                        .orElse(""));

        apiClient.syncXpBatch(toSend);
    }
}

